(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.8"]={"from":192,"a":[["\u0003ואי מחמת תרעא\u0004 \u0005[ואם מחמת\u0006 שינוי \u0005השער],\u0006 כלומר, מחיר השוק, שאינו קשור לשינוי המטבע \u0003זיל\u0004 \u0005[הוזלו]\u0006 — \u0003לא מנכינן ליה\u0004 \u0005[אין אנו מנכים לו].\u0006","ומקשים: \u0003והא קא שבח\u0004 \u0005[והרי השביח]\u0006 המטבע \u0003לענין נסכא\u0004 \u0005[מטיל\u0006 מתכת הכסף\u0005],\u0006 שאם יתיך את המטבעות ויעשה מהם כסף המחיר עתה גבוה יותר ממה שהיה קודם! \u0003אלא\u0004 צריך לומר שנוהגים בענין זה \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עבדי עובדא בזוזי\u0004 \u0005[עשו מעשה במטבעות]\u0006 של \u0003אגרדמיס טייעא\u0004 \u0005[הערבי]\u0006 \u0003עד עשרה בתמניא\u0004 \u0005[בשמונה],\u0006 ששמונה מטבעות חדשים היו שקולים כנגד עשרה ישנים ושילמו רק שמונה מן החדשים תמורת עשרה ישנים.","\u0003אמר רבה: הזורק מטבע של חבירו לים הגדול\u0004 — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אמר\u0004 \u0005[\u0006יכול הוא \u0005לומר]:\u0006 \u0003הא מנח קמך, אי בעית שקליה\u0004 \u0005[הרי\u0006 הכסף \u0005מונח לפניך, אם אתה רוצה קח אותו].\u0006 \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003ב\u0004מים \u0003צלולין דקא חזי ליה\u0004 \u0005[שהוא רואה אותו],\u0006 \u0003אבל\u0004 במים \u0003עכורין\u0004 ש\u0003לא קחזי ליה\u0004 \u0005[רואה אותו],\u0006 את המטבע — \u0003לא. והני מילי דאדייה אדויי\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005שגלגל אותו],\u0006 את המטבע, ממקום למקום עד שנפל לים, \u0003אבל\u0004 אם \u0003שקליה בידיה\u0004 \u0005[\u0006אם \u0005לקח אותו,\u0006 את המטבע, \u0005בידו]\u0006 וזרק אותו — \u0003מיגזל גזליה\u0004 \u0005[גזל אותו],\u0006 ואז \u0003השבה\u0004 גמורה \u0003בעי מיעבד\u0004 \u0005[צריך לעשות]\u0006 ולהחזיר לו את המטבע לידו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003אין מחללין\u0004 פירות מעשר שני \u0003על מעות שאינן ברשותו, כיצד?\u0004 אם \u0003היו לו מעות בקסטרא\u0004 (מבצר) \u0003או בהר המלך\u0004 (איזור בדרום ארץ ישראל), \u0003או שנפל כיסו\u0004 (ארנקו) \u0003לים הגדול\u0004 — \u0003אין מחללין\u0004 עליהם. משמע שדבר שנפל לים הגדול נחשב כאבוד! \u0003אמר רבה:\u0004 אין זו קושיה, \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר \u0003לענין\u0004 חילול \u0003מעשר\u0004 שני, \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהא הכסף \u0003מצוי בידך\u0004 של הבעלים המחלל את המעשר, \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003\"וצרת הכסף בידך\"\u0004 (דברים יד, כה) \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 אף שאינו אבוד לגמרי.","\u0003ו\u0004עוד \u0003אמר רבה: השף\u0004 (מקלקל צורה) של \u0003מטבע של חבירו\u0004 — \u0003פטור\u0004 מתשלום הנזק, אף שגרם שייפחת ערכו של המטבע \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא עבד\u0004 \u0005[עשה]\u0006 בו \u0003ולא מידי\u0004 \u0005[דבר]\u0006 והסלע נשאר במקומו. \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 דווקא באופן \u0003דמחייה בקורנסא וטרשיה\u0004 \u0005[שהיכה אותו בפטיש ועשה אותו שטוח],\u0006 \u0003אבל\u0004 אם \u0003שייפא בשופינא\u0004 \u0005[שייף אותו בשופין]\u0006 — \u0003חסורי חסריה\u0004 \u0005[חיסר אותו]\u0006 ואז הוא משלם כל מה שהופסד על ידו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: האדון ש\u0003הכהו\u0004 לעבדו \u0003על עינו וסמאה, על אזנו וחרשו\u0004 — \u0003עבד יוצא בהן לחירות.\u0004 אם היכהו \u0003כנגד עינו ו\u0004כתוצאה מכך הוא \u0003אינו רואה, כנגד אזנו ואינו שומע\u0004 — \u0003אין עבד יוצא בהן לחירות.\u0004 ולמדנו מכאן שאף שעשה בו מעשה שאין בו חיסרון ניכר — חייב עליו!","ומשיבים: \u0003רבה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבה:\u0004 בן ש\u0003חרשו לאביו\u0004 — \u0003נהרג\u0004 על כך משום מכה אביו, שחייב כאשר עושה בו חבורה, כיון \u0003שאי אפשר לחרישה\u0004 (לעשיית אדם לחרש) \u0003בלא\u0004 לעשות בתוך כך \u0003חבורה, דטפתא דדמא נפלת ליה באוניה\u0004 \u0005[שטיפת דם נפלה לו באוזנו]\u0006 והיא שגרמה לכך, ולכן מכה באוזן שגרמה לחירשות נחשבת כדבר שיש בו חסרון, אבל הכאה בקורנס אינה מחסירה מן המטבע.","\u0003ו\u0004בענין דומה \u0003אמר רבה: הצורם\u0004 (חותך מעט, שורט) \u0003אוזן פרתו של חבירו\u0004 — \u0003פטור,\u0004 אף שפרה זו אינה ראויה עוד לשמש כקרבן ונפחת ערכה בצרימה זו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003פרה כדקיימא קיימא\u0004 \u0005[כמו ש\u0006היתה עד כה \u0005עומדת\u0006 לשימושים שונים, גם עכשיו היא \u0005עומדת\u0006 לאותם שימושים\u0005],\u0006 ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 בה \u0003ולא מידי\u0004 \u0005[דבר],\u0006 \u0003וכולהו\u0004 \u0005[וכל]\u0006 ה\u0003שוורים לאו לגבי\u0004 \u0005[לא אצל]\u0006 \u0003מזבח\u0004 הם \u0003קיימי\u0004 \u0005[עומדים],\u0006 ולשאר דברים לא נוצר חסרון על ידי הצרימה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003העושה מלאכה במי חטאת\u0004 (מים שמזים על הטמא בטומאת מת כדי לטהרו), או \u0003בפרת חטאת\u0004 (פרה אדומה) ובמלאכה זו פסלם מלשמש עוד למטרתם — \u0003פטור מדיני אדם,\u0004 שהרי לא עשה נזק ניכר, \u0003וחייב בדיני שמים.\u0004 ונדייק מכאן: דווקא \u0003מלאכה הוא\u0004 שפטור בדיני אדם, משום ש\u0003לא מינכר\u0004 \u0005[ניכר]\u0006 \u0003היזיקה\u0004 שעשה בה, \u0003אבל צורם דמינכר\u0004 \u0005[שניכר]\u0006 \u0003היזיקה, הכי נמי דמחייב\u0004 \u0005[כך גם כן\u0006 הריהו \u0005חייב]\u0006 \u0003בדיני אדם!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחייה: \u0003הוא הדין\u0004 ש\u0003אפילו צורם פטור, והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 מה שלא שנה דבר זה אלא דיבר במעשה שאינו ניכר כלל, ש\u0003אפילו מלאכה\u0004 ש\u0003לא מינכר\u0004 \u0005[ניכר]\u0006 \u0003היזיקה חייב בדיני שמים.\u0004","\u0003ו\u0004עוד \u0003אמר רבה\u0004 בענין דומה: \u0003השורף שטרו של חבירו\u0004 — \u0003פטור, דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]\u0006 המזיק: \u0003ניירא קלאי מינך\u0004 \u0005[נייר\u0006 בלבד \u0005שרפתי לך]\u0006 אף שנגרם בכך הפסד גדול לבעל השטר, שאין יכול לגבות בו את חובו מהלווה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רמי בר חמא: היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006"],["\u0003אי דאיכא סהדי דידעי מאי הוה בשטרא\u0004 \u0005[אם שיש עדים שיודעים מה היה\u0006 כתוב \u0005בשטר],\u0006 \u0003ליכתבו ליה שטרא מעליא\u0004 \u0005[שיכתבו לו\u0006 שנית \u0005שטר יפה],\u0006 שהרי הם יכולים להעיד על מה שהיה, ולכתוב! \u0003ואי דליכא סהדי, אנן מנא ידעינן\u0004 \u0005[ואם שאין עדים, מניין אנו יודעים]\u0006 מה היה כתוב בשטר? \u0003אמר רבא: תהא במאמינו,\u0004 ששורף השטר מאמין לבעליו שכך היה כתוב בו ובכל זאת פטור לדעת רבה, משום שלא הזיק ממון בידיו.","\u0003אמר רב דימי בר חנינא: הא\u0004 \u0005[זו]\u0006 שאמר \u0003רבה\u0004 — \u0003מחלוקת ר' שמעון ורבנן היא. ל\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שכל \u0003דבר הגורם לממון כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003מחייב\u0004 \u0005[חייב]\u0006 על כך, \u0003לרבנן דאמרי\u0004 \u0005[לחכמים שאומרים]\u0006 ש\u0003דבר הגורם לממון לאו\u0004 \u0005[לא]\u0006 \u0003כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003לא מחייב\u0004 \u0005[חייב],\u0006 וכן הוא דעת רבה הפוטרו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אימר\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' שמעון\u0004 שאומר \u0003דבר הגורם לממון כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003בדבר שעיקרו ממון,\u0004 שהדבר שהזיק היה בעל ערך כשלעצמו, \u0003כ\u0004פי שאמר \u0003רבה,\u0004 ש\u0003אמר רבה:\u0004 אם \u0003גזל חמץ לפני הפסח, ובא אחר ושרפו במועד\u0004 — \u0003פטור\u0004 השורף מלשלם לגזלן, \u0003שהכל מצווים עליו לבערו\u0004 ומצוה עשה. אם שרפו \u0003לאחר הפסח\u0004 — \u0003מחלוקת ר' שמעון ורבנן\u0004 \u0005[וחכמים],\u0006","\u0003ל\u0004דעת \u0003ר' שמעון דאמר\u0004 \u0005[שאומר]\u0006 ש\u0003דבר הגורם לממון כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003חייב\u0004 השורף, וצריך לשלם לגזלן, כי אף שהיה החמץ אסור בהנאה יכול היה הגזלן להחזיר אותו בעינו לנגזל ולהיפטר, ועכשיו שנשרף צריך להשיב לו דמי אותה כמות של חמץ, ואילו \u0003לרבנן דאמרי\u0004 \u0005[לחכמים שאומרים]\u0006 ש\u0003דבר הגורם לממון לאו\u0004 \u0005[לא]\u0006 \u0003כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003פטור,\u0004 ואולם \u0003בדבר שאין עיקרו ממון מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 גם כן אף לדעת ר' שמעון שכממון הוא נחשב? והרי השטר אינו ממון כשלעצמו!","\u0003אמר אמימר: מאן דדאין דינא דגרמי\u0004 \u0005[מי שדן דין של גורמים],\u0006 שהוא מחייב גם מי שגרם נזק עקיף — \u0003מגבי ביה\u0004 \u0005[גובה בו]\u0006 מן השורף שטרו של חבירו \u0003דמי שטרא מעליא\u0004 \u0005[שטר מעולה,\u0006 מושלם\u0005],\u0006 \u0003ומאן דלא דאין דינא דגרמי\u0004 \u0005[ומי שאינו דן דין של גורמים]\u0006 — \u0003מגבי ביה\u0004 \u0005[גובה בו]\u0006 מן השורף \u0003דמי ניירא בעלמא\u0004 \u0005[נייר סתם].\u0006 ומספרים: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 כזה, \u0003וכפייה\u0004 \u0005[וכפה אותו]\u0006 \u0003רפרם לרב אשי\u0004 ששרף שטר של אחר בצעירותו, \u0003ואגבי ביה כי כשורא לצלמא\u0004 \u0005[וגבה בו כמו קורה\u0006 נבחרת \u0005שעושים לצלמים,\u0006 פסלים\u0005],\u0006 כלומר, גבה שטר זה בשלימות.","שנינו במשנה: אם גזל \u0003חמץ ועבר עליו הפסח,\u0004 יכול הגזלן להחזירו לנגזל כמות שהוא אף שהוא עתה אסור בהנאה וחסר ערך, כי \u0003אומר לו \"הרי שלך לפניך\".\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שסבור ש\u0003אומרין\u0004 גם \u0003באיסורי הנאה \"הרי שלך לפניך\"? אמר רב חסדא:\u0004 שיטת \u0003ר' יעקב היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שור שהמית\u0004 את האדם ודינו לסקילה, הרי \u0003עד שלא נגמר דינו\u0004 בבית דין לסקילה, אם \u0003מכרו\u0004 — \u0003מכור,\u0004 אם \u0003הקדישו\u0004 — \u0003מוקדש,\u0004 אם \u0003שחטו\u0004 — \u0003בשרו מותר,\u0004 אם \u0003החזירו שומר לבעליו\u0004 — \u0003מוחזר.\u0004","ואולם \u0003משנגמר דינו\u0004 כבר לסקילה ונאסר בהנאה, אם \u0003מכרו\u0004 — \u0003אינו מכור, הקדישו\u0004 — \u0003אינו מוקדש, שחטו\u0004 — \u0003בשרו אסור, החזירו שומר לבעליו\u0004 — \u0003אינו מוחזר,\u0004 שהרי הוא אסור בהנאה, ואין לו כל ערך. \u0003ר' יעקב אומר: אף משנגמר דינו,\u0004 אם \u0003החזירו שומר לבעליו\u0004 — \u0003מוחזר.\u0004","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים],\u0006 ש\u0003ר' יעקב סבר\u0004 \u0005[סבור]\u0006 ש\u0003אומרין\u0004 גם \u0003באיסורי הנאה \"הרי שלך לפניך\", ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 ש\u0003אין אומרין באיסורי הנאה \"הרי שלך לפניך\"\u0004 ומשנתנו בענין חמץ שעבר עליו הפסח כשיטת ר' יעקב היא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003באיסורי הנאה \"הרי שלך לפניך\",\u0004 וכולם סבורים כדין משנתנו בענין חמץ, שאם כדבריך שחכמים ור' יעקב בברייתא חולקים בבעיה הכללית של השבת איסורי הנאה, \u0003אם כן\u0004 \u0003נפלגו\u0004 \u0005[שיחלקו]\u0006 באותה ברייתא \u0003בחמץ בפסח\u0004 אם מחזירו בעינו, שהוא איסור הנאה ברור. \u0003אלא אמר רבה: הכא\u0004 \u0005[כאן]\u0006 באותה ברייתא \u0003ב\u0004שאלה אחרת, והיא: האם \u0003גומרין דינו של שור שלא בפניו קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003אין גומרין דינו של שור שלא בפניו,\u0004 ומשום כך חייב — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הבעלים לשומר שמחזיר לו עתה את השור: \u0003אי אייתיתיה ניהליה\u0004 \u0005[אם היית מביא אותו,\u0006 את השור, \u0005אלי]\u0006 לפני שנגמר דינו \u0003הוה מעריקנא ליה לאגמא\u0004 \u0005[הייתי מבריח אותו לאגם]\u0006 ואי אפשר היה לדון אותו שלא בפניו, והיה השור נשאר בהיתירו. \u0003השתא מסרתיה ביד מאן דלא מצינא לאישתעויי דינא בהדיה\u0004 \u0005[עכשיו מסרת אותו בידי מי שאיני יכול להתדיין עימו],\u0006 שלא החזרת אותו אלי לפני שנמסר לבית דין, ומשום כך אתה חייב לשלם לי, ואין השבה של עכשיו מועילה. \u0003ור' יעקב סבר\u0004 \u0005[סבור]:\u0006 \u0003גומרין דינו של שור\u0004 גם \u0003שלא בפניו,\u0004 ולכן אין הבעלים יכול לטעון טענה זו, משום \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 השומר בתשובה: \u0003מאי עבדי ליה\u0004 \u0005[מה\u0006 כבר \u0005עשיתי לו\u0006 לשור\u0005]?\u0006 \u0003סוף סוף הוה גמרי ליה דינא\u0004 \u0005[היו גומרים לו את דינו]\u0006 \u0003שלא בפניו\u0004 בכל מקום שהוא, ואין ממש בטענת הבעלים.","מסופר: \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רב חסדא\u0004 שסבור היה כי משנתנו שיטת ר' יעקב היא, \u0003לרבה בר שמואל, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנית מידי\u0004 \u0005[\u0006האם \u0005שנית דבר]\u0006 \u0003ב\u0004ענין דיני \u0003איסורי הנאה\u0004 לגבי השבת גזילה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003תנינא\u0004 \u0005[שניתי]:\u0006 נאמר \u0003\"והשיב את הגזלה\"\u0004 (ויקרא ה, כג), \u0003מה תלמוד לומר\u0004 בהמשך \u0003\"אשר גזל\",\u0004 מה בא זה ללמדנו? — כוונתו \u0003יחזיר כעין שגזל,\u0004","\u0003מכאן אמרו: גזל מטבע ונפסל, פירות והרקיבו, יין והחמיץ, תרומה ונטמאת, חמץ ועבר עליו הפסח, בהמה ונעבדה בה עבירה\u0004 שפוסלת אותה מקרבן, \u0003ושור עד שלא נגמר דינו\u0004 — \u0003אומר לו\u0004 הגזלן לנגזל \u0003\"הרי שלך לפניך\".\u0004","ומעתה נברר: \u0003מאן שמעת ליה דאמר\u0004 \u0005[מי שמעת אותו שאומר]\u0006 ש\u0003עד שלא נגמר דינו\u0004 של השור — \u0003אין\u0004 \u0005[כן]\u0006 אפשר להחזיר אותו, \u0003משנגמר דינו\u0004 — \u0003לא?\u0004 — שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא החולקים על ר' יעקב בברייתא, \u0003וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003חמץ ועבר עליו הפסח\u0004 — \u0003אומר לו \"הרי שלך לפניך\",\u0004 ומכאן מוכח שלא כדברי רב חסדא, אלא שאף חכמים מודים בהשבת איסור הנאה בעינו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרבה בר שמואל: \u0003אי משכחת להו\u0004 \u0005[אם תמצא אותם,\u0006 את החכמים\u0005]\u0006 \u0003לא תימא להו ולא מידי\u0004 \u0005[אל תאמר להם דבר]\u0006 ואל תפרסם שלא צדקתי בדברי.","אגב שהובאה ברייתא זו דנים במה ששנו בה: גזל \u0003פירות והרקיבו\u0004 — \u0003אומר לו\u0004 הגזלן לנגזל \u0003\"הרי שלך לפניך\".\u0004 ומקשים: \u0003והתנן\u0004 \u0005[והרי שנינו]\u0006 במשנתנו: גזל \u0003פירות והרקיבו\u0004 — \u0003משלם כשעת הגזילה! אמר רב פפא: כאן\u0004 במשנתנו מדובר \u0003שהרקיבו כולן,\u0004 שמה שגזל ממנו נשתנה שינוי של ממש שאינו יכול לומר \"הרי שלך לפניך\", ולכן צריך לשלם, ואילו \u0003כאן\u0004 בברייתא מדובר \u0003שהרקיבו מקצתן,\u0004 ולכן יכול להחזיר לו ולומר \"הרי שלך לפניך\".","\u0003נתן לאומנין\u0004 (בעלי מלאכה) חפץ \u0003לתקן, וקלקלו\u0004 אותו — \u0003חייבין לשלם.\u0004 ודוגמאות לדבר: \u0003נתן לחרש\u0004 (נגר) \u0003שידה תיבה ומגדל\u0004 (סוגים שונים של ארוניות) \u0003לתקן וקלקל\u0004 — \u0003חייב לשלם. והבנאי שקיבל עליו לסתור\u0004 (לפרק) \u0003את הכותל, ושיבר\u0004 בתוך כדי כך את \u0003האבנים או שהזיקן\u0004 ועתה אין הן ראויות עוד לשימוש — \u0003חייב לשלם.\u0004 ואם \u0003היה סותר מצד זה\u0004 של הכותל \u0003ונפל\u0004 הכותל \u0003מצד אחר\u0004 והזיק — \u0003פטור,\u0004 אבל \u0003אם מחמת המכה\u0004 שהיכה בכח הותזה אבן והזיקה — \u0003חייב.\u0004","שנינו במשנה שאם נתן לחרש שידה תיבה ומגדל לתקן, וקלקל — חייב לשלם. \u0003אמר רב אסי: לא שנו\u0004 כן \u0003אלא\u0004 במקרה \u0003שנתן לחרש שידה תיבה ומגדל לנעץ בהן מסמר\u0004 (או כל תיקון אחר כיוצא בזה הנעשה בכלי שלם), \u0003ונעץ בהן מסמר ושיברן\u0004 בתוך כדי כך, שמשלם האומן עבור הכלי שקלקל. \u0003אבל\u0004 אם \u0003נתן לחרש עצים לעשות\u0004 מהם \u0003שידה תיבה ומגדל, ועשה מהן שידה תיבה ומגדל ושיברן\u0004 לפני שמסרם לבעל הבית — \u0003פטור\u0004 מלשלם על אבדן הכלי, ואינו חייב אלא במה שגרם נזק לעצים.","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אומן קונה בשבח כלי,\u0004 כלומר, האומן זוכה בכלי על ידי זה שהוא עובד בו ומעלה את ערכו, ומשום כך הכלי נחשב כשייך לאומן עד שיתננו לבעליו, ומשום כך אם קלקל את הכלי הזה — הריהו כמקלקל את שלו ואינו צריך להחזיר אלא את העצים בלבד.","ומנסים לסתור את דברי רב אסי ממה ששנינו בתחילת המשנה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נתן לאומנין וקלקלו\u0004 — \u0003חייבין לשלם. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר פה במקרה \u0003דיהיב להו\u0004 \u0005[שנתן להם]\u0006 \u0003עצים\u0004 ובכל זאת הם משלמים דמי כלי! ודוחים: \u0003לא,\u0004 מדובר שנתן להם \u0003שידה תיבה ומגדל\u0004 לעשות בהם תיקון כלשהו.","ומקשים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנה בסוף,\u0006 בהמשך המשנה\u0005]\u0006 \u0003שידה תיבה ומגדל, מכלל דרישא\u0004 \u0005[שבתחילה]\u0006 מדובר במקרה שנתן להם \u0003עצים! אמרי\u0004 \u0005[אומרים]\u0006 בדחיה לכך: \u0003פרושי קא מפרש לה\u0004 \u0005[מפרש הוא]\u0006 את הדברים שאמר בתחילה. שתחילה אומר כלל שהאומנים אחראים לקלקול, ומפרש: \u0003כיצד נתן לאומנין לתקן וקלקלו חייבין לשלם?\u0004 — \u0003כגון שנתן לחרש שידה תיבה ומגדל.\u0004","ומעירים: \u0003והכי נמי מסתברא\u0004 \u0005[וכך גם כן מסתבר לומר]\u0006 כפירוש זה, שבלשון \u0003\"כיצד\" קתני\u0004 \u0005[שנה].\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר במקרה שנתן לו \u0003עצים,\u0004 אם כן \u0003השתא אשמעינן\u0004 \u0005[עכשיו,\u0006 הרי \u0005השמיע לנו\u0006 כבר\u0005]\u0006 שאם נתן לו \u0003עצים\u0004 — \u0003חייבין לשלם, ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 ש\u0003אומן קונה בשבח כלים,\u0004 אם כן נתן לו \u0003שידה תיבה ומגדל מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שחייב לשלם?","ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[\u0006ראיה \u0005זו]\u0006 \u0003לא איריא\u0004 \u0005[אינו שייך],\u0006 ואפשר לדחות אותה ולומר ש\u0003תנא סיפא לגלויי רישא\u0004 \u0005[שנה\u0006 את \u0005סופה לגלות,\u0006 להסביר, את \u0005תחילתה],\u0006 \u0003שלא תאמר\u0004 כי \u0003רישא\u0004 \u0005[תחילתה]\u0006 עוסקת בנותן \u0003שידה תיבה ומגדל, אבל עצים לא,\u0004 לכן \u0003תנא סיפא\u0004 \u0005[שנה בסוף]\u0006 \u0003שידה תיבה ומגדל, מכלל\u0004 זה תלמד \u0003דרישא\u0004 \u0005[שתחילתה]\u0006 מדברת בנותן \u0003עצים, ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003חייב לשלם,\u0004 ואם כן מן המשנה אין להביא הוכחה כלל.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם\u0006 אפשר \u0005לומר\u0006 שאפשר \u0005לסייע לו]\u0006 לרב אסי ממה ששנינו במשנה: \u0003הנותן צמר לצבע\u0004 לצובעו"],["\u0003והקדיחו\u0004 (התקלקל) ב\u0003יורה\u0004 (כלי בישול) שצובעים בה — \u0003נותן לו\u0004 הצבע את \u0003דמי צמרו.\u0004 ונדייק: \u0003דמי צמרו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 משלם לו, \u0003דמי צמרו ושבחו\u0004 (את תוספת הערך) — \u0003לא\u0004 משלם לו. \u0003לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003שהקדיחו לאחר נפילה,\u0004 כלומר, לאחר שנפל הצמר לכלי ונצבע יפה, ואחר כך התקלקל, \u0003דאיכא שבחא\u0004 \u0005[שיש שבח]\u0006 בצמר, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כרב אסי ש\u0003אומן קונה בשבח כלי,\u0004 ולכן אינו צריך לשלם את השבח!","\u0003אמר שמואל:\u0004 אין מכאן ראיה שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שהקדיחו בשעת נפילה\u0004 עצמה, \u0003דליכא שבחא\u0004 \u0005[שאין כאן שבח].\u0006 ושואלים: לפי דרך זו, \u0003אבל\u0004 אם \u0003הקדיחו לאחר נפילה מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003נותן לו דמי צמרו ושבחו? לימא\u0004 \u0005[\u0006האם \u0005לומר\u0006 נסיק מכאן\u0005]\u0006 ש\u0003שמואל לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור כדברי\u0005]\u0006 \u0003רב אסי,\u0004 ולדעתו אין אומן קונה בשבח כלי?","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003שמואל: הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנה זו \u0005במה אנו עוסקים]\u0006 — \u0003כגון\u0004 שה\u0003צמר וסמנין\u0004 (חומרי הצביעה) שניהם של \u0003בעל הבית, ו\u0004ה\u0003צבע אגר ידיה\u0004 \u0005[שכר ידו,\u0006 שכר מלאכתו\u0005]\u0006 \u0003הוא דשקיל\u0004 \u0005[שלוקח]\u0006 ולא דבר אחר. ולכן אין האומן קונה בשבח כלי, ואולם במקרה שהסמנים של הצבע — קונה בשבח הכלי.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאף הסמנים של בעל הבית והכל נתקלקל בידי הצבע, \u0003\"נותן לו דמי צמרו וסמנין\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר במשנה\u0005]\u0006 ולא דמי צמרו בלבד! \u0003אלא\u0004 צריך לומר ש\u0003שמואל דחויי קא מדחי ליה\u0004 \u0005[\u0006רק ב\u0005דחיה הוא דוחה אותו],\u0006 שהוא אומר שממשנה זו אין הוכחה שאומן קונה בשבח כלי, משום שאפשר לפרשה באופן אחר, אבל הוא עצמו לא פירש מה דעתו בענין זה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003הנותן טליתו\u0004 (בגד) \u0003לאומן\u0004 לתקנו וכיוצא בזה, \u0003גמרו\u0004 האומן את מלאכתו \u0003והודיעו\u0004 לבעלים שגמר — \u0003אפילו מכאן,\u0004 מזמן זה, \u0003ועד עשרה ימים אינו עובר עליו משום \"לא תלין\u0004 פעולת שכיר אתך עד בקר\u0003\"\u0004 (ויקרא יט, יג), כיון שלא החזיר לו עדיין את טליתו. אם \u0003נתנה לו\u0004 את הטלית בחזרה \u0003בחצי היום\u0004 — \u0003כיון ששקעה עליו החמה עובר עליו משום \"בל תלין\".\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003אומן קונה בשבח כלי, אמאי\u0004 \u0005[מדוע]\u0006 \u0003עובר משום \"בל תלין\"?\u0004 הרי האומן קנה את הכלי, ומה שהוא מקבל בתמורה הוא בגדר מחיר הכלי, ואינו שכר עבודה שעליו נאמר דין הלנת שכר!","ומשיבים: \u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא:\u0004 מדובר פה \u0003ב\u0004מלאכת \u0003גרדא דסרבלא\u0004 \u0005[כיבוס בגד עבה]\u0006 \u0003דליכא שבחא\u0004 \u0005[שאין\u0006 בכך \u0005שבח\u0006 ותוספת\u0005]\u0006 לבגד, ואין מה שיקנה בו האומן.","ומקשים: \u0003סוף סוף למאי יהבה נהליה\u0004 \u0005[למה נתן לו\u0006 את הבגד הזה\u0005]?\u0006 — \u0003לרכוכי\u0004 \u0005[לרכך\u0006 אותו\u0005],\u0006 הלא \u0003כיון דרככיה היינו שבחא\u0004 \u0005[שריכך אותו זהו השבח]\u0006 שהוסיף בבגד ויקנה בו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דאגריה לביטשי\u0004 \u0005[ששכר אותו לדריכות,\u0006 דריסות בכוח\u0005],\u0006 שדורך על הבגד במים עד שמתרכך, וקצב לו שכרו לפי חישוב של \u0003ביטשא ביטשא במעתא\u0004 \u0005[דריכה דריכה במעה]\u0006 \u0003דהיינו\u0004 \u0005[שזו היא]\u0006 \u0003שכירות\u0004 ולא קבלנות, שהרי הוא משלם לו על פי עצם עבודתו, ולא על תוצאת עבודתו שהיא בגד מכובס שמקבל ממנו.","ושואלים: \u0003ולמאי דסליק אדעתין מעיקרא\u0004 \u0005[ול\u0006פי \u0005מה שעלה על דעתנו מתחילה]\u0006 ש\u0003לא אגריה לביטשי\u0004 \u0005[שכר אותו\u0006 \u0005לדריכות]\u0006 אלא נתן לו את הבגד על מנת לקבלו מכובס, כמו שנותנים לאומן, \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב ששת. דבעו מיניה\u0004 \u0005[ששאלו אותו]\u0006 את \u0003רב ששת:\u0004 האם \u0003קבלנות\u0004 שכר עבודה של אומן, שאינו מקבל שכר עבור זמן עבודתו אלא עבור התוצאה, האם \u0003עובר עליו משום \"בל תלין\"\u0004 אם לא שילמו לו הבעלים שכרו ביום שגמר מלאכתו \u0003או אינו עובר? ואמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: עובר\u0004 על כך.","ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 מכאן ש\u0003רב ששת פליגא\u0004 \u0005[חולק]\u0006 על דברי \u0003רב אסי\u0004 הסבור שאומן קונה בשבח כלי? \u0003אמר שמואל בר אחא:\u0004 רב ששת דיבר \u0003ב\u0004מקרה של קבלנות מיוחדת שהיא \u0003שליחא דאיגרתא\u0004 \u0005[שליחות של איגרת],\u0006 ששכרו להעביר לו איגרת למקום מסויים, שאין בכך כל שבח שיקנה בו האומן אלא רק העברת חפץ בלבד, ובזה יש דין של \"בל תלין\".","ומציעים: דיון זה אם אומן קונה בשבח כלי, \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 ששנוי כבר \u0005כ\u0006מחלוקת \u0005תנאים].\u0006 ששנינו שנחלקו בבעיה הבאה: אם נתנה אשה לצורף זהב ואמרה לו: \u0003\"עשה לי שירים\u0004 (אצעדות), \u0003נזמין וטבעות\u0004 מזהב זה \u0003ואקדש\u0004 (ואתקדש) \u0003לך\u0004 בשכר עבודתך \u0003\",\u0004 \u0003כיון שעשאן\u0004 — מיד היא \u0003מקודשת,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: אינה מקודשת עד שיגיע ממון לידה.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ממון\"\u0004 שהוזכר כאן שצריך שיגיע לידי האשה, לדעת חכמים על מנת שתתקדש? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אותו ממון,\u0004 כלומר, הצמידים הללו, \u0003מכלל\u0004 ש\u0003ר' מאיר\u0004 החולק על חכמים \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003אותו ממון לא,\u0004 שאינה מתקדשת בו? \u0003אלא במאי מקדשא\u0004 \u0005[במה\u0006 היא \u0005מתקדשת]?\u0006 \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 כי \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ממון\"? ממון אחר,\u0004 שלדעת חכמים צריך לתת לה ממון נוסף כדי לקדש אותה בו. ואילו ר' מאיר סבור שבנתינת התכשיטים לידה היא מתקדשת.","וכהקדמה לבירור הענין אומרים מה היו הנחות היסוד; \u0003וסברוה\u0004 \u0005[וחשבו]\u0006 מתחילה מי שמציעים כי אכן בענין שבח כלי נחלקו \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003ישנה לשכירות מתחילה ועד סוף,\u0004 כלומר, ההתחייבות של הבעלים לשלם לפועל עבור השכירות היא מתחילה ועד סוף, שבכל רגע ורגע שהוא עובד כבר חלה חובה על הבעלים לשלם את השכר, אלא שאין משלמים מיד, ושכר זה נזקף כעין חוב. ואם כן שכר עבודה של פועל הוא הלוואה. \u0003ודכולי עלמא\u0004 \u0005[ו\u0006כן \u0005שלדעת הכל]\u0006 \u0003המקדש\u0004 אשה \u0003במלוה אינה מקודשת,\u0004 ואם כן בשכר עבודתו לבד אינה מקודשת, ולפי זה","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003באומן קונה בשבח כלי קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003אומן קונה בשבח כלי,\u0004 וכיון ששבח הכלי נקנה לו, הרי כאשר הוא נותן לה את התכשיטים הרי זה כנותן לה משלו דבר בעל ערך ומתקדשת בו, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין אומן קונה בשבח כלי,\u0004 ואם כן אין לאומן כל קנין בתכשיטים אלא הלוואה בלבד, ואינה מתקדשת לו בה?","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003אין אומן קונה בשבח כלי, אלא הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003ישנה לשכירות מתחילה ועד סוף קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 ש","\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003אין לשכירות אלא לבסוף,\u0004 שבגמר המלאכה יש חיוב ממון על השוכר לשלם, ומשום כך אין זו הלוואה אלא סכום כסף שהיא צריכה לתת לו באותה שעה, ואם הוא נותן לה את התכשיטים בלא לתבוע ממנה — הרי זה כאילו נתן לה את הכסף הזה, והיא מתקדשת בו. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003יש לשכירות מתחילה ועד סוף,\u0004 ומשום כך כסף השכירות מלווה הוא, ואינה מתקדשת בו אלא בכסף נוסף שיתן לידה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ישנה לשכירות מתחילה ועד סוף, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004ענין \u0003מקדש במלוה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003המקדש במלוה\u0004 — \u0003מקודשת, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003המקדש במלוה\u0004 — \u0003אינה מקודשת.\u0004"],["\u0003רבא אמר\u0004 הסבר אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ישנה לשכירות מתחילה ועד סוף, ודכולי עלמא\u0004 \u0005[ולדעת הכל]\u0006 \u0003המקדש במלוה אינה מקודשת, ודכולי עלמא\u0004 \u0005[ולדעת הכל]\u0006 \u0003אין אומן קונה בשבח כלי.\u0004","\u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהוסיף לה נופך\u0004 (אבן קטנה לקישוט) \u0003משלו, ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003מלוה ופרוטה,\u0004 שאם האיש המקדש מוותר לאשה על מלווה בסכום גדול ובנוסף לכך נותן לה בקידושיה דבר קטן \u0003דעתה\u0004 של האשה להתקדש ב\u0003פרוטה,\u0004 ומשום כך הריהי מתקדשת. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מלוה ופרוטה\u0004 — \u0003דעתה\u0004 על ה\u0003מלוה,\u0004 ואת הפרוטה אינה מחשיבה, ומשום כך אינה מתקדשת, שאין מקדשים במלווה.","\u0003ו\u0004נחלקו ר' מאיר וחכמים \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת של תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשה \u0003\"\u0004הרי את מקודשת לי \u0003בשכר שעשיתי עמך\",\u0004 כלומר, בשכר עבודה שעשה עבורה ולא שילמה לו עדיין אותו — \u0003אינה מקודשת,\u0004 שאין זה אלא כמקדש במלווה, אבל אם אמר לה \u0003\"\u0004הרי את מקודשת לי \u0003בשכר\u0004 עבודה \u0003שאעשה עמך\"\u0004 — הריהי \u0003מקודשת. ר' נתן אומר:\u0004 אם אמר \u0003\"בשכר שאעשה עמך\"\u0004 — \u0003אינה מקודשת, וכל שכן\u0004 אם אמר \u0003\"בשכר שעשיתי עמך\".\u0004","\u0003ור' יהודה הנשיא אומר, באמת אמרו,\u0004 כך ההלכה: \u0003בין\u0004 אם אמר \u0003\"בשכר שעשיתי עמך\" ובין\u0004 אם אמר \u0003\"בשכר שאעשה עמך\"\u0004 — \u0003אינה מקודשת, ו\u0004אולם \u0003אם הוסיף לה נופך משלו\u0004 — הריהי \u0003מקודשת.\u0004","ומבארים: \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 מה ההבדל בהלכה \u0003בין\u0004 שיטת ה\u0003תנא קמא ל\u0004שיטת \u0003ר' נתן\u0004 — \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 המחלוקת בענין \u0003שכירות,\u0004 האם חיוב תשלום שכירות שעל השוכר חל בכל רגע ורגע (\"מתחילה ועד סוף\") שנעשה מלווה, או שהחיוב חל בגמר העבודה על כל הסכום כולו (\"אינה אלא לבסוף\"). \u0003בין\u0004 שיטת \u0003ר' נתן ל\u0004שיטת \u0003ר' יהודה הנשיא\u0004 — \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת לגבי \u0003מלוה ופרוטה,\u0004 שלדעת ר' נתן דעתה על המלווה, ולכן אינה מקודשת בתוספת הנופך. ולדעת ר' יהודה דעתה על הפרוטה — ומתקדשת.","ושבים לדון בעיקר דין משנתנו באומנים שקלקלו. \u0003אמר שמואל: טבח\u0004 (שוחט) \u0003אומן\u0004 (בעל מקצוע) \u0003שקלקל\u0004 בשחיטה והתנבלה הבהמה — \u0003חייב לשלם\u0004 לבעל הבהמה, מדוע? \u0003מזיק הוא, פושע\u0004 (רשלן) \u0003הוא, נעשה כאומר לו \"שחוט לי מכאן\" ושחט לו מכאן,\u0004 במקום אחר, שלא כדברי בעל הבהמה.","ושואלים: \u0003למה ליה למימר\u0004 \u0005[לו לומר]\u0006 בלשון זו \u0003\"מזיק הוא, פושע הוא\"?\u0004 ומסבירים: \u0003אי אמר\u0004 \u0005[אם\u0006 היה \u0005אומר]\u0006 רק \u0003\"מזיק הוא\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהשתמש בביטוי זה דווקא משום \u0003הני מילי היכא דקא עביד\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שהוא עושה]\u0006 שחיטה זו \u0003בשכר,\u0004 שאחריותו לחפץ מחשיבה אותו כמזיק, וחייב אף באופן כזה של שגגה, \u0003אבל היכא דקא עביד\u0004 \u0005[במקום שהוא עושה]\u0006 שחיטה זו \u0003בחנם\u0004 — \u0003לא,\u0004 ואף שהזיק — הרי היה זה באונס, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003פושע הוא,\u0004 ועל רשלנות חייב גם אם אינו מקבל שכר על כך, כדין שומר חינם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב חמא בר גוריא לשמואל: הנותן בהמה לטבח וניבלה,\u0004 אם היה זה שוחט \u0003אומן\u0004 — \u0003פטור,\u0004 ואם היה זה \u0003הדיוט\u0004 — \u0003חייב. ואם נותן\u0004 לו \u0003שכר\u0004 על שחיטתו, \u0003בין\u0004 אם היה \u0003הדיוט בין\u0004 אם היה שוחט \u0003אומן\u0004 — \u0003חייב,\u0004 ואם כן שוחט אומן שעשה בחינם — פטור! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לעכר\u0004 \u0005[שיתעכר]\u0006 \u0003מוחך\u0004 שאתה שואל דברי שטות!","\u0003אתא ההוא מרבנן קא מותיב ליה\u0004 \u0005[בא אחד מהחכמים והקשה לו]\u0006 אותה קושיה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא שקלת מאי דשקל\u0004 \u0005[עכשיו תקבל\u0006 ממני \u0005מה שיקבל]\u0006 \u0003חברך,\u0004 שהרי \u0003קאמינא לכו אנא\u0004 \u0005[אני אומר לכם]\u0006 כפי שיטת \u0003ר' מאיר, וקאמריתו\u0004 \u0005[ואתם אומרים]\u0006 \u0003לי\u0004 כקושיה על דברי את שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא דייקת מילי\u0004 \u0005[בדברי]?\u0006 \u0003שאני אומר: מזיק הוא, פושע הוא, נעשה כאומר לו שחוט לי מכאן ושחט לו מכאן. מאן אית ליה האי סברא\u0004 \u0005[מי יש לו סברה זו]?\u0006 — \u0003ר' מאיר, דאמר\u0004 \u0005[שאומר]:\u0006 \u0003מבעי ליה למירמי אנפשיה\u0004 \u0005[צריך הוא להטיל על עצמו]\u0006 את החובה לעשות את הדברים כראוי, ואם לא עשה כראוי — חייב בתוצאות הנזק שנגרם.","ושואלים: \u0003הי\u0004 \u0005[\u0006ל\u0005איזה]\u0006 מדברי \u0003ר' מאיר\u0004 מתייחס שמואל? \u0003אילימא הא\u0004 \u0005[אם תאמר זו]\u0006 שאמר \u0003ר' מאיר (קל\"ן סימן),\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 שור ש\u0003קשרו בעליו במוסירה\u0004 (רצועה) \u0003ונעל בפניו כראוי, ויצא והזיק, בין\u0004 אם היה זה שור \u0003תם בין\u0004 אם היה שור \u0003מועד\u0004 — \u0003חייב,\u0004 אלו \u0003דברי ר' מאיר,\u0004 ומשמע שלגבי שור מועד צריך היה להשגיח היטב, וכיון שלא עשה זאת — חייב.","ואולם \u0003התם\u0004 \u0005[שם]\u0006 כפי שהסברנו במקומו \u0003בקראי פליגי\u0004 \u0005[בכתובים\u0006 הם \u0005חלוקים]\u0006 הדעות השונות, ור' מאיר בכללם, ולא בסברה שבדבר!","\u0003אלא הא\u0004 \u0005[זו]\u0006 שאמר \u0003ר' מאיר, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 נתן לצבע \u0003לצבוע לו\u0004 צמר בצבע \u0003אדום וצבעו שחור, שחור וצבעו אדום\u0004 — \u0003ר' מאיר אומר: נותן לו דמי צמרו.\u0004 אולם מכאן אין להוכיח ששיטת ר' מאיר שאדם חייב לעשות דברים כראוי, ואם עשה כן — חייב לשלם. ואולם \u0003התם\u0004 \u0005[שם]\u0006 \u0003בידים קלאו מיניה\u0004 \u0005[שרף אותו ממנו],\u0006 שעשה בפועל מעשה של קלקול!","\u0003אלא הא\u0004 \u0005[זו]\u0006 שאמר \u0003ר' מאיר, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נשברה כדו\u0004 של אדם \u0003ולא סילקה\u0004 מן הדרך, \u0003נפלה גמלו ולא העמידה\u0004 — \u0003ר' מאיר אומר: חייב בנזקן, וחכמים אומרים: פטור מדיני אדם\u0004 אף על פי ש\u0003חייב בדיני שמים, וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 שבשאלה האם \u0003נתקל פושע הוא פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ומכאן רואים שאף הנתקל נחשב פושע לדעת ר' מאיר, שמוטל היה עליו לשים לב למה שעושה, וכיון שאירע נזק — הרי הוא חייב.","לאחר שדנו בדעת שמואל בענין טבח אומן, דנים בדעת ר' יוחנן באותו נושא, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: טבח אומן שקלקל\u0004 — \u0003חייב, ואפילו הוא אומן כטבחי ציפורי,\u0004 שאין אומרים שהיה זה אונס, אלא אשמתו היא. ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה: עובדא הוה\u0004 \u0005[מעשה היה]\u0006 בשוחט שקלקל בשחיטתו ונתבע לדין \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן בכנישתא\u0004 \u0005[בבית הכנסת]\u0006 של היישוב \u0003מעון,\u0004 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 לשוחט: \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003ראיה דממחית\u0004 \u0005[שאתה מומחה]\u0006 \u0003ל\u0004שחוט \u0003תרנגולים ואפטרך\u0004 מתשלום!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 במעשה זה שהבאנו היה זה כששחט \u0003בחנם,\u0004 ולכן אם מומחה הוא — הריהו פטור, \u0003כאן בשכר\u0004 — חייב. \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר ר' זירא: הרוצה שיתחייב לו טבח\u0004 אם יקלקל בשחיטתו — \u0003יקדים לו דינר,\u0004 ואז, כיון שהוא עושה בשכר — חייב.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003המוליך חטים לטחון, ולא לתתן\u0004 (הרטיבן) הטוחן לפני הטחינה כפי שהיה צריך לעשות כדי שתעלה הטחינה יפה, \u0003ו\u0004כתוצאה מכך \u0003עשאן סובין או מורסן,\u0004 או נתן \u0003קמח לנחתום\u0004 (אופה) \u0003ועשאו פת ניפולין,\u0004 שהיא פת שלא נאפתה כל צורכה, או נתן \u0003בהמה לטבח וניבלה\u0004 (עשה אותה נבילה) בשחיטתו — \u0003חייב, מפני שהוא כנושא שכר,\u0004 משמע שאפילו אם בחינם עשה דינו כמקבל שכר וחייב! ומתקנים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מפני שהוא נושא שכר.\u0004 אבל העושה בחינם — פטור, אם היה מומחה.","מסופר: \u0003ההוא מגרומתא\u0004 \u0005[\u0006בהמה \u0005מוגרמת אחת],\u0006 שנשחטה שלא במקום הראוי, \u0003דאתאי לקמיה\u0004 \u0005[שהובאה לפני]\u0006 \u0003רב, טרפיה\u0004 \u0005[הטריף אותה],\u0006 \u0003ופטריה\u0004 \u0005[ופטרו],\u0006 את ה\u0003טבח מלשלומי דמי\u0004 \u0005[מלשלם\u0006 את \u0005מחירה].\u0006 \u0003פגעו\u0004 (פגשו) \u0003ביה\u0004 \u0005[בו,\u0006 אותו\u0005]\u0006 \u0003רב כהנא ורב אסי בההוא גברא\u0004 \u0005[באותו אדם]\u0006 בעל הבהמה, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003בך רב תרתי\u0004 \u0005[שני\u0006 דברים\u0005].\u0006","ושואלים: \u0003מאי תרתי\u0004 \u0005[מהם שתים\u0006 אלה\u0005]?\u0006 \u0003אילימא תרתי לגריעותא\u0004 \u0005[אם תאמר\u0006 שעשה \u0005שתים להרע],\u0006 האחת — \u0003דאיבעי ליה לאכשורי\u0004 \u0005[שהיה צריך להכשיר]\u0006 את הבהמה \u0003כ\u0004דעת \u0003ר' יוסי בר' יהודה\u0004 המכשיר מוגרמת שכזו, \u0003ו\u0004אילו רב \u0003טרפה כרבנן\u0004 \u0005[הטריף אותה כ\u0006דעת \u0005חכמים]\u0006 החולקים על ר' יוסי בר' יהודה ומטריפים מוגרמת שכזו. \u0003ואי נמי כרבנן\u0004 \u0005[ואם גם כן\u0006 פסק \u0005כחכמים],\u0006 \u0003דאיבעי ליה חיובא לטבחא\u0004 \u0005[שהיה צריך לחייב את הטבח],\u0006 \u0003ומי שרי למימר כי האי גונא\u0004 \u0005[והאם מותר לומר כגון זה]\u0006 שאמרו לו רב כהנא ורב אסי לאותו אדם?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לכשיצא\u0004 הדיין מבית הדין, \u0003לא יאמר\u0004 לנידון: \u0003אני\u0004 הייתי \u0003מזכה וחבירי\u0004 היו \u0003מחייבין, אבל מה אעשה שחבירי רבו עלי, ועל זה\u0004 שעושה כך \u0003נאמר: \"הולך רכיל מגלה סוד\"\u0004 (משלי יא, יג)!","\u0003אלא\u0004 הכוונה היא שאמרו לו \u0003תרתי למעליותא\u0004 \u0005[שני\u0006 דברים \u0005לטובה\u0006 עשה לך\u0005],\u0006 האחד — במה שהטריף את הבהמה, ש\u0003לא אוכלך\u0004 \u0005[האכילך]\u0006 \u0003ספק איסורא\u0004 \u0005[איסור],\u0006 והשני — בזה שפטר את הטבח מלשלם לך \u0003ומנעך מספק גזילה,\u0004 שממון הטבח יהא בידיך, ואולי הוא פטור, שאין הבהמה טריפה.","ועוד בעניינים אלו של אומן שקלקל, \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003המראה דינר לשולחני\u0004 (חלפן כספים) והשולחני אמר לו שהדינר כשר, \u0003ונמצא\u0004 שהיה הדינר \u0003רע\u0004 וכתוצאה מכך נגרם לו הפסד. \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 אם היה שולחני \u0003אומן\u0004 — \u0003פטור,\u0004 אם היה \u0003הדיוט\u0004 — \u0003חייב. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בין\u0004 אם היה \u0003אומן בין\u0004 אם היה \u0003הדיוט\u0004 — \u0003חייב!\u0004","\u0003אמר רב פפא: כי תניא\u0004 \u0005[כאשר שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003אומן פטור\u0004 — הרי זה \u0003כגון\u0004 השולחנים \u0003דנכו ואיסור,\u0004 ש\u0003לא צריכי למיגמר\u0004 \u0005[צריכים ללמוד]\u0006 \u0003כלל,\u0004 שהם מומחים גדולים. ושואלים: \u0003אלא במאי\u0004 \u0005[במה]\u0006 \u0003טעו?\u0004 ומשיבים: \u0003טעו בסיכתא חדתא, דההיא שעתא דנפק מתותי סיכתא\u0004 \u0005[טעו בטביעה חדשה, שבאותה שעה יצאה מתחת המטבעה],\u0006 ומשום כך לא ידעו מה טיבה.","מסופר: \u0003ההיא איתתא דאחזיא דינרא\u0004 \u0005[אשה אחת שהראתה דינר]\u0006 \u0003לר' חייא\u0004 לשאול מה טיבו, \u0003אמר לה: מעליא\u0004 \u0005[מעולה]\u0006 \u0003הוא. למחר אתאי לקמיה\u0004 \u0005[באה לפניו]\u0006 \u0003ואמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אחזיתיה\u0004 \u0005[הראיתיו]\u0006 \u0003ואמרו לי\u0004 דינר \u0003בישא\u0004 \u0005[רע]\u0006 \u0003הוא, ולא קא נפיק\u0004 \u0005[יוצא]\u0006 \u0003לי,\u0004 כלומר, אין אנשים רוצים לקחת אותו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא \u0003לרב: זיל חלפיה ניהלה\u0004 \u0005[לך החלף אותו לה],\u0006 \u0003וכתוב\u0004 על \u0003פנקסי: \"דין עסק ביש\"\u0004 \u0005[\"זהו עסק רע\"],\u0006 כלומר, שזהו הפסד שלא היה מן הראוי לעשות אותו.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003דנכו ואיסור דפטירי\u0004 \u0005[ש\u0006הם \u0005פטורים]?\u0006 — \u0003משום\u0004 ש\u0003לא צריכי למיגמר\u0004 \u0005[צריכים ללמוד]\u0006 ובקיאים היטב? \u0003ר' חייא נמי לאו למיגמר קא בעי\u0004 \u0005[גם כן לא היה צריך ללמוד]\u0006 שבוודאי היה מומחה בדבר! ומשיבים: \u0003ר' חייא לפנים משורת הדין הוא דעבד\u0004 \u0005[שעשה],\u0006 שבאמת לא היה צריך להחזיר לה, אלא נהג לפנים משורת הדין ונתן לה. \u0003כדתני\u0004 \u0005[כפי ששנה]\u0006 \u0003רב יוסף\u0004 על הכתוב: \"והודעת להם את הדרך ילכו בה ואת המעשה אשר יעשון\" (שמות יח, כ), שכך פירשו: \u0003\"והודעת להם\"\u0004 — \u0003זה\u0004"],["\u0003בית חייהם,\u0004 כלומר, לימוד התורה שהיא מקור החיים, \u0003\"את הדרך\"\u0004 — \u0003זו גמילות חסדים, \"ילכו\"\u0004 — \u0003זו ביקור חולים, \"בה\"\u0004 — \u0003זו קבורה, \"את המעשה\"\u0004 — \u0003זה הדין, \"אשר יעשון\"\u0004 — \u0003זו לפנים משורת הדין.\u0004 משמע שהתורה עצמה מצווה שאדם ינהג לפנים משורת הדין.","מסופר: \u0003ריש לקיש אחוי ליה דינרא\u0004 \u0005[הראה לו דינר]\u0006 \u0003לר' אלעזר,\u0004 שיאמר מה טיבו. \u0003אמר\u0004 לו ר' אלעזר: \u0003מעליא\u0004 \u0005[מעולה]\u0006 \u0003הוא. אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003חזי דעלך קא סמכינא\u0004 \u0005[ראה שעליך אני סומך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: \u0003כי סמכת עלי מאי למימרא\u0004 \u0005[כאשר אתה סומך עלי מה\u0006 רצונך \u0005לומר\u0006 בזה\u0005],\u0006 \u0003דאי משתכח בישא בעינא לאיחלופי לך\u0004 \u0005[שאם יימצא\u0006 לבסוף שהוא דינר \u0005רע\u0006 ש\u0005צריך אני להחליף לך]\u0006 אותו בדינר טוב? \u0003והא את\u0004 \u0005[והרי אתה]\u0006 עצמך \u0003הוא\u0004 ש\u0003אמרת\u0004 שתשלום על דבר זה כשיטת \u0003ר' מאיר הוא, דדאין דינא דגרמי\u0004 \u0005[שדן דין של גורמים]\u0006 ומחייב גם מי שגורם להפסד ואפילו לא הזיק במישרין לרכוש חבירו. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 היתה כוונתך לומר שזו שיטת \u0003ר' מאיר ולא סבירא לן כוותיה\u0004 \u0005[ואין אנו סבורים כמותו]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003לא,\u0004 כוונתי היתה ששיטת \u0003ר' מאיר\u0004 היא \u0003וסבירא לן כוותיה\u0004 \u0005[ואנו סבורים כמותו].\u0006","ומעתה שואלים: \u0003הי\u0004 \u0005[לאיזה]\u0006 מדברי \u0003ר' מאיר\u0004 מתייחסים כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה לדעה זו של \u0003ר' מאיר (ד' ל' מ' פ'\u0004 הוא \u0003סימן\u0004 לראשי תיבות של ההלכות הנזכרות כאן: \u0003ד\u0004ן את הדין, \u0003ל\u0004צבוע לו, \u0003מ\u0004סכך גפנו, מחיצת כרם שנ \u0003פ\u0004 רצה","\u0003)\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003דן\u0004 הדיין \u0003את הדין\u0004 וטעה בדינו כגון ש\u0003זיכה את החייב,\u0004 או ש\u0003חייב את הזכאי,\u0004 או ש\u0003טימא את הטהור,\u0004 או ש\u0003טיהר את הטמא\u0004 ונמצא שגרם בכך הפסד ממוני לנידון — \u0003מה שעשה עשוי\u0004 ואין מחזירים את הדין, \u0003וישלם\u0004 את הנזק \u0003מביתו,\u0004 כלומר, מכספו הפרטי.","הרי שחייב למרות שרק גרם להפסד, ואולם \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה]\u0006 על הלכה זו, \u0003אמר ר' אילעא אמר רב:\u0004 מדובר כאן לא בפסק דין בלבד של הדיין, אלא בעשיית מעשה על ידו, \u0003והוא שנטל\u0004 הדיין בעצמו ממי שחייבו בדין \u0003ונתן\u0004 לאחר \u0003ביד,\u0004 ואם כן, אין זה גרם בלבד אלא מעשה ממש!","\u0003אלא\u0004 תאמר כי הכוונה היא ל\u0003הא\u0004 \u0005[זו]\u0006 שאמר \u0003ר' מאיר, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 נתן צמר לצבע \u0003לצבוע לו אדום וצבעו שחור,\u0004 או לצבוע לו \u0003שחור וצבעו אדום\u0004 — \u0003ר' מאיר אומר: נותן לו דמי צמרו,\u0004 גם משם אין להוכיח, שהוא חייב למרות שרק גרם להפסד. \u0003התם קא עביד\u0004 \u0005[שם הוא עושה]\u0006 \u0003בידים\u0004 מעשה לקלקל!","\u0003אלא\u0004 תאמר כי הכוונה ל\u0003הא\u0004 \u0005[זו]\u0006 שאמר \u0003ר' מאיר, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המסכך גפנו על גבי תבואתו של חבירו\u0004 — \u0003הרי זה\u0004 בכך \u0003קידש\u0004 (אסר) אותה משום כלאיים בכרם, \u0003וחייב\u0004 לשלם לבעל התבואה את הנזק. ואולם גם משם אין ראיה, שכן \u0003התם נמי קא עביד\u0004 \u0005[שם גם כן הוא עושה]\u0006 מעשה \u0003בידים!\u0004","\u0003אלא\u0004 נאמר כי הכוונה ל\u0003הא\u0004 \u0005[זו]\u0006 שאמר \u0003ר' מאיר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מחיצת הכרם שנפרצה\u0004 והיה סמוך לה שדה תבואה —"],["\u0003אומר לו\u0004 בעל שדה התבואה לבעל הכרם \u0003גדור\u0004 את הפירצה שבמחיצה לפני שיאסור הכרם את התבואה אם תצמח עימו, \u0003נפרצה\u0004 שוב — \u0003אומר לו \"גדור\", נתייאש ממנה ולא גדרה\u0004 — \u0003הרי זה קידש\u0004 (אסר) את התבואה \u0003וחייב באחריותו\u0004 לשלם עבור התבואה. וכאן רואים שאפילו כאשר לא עשה מעשה כלל — חייב באחריות על הנזק שגרם, ומכאן שר' מאיר סבור שדנים \"דינא דגרמי\".","\u0003הנותן צמר לצבע והקדיחו\u0004 (שרפו) ב\u0003יורה\u0004 (כלי בישול) תוך כדי צביעתו והתקלקל הצמר לגמרי, ואין כאן שבח כלל, אלא הפסד גמור — \u0003נותן לו\u0004 הצבע לבעלים \u0003דמי צמרו.\u0004 אם \u0003צבעו כאור\u0004 (כעור), שהצבע לא נקלט יפה בצמר, הרי \u0003אם השבח\u0004 עליית ערך הצמר על ידי הצביעה הזו הוא \u0003יתר על היציאה\u0004 (ההוצאות, ובכללן שכרו) שהוציא הצבע — \u0003נותן לו\u0004 בעל הצמר לצבע \u0003את היציאה, ואם היציאה יתירה על השבח\u0004 — \u0003נותן לו את השבח.\u0004","נתן בעל הצמר לצבע צמר כדי \u0003לצבוע לו\u0004 אותו בצבע \u0003אדום\u0004 ושינה הצבע \u0003וצבעו שחור,\u0004 או נתן לו לצבוע \u0003שחור וצבעו אדום\u0004 — \u0003ר' מאיר אומר: נותן לו\u0004 הצבע לבעלים \u0003דמי צמרו. ר' יהודה אומר:\u0004 אף כאן, \u0003אם השבח יתר על היציאה\u0004 — \u0003נותן לו\u0004 הבעלים לצבע \u0003את היציאה, ואם היציאה יתירה על השבח\u0004 — \u0003נותן לו את השבח.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש לשון \u0003\"כאור\"\u0004 הנזכר במשנתנו? \u0003אמר רב נחמן אמר רבה בר בר חנה: כלבוס.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003כלבוס? אמר רבה בר שמואל:\u0004"],["\u0003כפרא דודי\u0004 \u0005[קינוח הקדירה],\u0006 כלומר, שצבע אותו בשיירי צבע שהם חומר גרוע לצביעה.","במשנה שנינו שנחלקו ר' מאיר ור' יהודה מה הדין אם שינה האומן מרצון הבעלים. ובאותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנותן עצים לחרש\u0004 (נגר) \u0003לעשות מהן כסא ועשה מהן ספסל,\u0004 או נתן לעשות \u0003ספסל ועשה מהן כסא\u0004 — \u0003ר' מאיר אומר: נותן לו דמי עציו,\u0004 שכיון ששינה האומן מדעת בעל הבית — קנה את גוף הכלי שעשה, ואינו מחזיר אלא דמי העצים. \u0003ר' יהודה אומר:\u0004 אינו קונה את הכלי, אבל משום ששינה מדעת בעל הבית ידו על התחתונה, בענין זה ש\u0003אם השבח יתר על היציאה\u0004 (ההוצאות, ובכללן שכרו) — \u0003נותן לו את היציאה, ואם היציאה יתירה על השבח\u0004 — \u0003נותן לו את השבח.\u0004","\u0003ומודה ר' מאיר\u0004 לר' יהודה ש\u0003אם נתן עצים לחרש לעשות מהן כסא נאה ועשה מהן כסא כעור,\u0004 או שנתן לו עצים כדי לעשות מהם \u0003ספסל נאה ועשה ספסל כעור,\u0004 שבמקרה זה שלא עשה שינוי מהותי מדעת בעל הבית \u0003אם השבח יתר על היציאה\u0004 — \u0003נותן לו דמי היציאה, ואם היציאה יתירה על השבח\u0004 — \u0003נותן לו דמי השבח.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003יש שבח סמנין\u0004 (צבעים) \u0003על הצמר,\u0004 כלומר, שצבעים, לאחר שצבע בהם צמר, נחשבים כדבר של ממש על גבי הצמר, \u0003או אין שבח סמנין על הצמר?\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 מהי בדיוק השאלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר ש\u0003גזל\u0004 חומרי גלם של \u0003סמנין\u0004 \u0003ודקינהו ותרנהו\u0004 \u0005[ושחק אותם ושרה אותם]\u0006 במים כדי לרככם לצבע \u0003וצבע בהן, תיפוק ליה\u0004 \u0005[תצא לו]\u0006 ההלכה שחייב לשלם תמורתם \u0003משום דקנינהו\u0004 \u0005[שקנה אותם]\u0006 \u0003בשינוי!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא במקרה ש\u0003גזל סמנין שרויין\u0004 ומוכנים לצביעה \u0003וצבע בהו\u0004 \u0005[בהם]\u0006 את צמרו, שלא עשה בהם שינוי. ובמקרה כזה השאלה היא: \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם \u0003יש שבח סמנין על גבי צמר, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הנגזל: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את \u0003סמנאי דשקלתינהו\u0004 \u0005[הסממנים שלי שלקחת אותם],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אין שבח סמנין על גבי הצמר, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הגזלן בתשובה: \u0003לית\u0004 \u0005[אין]\u0006 \u0003לך גבאי\u0004 \u0005[אצלי]\u0006 \u0003ולא מידי\u0004 \u0005[דבר]?\u0006","בדחייה לכך \u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה על כך: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אין שבח סמנין על גבי צמר, מי מצי אמר ליה\u0004 \u0005[האם יכול לומר לו]\u0006 \u0003לית\u0004 \u0005[אין]\u0006 \u0003לך גבאי\u0004 \u0005[אצלי]\u0006 \u0003ולא מידי\u0004 \u0005[דבר]?\u0006 \u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 הנגזל: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי סמנאי דאפסדתינהו\u0004 \u0005[\u0006את \u0005הסממנים שלי שהפסדת אותם]!\u0006","\u0003אלא\u0004 צריכים לחזור מהסבר זה ולומר כי השאלה היא \u0003להך גיסא\u0004 \u0005[לצד זה],\u0006 להצגה אחרת של צדדי הבעיה: האם \u0003אין שבח סמנין על גבי הצמר ובעי שלומי ליה\u0004 \u0005[וצריך לשלם לו]\u0006 את דמי הסממנים שגזל ממנו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003יש שבח סמנין על גבי צמר, ואמר ליה\u0004 \u0005[ו\u0006יכול הגזלן \u0005לומר לו]:\u0006 \u0003הא מנחי קמך שקלינהו\u0004 \u0005[הרי\u0006 הסממנים \u0005מונחים לפניך,\u0006 על הצמר, \u0005קח אותם].\u0006 ושואלים בתמיהה: \u0003שקלינהו\u0004 \u0005[קח אותם]?\u0006 \u0003במאי שקליה\u0004 \u0005[במה יקח אותם],\u0006 \u0003בצפון\u0004 \u0005[בסבון]?\u0006 \u0003צפון עבורי מיעבר\u0004 \u0005[הסבון מוריד]\u0006 את הצבע, אבל \u0003השבה\u0004 של הסממנים לבעליהם \u0003לא עביד\u0004 \u0005[עושה]!\u0006","\u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — בשאלה זו: \u0003כגון\u0004 ש\u0003גזל צמר וסמנין דחד\u0004 \u0005[של\u0006 אדם \u0005אחד],\u0006 \u0003וצבעיה לההוא\u0004 \u0005[וצבעו לאותו]\u0006 \u0003צמר בהנך סמנין\u0004 \u0005[באותם הסממנים],\u0006 \u0003וקא מהדר ליה ניהליה\u0004 \u0005[ומחזיר לו\u0006 לנגזל\u0005]\u0006 את \u0003הצמר\u0004 הצבוע, ואז עולה השאלה: האם \u0003יש שבח סמנין על גבי הצמר, וקא מהדר ליה\u0004 \u0005[ומחזיר לו]\u0006 בכך \u0003סמנין וצמר\u0004 שגזל ממנו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אין שבח סמנין על גבי צמר, ו\u0004את ה\u0003צמר מהדר ליה\u0004 \u0005[מחזיר לו],\u0006 \u0003סמנין לא מהדר ליה\u0004 \u0005[אינו מחזיר לו]\u0006 ועליו לשלם על כך לחוד?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה: \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 תשובה לשאלה זו משום \u0003דאייקר ליה ניהליה בדמי\u0004 \u0005[שהתייקר לו\u0006 הצמר \u0005בדמים],\u0006 שהרי צמר צבוע יקר יותר, ואם כן הוא משיב לו לפי ערך גם את שווי הסממנים! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דזל ציבעא\u0004 \u0005[שהוזל הצבע]\u0006 ואין בעל הסמנים מקבל את ערך סמניו בדרך זו, ונמצא שאם אכן אין הסממנים שעל גבי הצמר נחשבים כדבר של ממש — צריך לשלם לו את מחירה בנפרד. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן דומה: \u0003כגון שצבע בהו קופא\u0004 \u0005[בהם קוף],\u0006 שלא התייקר הדבר על ידי הצביעה.","\u0003רבינא אמר: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 לא במקרה של גזלן, אלא \u0003כגון\u0004 שהיה \u0003צמר דחד\u0004 \u0005[של\u0006 אדם \u0005אחד]\u0006 \u0003וסמנין דחד\u0004 \u0005[של\u0006 אדם \u0005אחד],\u0006 \u0003וקאתי\u0004 \u0005[ובא]\u0006 \u0003קוף וצבעיה לההוא\u0004 \u0005[וצבעו לאותו]\u0006 \u0003צמר בהנך\u0004 \u0005[באותם]\u0006 \u0003סמנין\u0004 באופן ששום אדם לא עשה מעשה, ואז השאלה היא: האם \u0003יש שבח סמנין על גבי צמר, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הסממנים לבעל הצמר: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי סמנאי דגבך נינהו\u0004 \u0005[\u0006את \u0005הסממנים שלי שאצלך הם],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אין שבח סמנין על גבי צמר, ואמר ליה\u0004 \u0005[ואומר לו]\u0006 בעל הצמר בתשובה לטענתו: \u0003לית\u0004 \u0005[אין]\u0006 \u0003לך גבאי\u0004 \u0005[אצלי]\u0006 \u0003כלום\u0004 שאתה יכול לתבוע?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו במשנה: \u0003בגד שצבעו בקליפי\u0004 (קליפות) של פירות \u0003ערלה\u0004 שעשו מהן צבע — \u0003ידלק\u0004 (ישרף) הבגד, כדין פירות ערלה שאסורים בהנאה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חזותא מילתא היא\u0004 \u0005[המראה\u0006 הצבע, \u0005דבר\u0006 של ממש \u0005הוא]\u0006 ומשום כך ישרף כל הבגד בגלל צבע הערלה שעליו, ואם כן מכאן ראיה שיש שבח סמנים על גבי צמר!","\u0003אמר רבא: הנאה הנראה לעינים אסרה תורה,\u0004 מכיון שהנאה זו של צבע הבגד היא נראית לעין, אף על פי שאין בה ממש, אסרה התורה ליהנות מזה, אבל אין זה אומר שצבע דבר של ממש הוא אף בענייני דיני ממונות. ומנין שאסרה אותו התורה במפורש? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \u0003\"ערלים לא יאכל\"\u0004 (ויקרא יט, כג): \u0003אין לי\u0004 ללמוד מכתוב זה \u0003אלא איסור אכילה\u0004 של פירות ערלה. \u0003מנין ש\u0004גם \u0003לא יהנה ממנו, ולא יצבע בו, ולא ידליק בו את הנר?\u0004","\u0003תלמוד לומר: \"וערלתם ערלתו את פריו\u0004 שלוש שנים יהיה לכם \u0003ערלים לא יאכל\"\u0004 (ויקרא יט, כג), שהכפלת לשון \"ערלה\" כאן באה \u0003לרבות את כולם,\u0004 כל מיני הנאה שיש בזה.","ומציעים עוד פתרון לבעיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003בגד שצבעו ב\u0004צבע שנעשה מ\u0003קליפי\u0004 פירות \u0003שביעית\u0004 — \u0003ידלק\u0004 משהגיע זמן הביעור, והרי שהצבע אכן דבר של ממש הוא! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין שביעית: \u0003\"תהיה\u0004 כל תבואתה לאכול\u0003\"\u0004 (שם כה, ז), וכוונתו: \u0003בהויתה תהא,\u0004 ואין דין שביעית בטל מתבואתה בכל אופן בו היא מצוייה."],["בענין זה \u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003בגד שצבעו בקליפי\u0004 (קליפות) פירות \u0003ערלה\u0004 — \u0003ידלק\u0004 (ישרף) \u0003אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 ש\u0003חזותא מילתא היא\u0004 \u0005[מראה, דבר הוא]\u0006 ונחשב. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה אחרת: \u0003רביעית דם\u0004 של המת \u0003שנבלעה בבית\u0004 — \u0003הבית\u0004 כלומר, כל הכלים המצויים בבית, \u0003טמא,\u0004 משום אוהל הטומאה, שהבית האהיל עליהם ועל הטומאה ונטמאו. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003הבית טהור.\u0004 והסבירו את שתי הדעות הללו: \u0003ולא פליגי\u0004 \u0005[נחלקו],\u0006 שכל אחד דיבר במקרה אחר: \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שהבית טמא מדובר \u0003בכלים דהוו מעיקרא\u0004 \u0005[שהיו מתחילה]\u0006 בבית קודם שנבלעה רביעית הדם בבית, \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שהבית טהור מדובר \u0003בכלים דאתו\u0004 \u0005[שבאו]\u0006 לתוכו \u0003לבסוף,\u0004 לאחר שנבלעה רביעית הדם בבית,","ובהמשך המשנה שנינו: אם \u0003נבלעה\u0004 רביעית הדם \u0003בכסות\u0004 — \u0003רואין\u0004 (בודקים אותה): \u0003אם מתכבסת הכסות\u0004 בכמות מסויימת של מים \u0003ו\u0004עדיין \u0003יוצא ממנה\u0004 בכביסה שיעור \u0003רביעית דם\u0004 בנוסף לאותה כמות מים — הריהי \u0003טמאה,\u0004 שבגד זה כשהיה הדם בו מטמא באוהל את מה שבבית בטומאת המת. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שיוצא ממנה בכביסה שיעור דם פחות מרביעית — \u0003טהורה\u0004 מלטמא את הנמצא בבית בטומאת אוהל, משמע שאף שברור שנבלעה רביעית דם בבגד והיא נראית בו, מכל מקום המראה אינו נחשב!","\u0003אמר רב כהנא: מקולי רביעיות שנו כאן,\u0004 כלומר, אנו מדברים פה בדין שאינו מן הדינים הרגילים אלא במקרה שיש בו צד קל מיוחד, שכאן מדובר \u0003בדם תבוסה,\u0004 שהוא דם היוצא מן המת ולא ברור אם יצא ממנו במותו או בחייו, וטומאתו היא רק \u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 ולכן הקלו בדינו. מה שאין כן בערלה שהיא מן התורה.","אגב שהובאה סתירה שהביא רבא, מביאים סתירה נוספת שהביא רבא, שיש לה קשר לענייני ביעור של חומרי צבע בשביעית. \u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 דברים שהם \u0003ממין הצובעין,\u0004 צמחים שעשויים לצביעה, כגון \u0003ספיחי\u0004 (גידולים שעלו מאליהם בשדה, שלא על ידי זריעה) של \u0003סטים וקוצה\u0004 — \u0003יש להן\u0004 דין \u0003שביעית, ולדמיהן\u0004 אם מוכרים אותם גם כן יש דין \u0003שביעית, יש להן\u0004 דין \u0003ביעור\u0004 שצריכים לבער אותם מן הבית ולחלק אותם כאשר כלו מן השדה, \u0003ו\u0004גם \u0003לדמיהן\u0004 יש דין \u0003ביעור. אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 ש\u0003עצים\u0004 עצמם אף שאינם פירות \u0003יש בהן משום קדושת שביעית.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003עלי קנים ועלי גפנים שגיבבן בחבא\u0004 (ערימה) \u0003על פני השדה.\u0004 אם \u0003לקטן\u0004 מתחילה \u0003לאכילה\u0004 — \u0003יש בהן משום קדושת שביעית,\u0004 אם לקטן \u0003לעצים\u0004 — \u0003אין בהן משום קדושת שביעית,\u0004 משמע שעצים אין בהם קדושת שביעית!","\u0003ומשני\u0004 \u0005[ומתרץ]\u0006 רבא עצמו את קושייתו, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין השביעית: \u0003\"\u0004והיתה שבת הארץ לכם \u0003לאכלה\"\u0004 (ויקרא כה, ו), לומר שאיסור שביעית חל בדבר שהוא כמו הדברים שהם לאכילה, \u0003במי שהנאתו וביעורו שוין\u0004 (ביחד), שבזמן שנהנים ממנו הוא מתבער מן העולם. \u0003יצאו עצים שהנאתן\u0004 (ההנאה שיש מהם) היא ל\u0003אחר ביעורן.\u0004 שעצים שעושים מהם גחלים הרי הם מתבערים מן העולם בשעת בעירתם, אבל עיקר הנאתם היא רק לאחר מכן, משעה שנעשו גחלים. מה שאין כן מיני צבע, שמתבערים מן העולם בשעה שנהנים מהם בצביעה.","ומקשים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003עצים דמשחן\u0004 \u0005[עצי שמן]\u0006 שמשמשים לתאורה, שמדליקים בהם אבוקה, ש\u0003הנאתן וביעורן שוין\u0004 ובכל זאת לא חילקה הברייתא, ואף בהם אין קדושת שביעית!","\u0003אמר רבא:\u0004"],["\u0003סתם עצים להסקה הן עומדין,\u0004 ואף עצים שמשמשים לתאורה עיקר שימושם הוא להסקה.","\u0003אמר רב כהנא: ו\u0004דינם בשביעית של \u0003עצים להסקה\u0004 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מוסרין פירות שביעית לא למשרה\u0004 (לשרות פשתן במשקיהם, כגון יין) \u0003ולא לכבוסה\u0004 (כביסה). \u0003ור' יוסי אומר: נותנין פירות שביעית לתוך המשרה ולתוך הכבוסה.\u0004","ומבררים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]?\u0006 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין שביעית: \u0003\"\u0004והיתה שבת הארץ לכם \u0003לאכלה\"\u0004 (ויקרא כה, ו), ללמדנו מיעוט: \u0003ולא למשרה, \"לאכלה\"\u0004 — \u0003ולא לכבוסה. ו\u0004אילו \u0003ר' יוסי\u0004 המתיר \u0003אומר\u0004 במענה לכך: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לכם\"\u0004 וכוונתו: \u0003לכל צרכיכם\u0004 ובכללם משרה וכביסה.","ושואלים: \u0003ורבנן נמי\u0004 \u0005[וחכמים גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לכם\",\u0004 ומה עושים הם בכתוב זה? ומשיבים: \u0003\"לכם\" דומיא\u0004 \u0005[בדומה]\u0006 למה שנאמר \u0003\"לאכלה\",\u0004 ללמדנו שהלכה זו נאמרה דווקא \u0003במי שהנאתו וביעורו שוין\u0004 (יחד), \u0003יצאו משרה וכבוסה שהנאתן אחר ביעורן.\u0004 כי ביעורם של הפירות הוא כשמביאים אותם למשרה או לתוך הכביסה, והנאתם היא רק לאחר גמר המלאכה.","ושואלים עוד: \u0003ור' יוסי נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לאכלה\",\u0004 וכיצד מפרש הוא כתוב זה? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 הכתוב \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכפי ששנינו\u0006 בברייתא\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"לאכלה\"\u0004 — \u0003ולא למלוגמא\u0004 (תחבושת). \u0003אתה אומר: \"לאכלה\"\u0004 — \u0003ולא למלוגמא, או אינו אלא \"לאכלה\"\u0004 — \u0003ולא לכבוסה?\u0004 לכך יש להשיב: \u0003כשהוא אומר: \"לכם\"\u0004 — \u0003הרי כבוסה אמור,\u0004 שגם היא בכלל צרכיכם, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"לאכלה\",\u0004 הרי זה בא למעט: \u0003\"לאכלה\"\u0004 — \u0003ולא למלוגמא.\u0004","והוא מסביר: \u0003ומה ראית לרבות הכבוסה\u0004 שהיא מותרת \u0003ולהוציא את המלוגמא\u0004 שהיא אסורה, ולמה לא נאמר ההיפך? ומשיבים: \u0003מרבה אני את הכבוסה ששוה בכל אדם,\u0004 שכל אדם נזקק לה, \u0003ומוציא אני את המלוגמא שאינו שוה בכל אדם\u0004 אלא רק בחולה ופצוע.","ואגב שהובאה מחלוקת זו, מעירים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנויה]:\u0006 \u0003\"לאכלה\"\u0004 — \u0003ולא למלוגמא, \"לאכלה\"\u0004 — \u0003ולא לזילוף\u0004 (הזיית יין לבישום הבית), \u0003\"לאכלה\"\u0004 — \u0003ולא לעשות ממנה אפיקטויזין\u0004 (סם הקאה), \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]?\u0006 — \u0003כ\u0004דעת \u0003ר' יוסי,\u0004 משום \u0003דאי כרבנן\u0004 \u0005[שאם\u0006 תאמר \u0005כ\u0006שיטת \u0005חכמים],\u0006 \u0003איכא נמי\u0004 \u0005[יש גם כן]\u0006 אופנים נוספים של איסור להשתמש בפירות שביעית כגון \u0003משרה וכבוסה.\u0004 ולפי זה עצי הסקה שמשמשים לכל אדם הם לדברי ר' יוסי בגדר \"לכם\", ומותר להשתמש בהם לכך, ולדברי חכמים כיון שאין הנאתם וביעורם שווים — אין משתמשים בהם לכך.","שנינו במשנה בענין הנותן צמר לצבע לצבוע לו אדום וצבעו שחור, ולהיפך, שלדעת ר' מאיר נותן לו דמי צמרו, ואילו \u0003ר' יהודה אומר\u0004 ש\u0003אם השבח\u0004 יתר על היציאה — נותן לו את היציאה, ואם היציאה יתירה על השבח — נותן לו את השבח. \u0003(סימן סבן).\u0004","ומסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יוסף אחורי ר' אבא\u0004 בעת שישבו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא, ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב הונא וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003הלכה כ\u0004שיטת \u0003ר' יהושע בן קרחה\u0004 בענין שיוזכר הלאה, \u0003והלכה כ\u0004שיטת \u0003ר' יהודה\u0004 שבמשנתנו.","\u0003אהדרינהו\u0004 \u0005[החזיר]\u0006 \u0003רב יוסף לאפיה\u0004 \u0005[את פניו]\u0006 כמראה שאין דעתו נוחה מן הדברים, ו\u0003אמר\u0004 כך: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' יהושע בן קרחה אצטריך\u0004 \u0005[הוצרך]\u0006 להיאמר שהלכה כמותו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 ש\u0003יחיד ורבים הלכה כרבים,\u0004 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבמקרה זה \u0003הלכה כיחיד.\u0004","כיון שהוזכר הדבר שואלים: אותה הלכה שנפסקה כשיטת \u0003ר' יהושע בן קרחה מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהושע בן קרחה אומר: מלוה בשטר אין נפרעין מהן,\u0004 מן הגויים את חובם ליהודי ביום חגם ובסמוך לו, משום שמשמחים אותם בכך שנפטרו מחובם, והולכים הגויים ומודים על כך לעבודה זרה. אבל \u0003מלוה על פה נפרעין מהן\u0004 אם הם מוכנים לפרוע לו, \u0003מפני שהוא כמציל מידם,\u0004 שהרי אין בידו ראיה לחובו. וחכמים סבורים שאין נפרעים מהם כלל.","ושוב חוזרים לדברי רב יוסף, \u0003אלא הלכה\u0004 במשנתנו \u0003כ\u0004שיטת \u0003ר' יהודה למה לי?\u0004 מדוע היה צריך רב הונא לומר זאת? הלא \u0003מחלוקת ואחר כך סתם היא, ו\u0004כלל הוא: \u0003מחלוקת ואחר כך סתם\u0004 — \u0003הלכה כסתם!\u0004 כיצד?","\u0003מחלוקת\u0004 יש בענין זה \u0003בבבא קמא\u0004 \u0005[בשער הראשון\u0006 של מסכת נזיקין\u0005]\u0006 כלומר, אצלנו בענין הנותן צמר לצבע כדי \u0003לצבוע לו\u0004 לו אותו בצבע \u0003אדום וצבעו שחור, שחור וצבעו אדום\u0004 — \u0003ר' מאיר אומר: נותן לו דמי צמרו, ר' יהודה אומר: אם השבח יתר על היציאה\u0004 — \u0003נותן לו את היציאה, ואם היציאה יתירה על השבח\u0004 — \u0003נותן לו את השבח. ו\u0004נשנה הדבר אחר כך כ\u0003סתם בבבא מציעא\u0004 \u0005[בשער האמצעי],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל המשנה\u0004 ממה שסוכם בינו לבין חבירו — \u0003ידו על התחתונה, וכל החוזר בו\u0004 מהסכם שעשה — \u0003ידו על התחתונה\u0004 והרי זה כשיטת ר' יהודה שבמשנתנו!","ומבררים: \u0003ורב הונא\u0004 מה הוא משיב לכך? ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 להיאמר במפורש שהלכה כר' יהודה שבמשנתנו, ומדוע? — \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 ש\u0003אין סדר למשנה,\u0004 שאין לומר שחלק אחד מוקדם לחלק אחר, \u0003ו\u0004לכן אפשר היה לומר גם במקרה שלפנינו כי \u0003סתם ואחר כך מחלוקת היא,\u0004 שקודם נשנתה המשנה שבבבא מציעא ואחריה נשנתה משנתנו, ובמקרה כזה אין פוסקים כסתם. ואומרים: \u0003ורב יוסף\u0004 מה הוא משיב לכך? \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אם אתה אומר שאין סדר במשנה כלל, אם כן \u0003כל מחלוקת ואחר כך סתמא\u0004 \u0005[סתם],\u0006 שהכלל הוא שהלכה כסתם, \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003אין סדר למשנה, ו\u0004שמא \u0003סתם ואחר כך מחלוקת היא\u0004 ואין הלכה כסתם.","\u0003ורב הונא\u0004 משיב לכך: \u0003כי לא אמרינן\u0004 \u0005[כאשר אין אנו אומרים]\u0006 ש\u0003אין סדר למשנה\u0004 — הרי זה דווקא \u0003בחדא מסכתא\u0004 \u0005[במסכת אחת],\u0006 שבאותה מסכת יש סדר, \u0003אבל בתרי מסכתות אמרינן\u0004 \u0005[בשתי מסכתות אומרים אנו]\u0006 שאין סדר למסכתות, וכאן מדובר בשתי מסכתות שונות. \u0003ו\u0004אילו \u0003רב יוסף\u0004 סבור ש\u0003כולה\u0004 \u0005[כל]\u0006 סדר \u0003נזיקין חדא מסכתא\u0004 \u0005[מסכת אחת]\u0006 \u0003היא,\u0004 ובבא קמא ובבא מציעא אינם אלא שני חלקים מתוך מסכת אחת.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 לא מטעם מחלוקת ואחר כך סתם, אלא מטעם אחר אמר שברור לנו שההלכה כר' יהודה — \u0003משום דקתני לה גבי הלכתא פסיקתא\u0004 \u0005[ששנה אותה\u0006 רבי \u0005יחד עם\u0006 \u0005הלכה פסוקה\u0006 אחרת\u0005]:\u0006 \u0003כל המשנה\u0004 — \u0003ידו על התחתונה, וכל החוזר בו\u0004 — \u0003ידו על התחתונה.\u0004","ומביאים ענין הקשור למחלוקת ר' מאיר ור' יהודה במשנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנותן מעות לשלוחו\u0004"],["כדי \u0003ליקח\u0004 (לקנות) \u0003לו\u0004 בהן \u0003חטין\u0004 ויהא השליח כעין שותף בעיסקה זו תמורת טירחתו — \u0003ולקח מהם שעורין,\u0004 או שנתן לו מעות כדי לקנות בהן \u0003שעורין\u0004 — \u0003ולקח מהם חטין,\u0004 במקרה זה \u0003תניא חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אם פחתו,\u0004 כלומר, אם נגרם הפסד כתוצאה מהשינוי במה שנקנה שלא כדין — \u0003פחתו לו,\u0004 לשליח, \u0003ואם הותירו,\u0004 שנגרם רווח כתוצאה מהשינוי שעשה השליח — \u0003הותירו לו,\u0004 שבשינוי ששינה מרצון המשלח הריהו כאילו ביטל את שליחותו ולקח שלא כדין את הכסף לעצמו, ומה שעשה — לעצמו עשה. \u0003ותני חדא\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחת\u0006 אחרת\u0005]:\u0006 \u0003אם פחתו\u0004 — \u0003פחתו לו, ואם הותירו\u0004 — \u0003הותירו לאמצע,\u0004 ששניהם חולקים בכך, והרי כאן סתירה בין הברייתות.","\u0003אמר ר' יוחנן: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כלומר, אין כאן סתירה, \u0003הא\u0004 \u0005[זו]\u0006 — כדעת \u0003ר' מאיר, והא\u0004 \u0005[וזו]\u0006 — כדעת \u0003ר' יהודה.\u0004","ומפרטים: \u0003הא\u0004 \u0005[זו]\u0006 הברייתא הראשונה שבכל מקרה נזקף השינוי לשליח היא כשיטת \u0003ר' מאיר דאמר\u0004 \u0005[שאומר]\u0006 במשנתנו \u0003שינוי\u0004 מדעת בעל הבית \u0003קונה,\u0004 אף לאומן, כגון שצבע צמר בצבע שונה מרצון בעל הבית וצריך להשיב לו דמי צמרו, ולכן אף השליח ששינה מדעת משלחו קנה את הדבר לעצמו, \u0003והא\u0004 \u0005[וזו]\u0006 הברייתא השניה היא כדעת \u0003ר' יהודה דאמר\u0004 \u0005[שאומר]\u0006 \u0003שינוי אינו קונה\u0004 ומה שקנה השליח בשינוי נקנה למשלח, אלא שמכל מקום אם נגרם הפסד בגלל עיסקה זו, שנעשתה שלא כדעת המשלח — ישא השליח בהפסדים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אלעזר: ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' מאיר\u0004 ששינוי מהוראת הבעלים קונה לאומן — \u0003אלא במידי דחזי ליה לגופיה\u0004 \u0005[בדבר שראוי לו ל\u0006משלח \u0005עצמו]\u0006 לשימושו, כגון לצבוע צמר ללובשו, או לעשות כסא לשבת עליו, שלא נזקק אלא לדבר שביקש. \u0003אבל\u0004 דבר שלוקח \u0003ל\u0004שם \u0003סחורה\u0004 — \u0003לא אמר,\u0004 שהרי בסחורה אין המשלח מעוניין בסחורה מסויימת אלא ברווח שיש בעיסקה, ואם יש רווח בדבר אף שנעשה שינוי מרצון המשלח — יסבור גם ר' מאיר שיש לבעל הכסף חלק בו!","\u0003אלא אמר ר' אלעזר,\u0004 יש לדחות הסבר זה ולומר הסבר אחר: \u0003הא והא\u0004 \u0005[זו וזו],\u0006 שתי הברייתות, כשיטת \u0003ר' מאיר, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 בברייתא הראשונה ששנינו שהשינוי קונה לשליח, מדובר שנתן לו מעות לקנות חטים (או שעורים) \u0003לאכילה\u0004 ולצורך עצמו, \u0003כאן,\u0004 בברייתא השניה שעולה ממנה שאין השליח קונה בשינוי מדובר שנתן לו מעות כדי לקנות לו חטים \u0003לסחורה.\u0004","ומסופר: \u0003מחכו עלה במערבא\u0004 \u0005[היו צוחקים על כך בארץ ישראל]\u0006 \u0003ל\u0004מה שאמר \u0003ר' יוחנן אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' יהודה,\u0004 ששינוי מדעת המשלח אינו קונה לשליח, ומה שקנה השליח נקנה אף למשלח למחצית הרווח, במקרה ששינה השליח משעורים לחיטים: \u0003וכי מי הודיעו לבעל חטין\u0004 (המוכר) \u0003שיקנה חטין לבעל מעות,\u0004 שהרי בעל החיטים לא ידע שנותן המעות אינו בעל המעות, וכיצד הוא יודע ויכול להתכוון להקנות את המיקח לבעל המעות הראשון וכיון שלא התכוון להקנות לבעל המעות — כיצד הוא זוכה במחצית הרווח?! \u0003מתקיף לה\u0004 \u0005[מקשה על כך],\u0006 על תמיהה זו שבארץ ישראל \u0003רב שמואל בר ססרטי: אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו\u0004 אם שלחו לקנות \u0003חטין ו\u0004קנה \u0003חטין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יזכה ברווח, שהרי גם כאן אפשר לומר: מי אמר לבעל החיטים שיקנה את החיטים לבעל המעות!","\u0003אמר ר' אבהו: שאני\u0004 \u0005[שונה]\u0006 מקרה של \u0003חטין וחטין, דשליחותיה קא עביד\u0004 \u0005[ש\u0006את \u0005שליחותו\u0006 של משלחו, השליח \u0005עושה]\u0006 \u0003וכי\u0004 \u0005[וכמו]\u0006 \u0003בעל הבית דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","\u0003תדע\u0004 שכן הוא, ששליח שמקיים את שליחותו הוא נחשב כבעל הבית, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אחד המקדיש\u0004 את כל \u0003נכסיו, ואחד המעריך את עצמו\u0004 (שנודר שהוא נותן את ערכו למקדש, כמבואר בויקרא פרק כז), \u0003אין לו\u0004 לגזבר ההקדש שגובה ממנו לגבות לא \u0003בכסות אשתו\u0004 של המקדיש או המעריך, \u0003ולא בכסות בניו, ולא בצבע שצבע לשמן\u0004 (עבורם), \u0003ולא בסנדלים חדשים שלקחן\u0004 (קנה אותם) \u0003לשמן.\u0004","ויש לשאול גם כאן: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהיה הדין כך? \u0003לימא הכא נמי\u0004 \u0005[נאמר כאן גם כן]:\u0006 \u0003מי הודיעו לצבע שיקנה צבעו לאשה\u0004 ולא לבעל, והרי את מעותיו קיבל מהבעל ולא מהאשה והבנים? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 שבכל מקום שנשלח אדם ואינו משנה מרצון משלחו \u0003דשליחותיה קא עביד\u0004 \u0005[ש\u0006את \u0005שליחותו\u0006 של המשלח \u0005הוא עושה],\u0006 \u0003וכיד אשתו דמי\u0004 \u0005[נחשב]\u0006 הבעל, וכיון שהתכוון הבעל לקנות הצבע עבור אשתו — נקנה לה בשליחותו? \u0003הכא\u0004 \u0005[כאן]\u0006 בנשלח לקנות חיטים וקנה חיטים \u0003נמי שליחותיה קא עביד\u0004 \u0005[גם כן שליחותו\u0006 של המשלח \u0005הוא עושה]\u0006 \u0003וכיד בעל הבית דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","\u0003אמר ר' אבא: לא,\u0004 מדינו של מקדיש ומעריך אין להוכיח, שכן אפשר לומר ש\u0003כל המקדיש נכסיו,\u0004 מתחילה \u0003אין דעתו על כסות אשתו ובניו,\u0004 ומכיון שכך מעיקרם לא נכנסו לכלל הקדש.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך,\u0006 על סברה זו\u0005]\u0006 \u0003ר' זירא: וכי דעתו של אדם על תפיליו\u0004 להקדיש אותם? \u0003ו\u0004בכל זאת \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדיש נכסיו\u0004 — \u0003מעלין\u0004 (מעריכים) \u0003לו\u0004 גם את ה\u0003תפילין\u0004 שלו בתוך מה שגובים ממנו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אין\u0004 \u0005[כן],\u0006 \u0003דעתו של אדם על תפילין\u0004 להקדישן עם שאר נכסיו, ומדוע? \u0003המקדיש נכסיו סבר\u0004 \u0005[סבור]:\u0006 \u0003מצוה קא עבידנא\u0004 \u0005[אני עושה]\u0006 ולכן הוא כולל בכך גם את התפילין שלו, שגם הם ענין של מצוה. \u0003ו\u0004אולם \u0003אין דעתו של אדם על כסות אשתו ובניו\u0004 — \u0003משום איבה,\u0004 שחושש שתהיה איבה בינו ובינם, ומשום כך מתחילה אינו מקדיש את בגדיהם ואת סנדליהם החדשים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אושעיא: והלא\u0004 אף \u0003חייבי ערכין שנו כאן, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003חייבי ערכין ממשכנין אותן\u0004 בעל כורחם, עד שישלמו מה שנדרו.","ויש לשאול: \u0003וכי דעתו של אדם\u0004 בשעה שהוא מעריך את עצמו אף \u0003על עצמו למשכנו?!\u0004 ומכאן מוכח שאין מתחשבים בנימוק שלא היתה דעתו של אדם להקדש זה.","\u0003אלא אמר ר' אבא,\u0004 כך יש לומר: \u0003כל המקדיש נכסיו\u0004 — \u0003נעשה כמי שהקנה להן\u0004 לאשתו ובניו \u0003כסות אשתו ובניו מעיקרא\u0004 \u0005[מתחילה,\u0006 קודם לכן\u0005]\u0006 ולכן הם אינם בכלל ההקדש.","ובענין זה של שיטת בני ארץ ישראל שהקונה עבור חבירו — אין חבירו קונה, מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הלוקח\u0004 (הקונה) \u0003שדה בשם\u0004 (לצורך) \u0003חבירו\u0004 — \u0003אין כופין אותו למכור. ואם אמר לו\u0004 בזמן הקניה \u0003\"על מנת\"\u0004 — \u0003כופין אותו למכור.\u0004","ושואלים: \u0003מאי קאמר?\u0004 \u0005[מה נאמר\u0006 פה, מה משמעות הדברים\u0005]?\u0006 \u0003אמר רב ששת, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003הלוקח שדה מחבירו בשם ריש גלותא\u0004 \u0005[ראש הגולה],\u0006 שהוא אומר למוכר שהוא קונה עבור ראש הגולה, או בשמו של אדם תקיף אחר — \u0003אין כופין אותו\u0004 אנשי \u0003ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 \u0003למכור\u0004 לקונה זה, כלומר, לחזור ולכתוב שטר ולהעביר על שמו של הקונה את השדה. \u0003ואם אמר\u0004 הקונה למוכר בשעה שקנה ממנו את השדה \u0003\"על מנת\"\u0004 שהתנה את הקניה בכך שראש הגולה ירשום על שמו את השדה — \u0003כופין את ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 \u0003למכור\u0004 את השדה, כלומר, לכתוב שטר על שם הקונה האמיתי. ודנים בברייתא זו לפי הפירוש שנתן לה רב ששת.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הלוקח שדה בשם ריש גלותא\u0004 — \u0003אין כופין אותו ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 \u0003למכור,\u0004 ומדייקים: \u0003מכלל דמקנא קניא ליה\u0004 \u0005[מכאן ש\u0006היא, השדה \u0005קנויה לו],\u0006 למרות שקנה בשמו של ראש הגולה. אם כן, \u0003לימא פליגא דבני מערבא\u0004 \u0005[האם נאמר\u0006 ש\u0005חולקת\u0006 שיטה זו \u0005על בני ארץ ישראל]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003וכי מי הודיעו לבעל חטין שיקנה חטין לבעל הבית,\u0004 ואף כאן, מי הודיעו לבעל השדה שהוא קונה לעצמו?","ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[כך]\u0006 הרי זה \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 שכן יש לפרש דבר זה \u0003כגון דאודעיה\u0004 \u0005[שהודיעו]\u0006 \u0003לבעל שדה, ואודעינהו לסהדי\u0004 \u0005[והודיע לעדים]\u0006 שבאמת הוא קונה לשם עצמו.","\u0003אלא\u0004 דבר אחר בפירוש זה קשה: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של אותה הלכה\u0005]:\u0006 \u0003\"על מנת\"\u0004 — \u0003כופין אותו ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 \u0003למכור,\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 כופים אותו? \u0003ולימא ריש גלותא\u0004 \u0005[ושיאמר ראש הגולה]:\u0006 \u0003לא יקרייכו בעינא\u0004 \u0005[\u0006את \u0005כבודכם אני רוצה],\u0006 \u0003ולא זילותייכו בעינא\u0004 \u0005[\u0006את \u0005זלזולכם אני רוצה],\u0006 שאתם משתמשים בשמי לכבוד, ומצד שני, מזלזלים בי אחר כך ומכריחים אותי להעשות כמוכר שדות.","\u0003אלא אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 כך יש לפרש את הברייתא: \u0003הלוקח שדה\u0004 וכותב את השטר \u0003בשם חבירו,\u0004 שהוא \u0003ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 —"],["\u0003אין כופין את המוכר למכור\u0004 את השדה \u0003זימנא אחריתי\u0004 \u0005[פעם אחרת],\u0006 כלומר, לכתוב שטר מכירה חדש, לקונה האמיתי על שמו. \u0003ואם אמר לו \"על מנת\u0004 שייכתב שטר נוסף על שמי \u0003\"\u0004— \u0003כופין את המוכר למכור,\u0004 כלומר, לכתוב לו שטר נוסף על שמו.","ומבררים דרך פירוש זו: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הלוקח\u0004 (הקונה) \u0003שדה בשם חבירו\u0004 — \u0003אין כופין את המוכר למכור זימנא אחריתי\u0004 \u0005[פעם אחרת].\u0006 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו\u0006 הקונה\u0005]:\u0006 הלא \u0003מידע ידעת דאנא לנפשאי שקילנא\u0004 \u0005[ידעת שאני לעצמי אני לוקח],\u0006 \u0003ופנחיא בעלמא\u0004 \u0005[והגנה בלבד]\u0006 \u0003הוא דקבעינא\u0004 \u0005[שרציתי]\u0006 בזה שאמרתי לך שאני קונה עבור ראש הגולה, \u0003וזוזי בכדי לא שדינא\u0004 \u0005[וכסף לחינם איני זורק]\u0006 לקנות שדה עבור אחר, \u0003אלא אדעתא דכתב ליה שטרא אחרינא\u0004 \u0005[על דעת שתכתוב לו,\u0006 לי, \u0005שטר אחר]\u0006 לאחר מכן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר בתשובה לכך: \u0003עניינא עבדי\u0004 \u0005[ענין עשיתי]\u0006 \u0003לך בהדי\u0004 \u0005[עם]\u0006 \u0003ההוא דזבנת ליה בשמיה\u0004 \u0005[שקנית לו בשמו],\u0006 לך אליו \u0003ו\u0004הוא \u0003יכתוב לך שטרא אחרינא\u0004 \u0005[שטר אחר].\u0006","ועל המשך הברייתא לפירוש זה \u0003ואם אמר לו \"על מנת\"\u0004 — \u0003כופין את המוכר למכור,\u0004 שואלים: גם כאן \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא במקרה ש\u0003אמר להו לסהדי קמיה דידיה\u0004 \u0005[להם לעדים בפניו,\u0006 בפני המוכר\u0005]:\u0006 \u0003חזו דשטרא אחרינא קא בעינא\u0004 \u0005[ראו ששטר אחר אני רוצה].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו\u0006 המוכר\u0005]:\u0006 \u0003אמינא שטרא מהיאך דקא שקלת בשמיה קאמרת\u0004 \u0005[אמרתי\u0006 סבור הייתי כי \u0005שטר מאותו שאתה לוקח בשמו אמרת],\u0006 וההוא יכתוב לך שטר מכירה בשמו, והודעת לעדים כדי שיצטרך אותו אדם לכתוב, על כן \u0003קא משמע לן דאמר ליה\u0004 \u0005[השמיע לנו\u0006 בברייתא \u0005שאומר לו]:\u0006 \u0003להכי טרחי ואמרי להו\u0004 \u0005[לפיכך טרחתי ואמרתי להם]\u0006 \u0003לעדים קמך\u0004 \u0005[לפניך],\u0006 \u0003דמינך\u0004 \u0005[שממך]\u0006 \u0003הוא דקא בעינא\u0004 \u0005[שאני רוצה\u0006 שטר נוסף\u0005].\u0006","מסופר: \u0003רב כהנא יהב זוזא אכיתנא\u0004 \u0005[נתן כסף עבור פשתן].\u0006 \u0003לסוף אייקר כיתנא\u0004 \u0005[לבסוף התייקר הפשתן]\u0006 \u0003זבניה מרוותיה דכיתנא\u0004 \u0005[\u0006ו\u0005מכר אותו בעל הפשתן]\u0006 במחיר יקר יותר, ורצה לתת את הכסף שקיבל מהקונים לרב כהנא. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב כהנא \u0005לפני]\u0006 \u0003רב\u0004 לשאול. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מה אעביד\u0004 \u0005[אעשה],\u0006 \u0003איזיל אישקיל זוזאי\u0004 \u0005[\u0006האם \u0005אלך\u0006 ו\u0005אקח\u0006 את \u0005כספי],\u0006 או שמא יש בכך משום ריבית? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי כי קא זבני אמרי\u0004 \u0005[אם\u0006 בזמן \u0005שמכרו\u0006 אותו \u0005אמרו]\u0006 \u0003\"האי כיתנא\u0004 \u0005[פשתן זה]\u0006 של \u0003כהנא הוא\"\u0004 — \u0003זיל שקול\u0004 \u0005[לך\u0006 ו\u0005קח]\u0006 את המעות כולן, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא תשקול\u0004 \u0005[תקח]\u0006 אלא את מה שנתת אתה.","ותוהים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר רב? האם \u0003כבני מערבא\u0004 \u0005[ארץ ישראל],\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003מי הודיעו לבעל חטין שיקנה חטין לבעל מעות?\u0004 כלומר, שאין שליח קונה עבור בעל הבית אלא לעצמו, אלא אם כן יודע המקנה למי הוא מקנה. ואם כן נמצא שהשליח זכה לעצמו במעות ונותנן לרב כהנא תמורת סכום קטן יותר ממה שקיבל ממנו.","אולם כאן \u0003אטו מי יהיב\u0004 \u0005[האם נתן]\u0006 \u0003רב כהנא ארבע\u0004 זוזים \u0003ושקיל תמני\u0004 \u0005[ולוקח שמונה]\u0006 ונוטל ריבית? \u0003כיתנא\u0004 \u0005[הפשתן]\u0006 שהוא של רב כהנא \u0003ממילא\u0004 (מעצמו) \u0003הוא דאייקר\u0004 \u0005[שהתייקר],\u0006 \u0003מיגזל גזלוה\u0004 \u0005[גזל אותה]\u0006 המוכר מרב כהנא, בזמן שמכר לאחר, \u0003ותנן\u0004 \u0005[ושנינו]:\u0006 \u0003כל הגזלנין משלמין כשעת הגזלה,\u0004 ולכן צריך להחזיר לו פשתן כשוויו בזמן הגזילה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003התם\u0004 \u0005[שם]\u0006 הסכם \u0003אמנה\u0004 בלבד \u0003הואי\u0004 \u0005[היה]\u0006 בין רב כהנא ומוכר הפשתן \u0003ולא משכיה\u0004 \u0005[משך אותו]\u0006 \u0003רב כהנא לכיתנא\u0004 \u0005[את הפשתן]\u0006 ולא קנה ממש את גוף הפשתן, ולכן אין בכך משום גזילה. \u0003ורב\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב: עושין\u0004 הסכם \u0003אמנה בפירות,\u0004 שנותן אדם כסף מראש על מנת שיקבל פירות לאחר זמן אפילו יהיו בשער יקר יותר, \u0003ו\u0004אולם \u0003אין עושין אמנה בדמים,\u0004 כלומר, אין לעשות הסכם כזה ולקבל כסף במקום פירות, משום שנראה הדבר כריבית.","\u0003הגוזל את חבירו\u0004 דבר ה\u0003שוה פרוטה\u0004 ותבעו הנגזל \u0003ונשבע לו\u0004 הגזלן לשקר שלא גזלו, ואחר כך רוצה הגזלן לעשות תשובה, ובמקרה כזה עליו להשיב לו מלבד הגזילה עצמה (קרן), גם חומש (חמישית) מערך הגזילה, \u0003יוליכנו אחריו\u0004 את הדבר הגזול ואת חומשו, אפילו \u0003ל\u0004ארץ \u0003מדי\u0004 הרחוקה. \u0003לא יתן\u0004 הגזלן את תשלומיו \u0003לא לבנו\u0004 של הנגזל \u0003ולא לשלוחו,\u0004 שאינו יוצא בכך ידי חובת השבה כדינה. \u0003אבל נותן\u0004 הוא \u0003לשליח בית דין. ואם מת\u0004 הנגזל — \u0003יחזיר ליורשיו.\u0004","\u0003נתן לו\u0004 הגזלן לנגזל \u0003את הקרן ולא נתן לו את החומש,\u0004 או \u0003מחל לו\u0004 הנגזל \u0003על הקרן ולא מחל לו על החומש,\u0004 או \u0003מחל לו על זה ועל זה חוץ מפחות\u0004 מ\u0003שוה פרוטה בקרן\u0004 שעל כך לא מחל — בכל אלה \u0003אינו צריך לילך אחריו.\u0004 אבל אם \u0003נתן לו את החומש ולא נתן לו את הקרן, מחל לו\u0004 הנגזל \u0003על החומש ולא מחל לו על הקרן, מחל לו על זה ועל זה חוץ משוה פרוטה בקרן\u0004 שעליו לא מחל — \u0003צריך לילך אחריו\u0004 ולהחזיר לו.","מי שהתחייב קרן וחומש ו\u0003נתן לו את הקרן\u0004 בשעתו \u0003ונשבע לו על החומש\u0004 שטען שכבר נתן לו, ואחר כך הודה שהיתה זו שבועת שקר —"],["\u0003הרי זה משלם חומש על חומש\u0004 על מה שכיחש בשבועה בחומש הזה, שהוא נעשה כגוף הגזילה, וכן הוא הדין אם חזר ונשבע על החומש הזה, \u0003עד שיתמעט הקרן\u0004 אותו דבר שהוא נשבע עליו שיהיה פחות \u0003משוה פרוטה.\u0004","\u0003וכן\u0004 הדין \u0003בפקדון, שנאמר: \"או בפקדון או בתשומת יד\u0004 (הלוואה) \u0003או בגזל או עשק את עמיתו. או מצא אבדה וכחש בה ונשבע על שקר\"\u0004 (ויקרא ה כא –כב), בכל אלה אם כיחש ונשבע לשקר \u0003הרי זה משלם קרן וחומש ו\u0004קרבן \u0003אשם\u0004 גזילות, כמפורש בתורה.","במשנה נאמר כי הגוזל את חבירו ונשבע לו — יוליכנו אחריו אפילו למדי, ומדייקים: \u0003נשבע לו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא נשבע לו\u0004 — \u0003לא,\u0004 אינו צריך לילך אחריו כדי להשיב לו את הגזילה וחומשה. ויש לשאול: \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]\u0006 משנה זו? \u0003לא\u0004 כ\u0003ר' טרפון ולא\u0004 כ\u0003ר' עקיבא! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מי ש\u0003גזל אחד מחמשה\u0004 בני אדם \u0003ואינו יודע איזה מהן\u0004 גזל, \u0003וכל אחד\u0004 מהם \u0003אומר \"אותי גזל\"\u0004 — \u0003מניח גזילה ביניהם ומסתלק,\u0004 והם יסתדרו ביניהם, אלו \u0003דברי ר' טרפון. ר' עקיבא אומר: לא זו דרך מוציאתו\u0004 בוודאות \u0003מידי עבירה, עד שישלם גזילה לכל אחד ואחד.\u0004","ומעתה נברר: משנתנו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' טרפון,\u0004 הרי לשיטתו \u0003אף על גב דאישתבע\u0004 \u0005[אף על פי שנשבע]\u0006 שלא גזל, ועתה מבקש הוא להשיב את הגזילה, בכל זאת \u0003אמר: מניח גזילה ביניהם ומסתלק\u0004 ואינו צריך להוליך את הגזילה לבעליה! \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' עקיבא,\u0004 הרי לשיטתו \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אישתבע\u0004 \u0005[נשבע],\u0006 \u0003אמר:\u0004 אינו יוצא מידי עבירה \u0003עד שישלם גזילה לכל אחד ואחד,\u0004 ונמצא שאין משנתנו המבדילה בין נשבע ללא נשבע כשיטת שניהם.","ומשיבים: \u0003לעולם\u0004 תאמר שמשנתנו כשיטת \u0003ר' עקיבא היא, וכי קאמר\u0004 \u0005[וכאשר אומר]\u0006 \u0003ר' עקיבא עד שישלם גזילה לכל אחד ואחד, היכא דאישתבע\u0004 \u0005[במקום שנשבע]\u0006 \u0003הוא דקאמר\u0004 \u0005[שאומר]\u0006 ולא כאשר לא נשבע, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין הנשבע לשקר על גזילה: \u0003\"לאשר הוא לו יתננו ביום אשמתו\"\u0004 (שם כד), להדגיש שעליו ליתן ליד הנגזל.","\u0003ור' טרפון\u0004 שאף בזמן שנשבע מתיר, במקרה של ספק, להניח גזילה ולהסתלק, מה הוא אומר? והרי דין תורה הוא! ומשיבים: \u0003אף על גב דאישתבע, עבוד רבנן תקנתא\u0004 \u0005[אף על פי שנשבע, עשו חכמים תקנה]\u0006 בענין זה להקל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר בר' צדוק אומר: תקנה גדולה התקינו, שאם היתה\u0004 ה\u0003הוצאה\u0004 להחזיר את הגזילה \u0003יתירה על הקרן\u0004 עצמה — \u0003משלם קרן וחומש לבית דין, ומביא\u0004 קרבן \u0003אשמו ומתכפר לו,\u0004 ובמקרה של ספק גם כן יש להקל בדומה לכך.","ושואלים: \u0003ור' עקיבא\u0004 מה אומר הוא על כך? מדוע לא יקל במקרה של ספק? ומשיבים: \u0003כי עבוד רבנן תקנתא\u0004 \u0005[כאשר עשו חכמים תקנה]\u0006 ליתנה לבית הדין — הרי זה \u0003היכא דידע למאן גזליה, דקא מהדר ליה ממונא למריה\u0004 \u0005[\u0006\u0005במקום שיודע ממי גזל, שהוא מחזיר\u0006 בסופו של דבר את \u0005הכסף לבעליו],\u0006 אבל במקרה ש\u0003גזל אחד מחמשה דלא ידע למאן גזליה, דלא הדר ממונא למריה\u0004 \u0005[שאינו יודע את מי גזל, שאין הכסף חוזר לבעליו]\u0006 — \u0003לא עבוד רבנן תקנתא\u0004 \u0005[עשו חכמים תקנה\u0006 זו\u0005].\u0006","על הנחה זו, שר' טרפון ור' עקיבא חולקים במקרה שגזל ונשבע, ומשנתנו כשיטת ר' עקיבא היא, \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בר יהודה\u0004 ממה ששנינו בברייתא אחרת, \u0003אמר ר' שמעון בן אלעזר: לא נחלקו ר' טרפון ור' עקיבא על שלקח\u0004 (קנה) חפץ מ\u0003אחד מחמשה\u0004 בני אדם \u0003ואינו יודע מאיזה מהן לקח, שמניח דמי מקח ביניהם ומסתלק,\u0004 שכיוון שלא עבר עבירה אין מחייבים אותו לשלם יותר ממה שנהנה, ואינו צריך לברר ממי קנה. \u0003על מה נחלקו?\u0004 על מי \u0003שגזל אחד מחמשה בני אדם ואינו יודע מאיזה מהן גזל, שר' טרפון אומר: מניח דמי גזילה ביניהם ומסתלק, ור' עקיבא אומר: אין לו תקנה עד שישלם גזילה לכל אחד ואחד.\u0004","\u0003ואי סלקא דעתך דאישתבע\u0004 \u0005[ואם עולה על דעתך\u0006 לומר שמדובר כאן במקרה \u0005שנשבע\u0006 לשקר\u0005],\u0006 ומשום כך סבור ר' עקיבא שעליו להשיב ליד הנגזל, \u0003מה לי לקח מה לי גזל!\u0004","\u0003ועוד מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003מעשה בחסיד אחד שלקח משני בני אדם ולא היה יודע מאיזה מהן לקח\u0004 וישלם לו, \u0003ובא לפני ר' טרפון, אמר לו: הנח דמי מקחך ביניהם והסתלק. בא לפני ר' עקיבא, אמר לו: אין לך תקנה עד שתשלם לכל אחד ואחד. ואי סלקא דעתך דמישתבע\u0004 \u0005[ואם עולה על דעתך\u0006 שנחלקו במקרה \u0005שנשבע\u0006 לשקר\u0005],\u0006 \u0003חסיד מי מישתבע בשיקרא\u0004 \u0005[האם\u0006 הוא \u0005נשבע לשקר]?\u0006","\u0003וכי תימא, דמישתבע והדר הוי\u0004 \u0005[ואם תאמר\u0006 שמדובר כאן באדם \u0005שנשבע וחזר\u0006 אחר כך ו\u0005נהיה]\u0006 \u0003חסיד.\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כל היכא דאמרינן\u0004 \u0005[מקום שאנו אומרים]\u0006 \u0003\"מעשה בחסיד אחד\",\u0004 הרי זה \u0003או ר' יהודה בן בבא או ר' יהודה בר' אילעאי, ור' יהודה בן בבא ור' יהודה בר' אילעאי\u0004 הלא \u0003חסידים דמעיקרא הוו\u0004 \u0005[מתחילה היו],\u0006 שלא היה זמן שלא היו מדקדקים במצוות!","\u0003אלא לעולם\u0004 נחלקו ר' טרפון ור' עקיבא במקרה של גזילה בלא שבועת שקר, ואף במקרה זה סבור ר' עקיבא שצריך להשיב ליד הנגזל. \u0003ו\u0004משנתנו, ממנה משמע שרק במקרה שנשבע הדין כן — כשיטת \u0003ר' טרפון היא, ו\u0004צריך לומר ש\u0003מודה ר' טרפון היכא דאישתבע\u0004 \u0005[במקום שנשבע]\u0006 שאז צריך להחזיר לאותו אדם עצמו, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בגוזל ונשבע על כך לשקר: \u0003\"לאשר הוא לו יתננו ביום אשמתו\".\u0004 \u0003ור' עקיבא דאמר\u0004 \u0005[שאומר]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא מישתבע\u0004 \u0005[נשבע]\u0006 עליו להשיב ליד הנגזל, למרות שבכתוב מדובר דווקא על נשבע לשקר — הרי זה משום שהוא \u0003קניס\u0004 \u0005[קונס]\u0006 את העבריין.","ושואלים: \u0003ו\u0004לדעת \u0003ר' טרפון, מכדי היכא דמישתבע\u0004 \u0005[הואיל ובמקום שנשבע]\u0006 \u0003לא סגיא\u0004 \u0005[די\u0006 לו\u0005]\u0006 שאינו מתכפר במקרה ש\u0003לא הודה,\u0004 ואם כן ברור שהוא מחזיר מחמת תשובה והודאה, ואם כן \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 למה דווקא\u0005]\u0006 נאמר במשנתנו \u0003\"ונשבע\"? אפילו בלא שבועה נמי\u0004 \u0005[גם כן]\u0006 יהא חייב להחזיר לשם כפרתו! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מודה ר' טרפון, באומר לשנים \"גזלתי\u0004 מ\u0003אחד מכם מנה ואיני יודע\u0004 מ\u0003איזה מכם\"\u0004 — \u0003נותן לזה מנה ולזה מנה,\u0004"],["לפי \u0003שכבר הודה מפי עצמו!\u0004 משמע שאף ר' טרפון מודה שהבא לצאת ידי שמים צריך לתת לבעלים דווקא, ומדוע לא יהא הדין כן במשנתנו?","\u0003אלא אמר רבא: שאני מתניתין\u0004 \u0005[שונה\u0006 הדין ב\u0005משנתנו],\u0006 ש\u0003כיון דידע למאן גזליה ואודי ליה\u0004 \u0005[ש\u0006הוא \u0005יודע למי גזל והודה לו],\u0006 \u0003כיון\u0004 ש\u0003אפשר לאהדורי ממונא למריה\u0004 \u0005[להחזיר\u0006 את \u0005הממון לבעליו]\u0006 \u0003הוה ליה כמאן דאמר ליה\u0004 \u0005[הריהו\u0006 נחשב \u0005כמי שאומר לו]\u0006 הנגזל לגזלן \u0003\"יהיו לי בידך\"\u0004 כפקדון, \u0003הלכך\u0004 (על כן): אם \u0003נשבע, אף על גב דקאמר ליה\u0004 \u0005[אף על פי שאומר לו]\u0006 \u0003\"יהיו לי בידך\", כיון דבעי\u0004 \u0005[ש\u0006הוא \u0005צריך]\u0006 \u0003כפרה, לא סגי\u0004 \u0005[די]\u0006 לו \u0003עד דמטי לידיה\u0004 \u0005[שיבואו לידו\u0006 ממש\u0005].\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003לא אישתבע\u0004 \u0005[נשבע],\u0006 \u0003הוי גביה\u0004 \u0005[הריהו\u0006 הגזילה \u0005אצלו]\u0006 \u0003פקדון עד דאתי ושקיל ליה\u0004 \u0005[שיבוא ויקח אותו].\u0006","שנינו במשנה: \u0003לא יתן\u0004 הגזלן את תשלומיו \u0003לא לבנו\u0004 של הגזלן \u0003ולא לשלוחו,\u0004 שאינו יוצא בכך ידי חובת השבה כדינה. ובענין זה מביאים, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בהלכה זו של שליחות: \u0003שליח שעשאו\u0004 (מינה אותו) המשלח \u0003בעדים\u0004 לקבל עבורו דבר השייך לו, או מלווה שיש לו בידי חבירו — \u0003רב חסדא אמר: הוי\u0004 \u0005[הריהו]\u0006 \u0003שליח\u0004 גם לענין זה, שאם אירע אונס בדרך לחפץ או לכסף שקיבל השליח מאותו אדם — פטור מי שמסר בידיו את החפץ או הכסף, משום שמסירתו לשליח היא כמסירתו לבעלים. \u0003רבה אמר: לא הוי\u0004 \u0005[אינו]\u0006 \u0003שליח,\u0004 והרי זה באחריות חבירו.","ומסבירים: \u0003רב חסדא אמר הוי\u0004 \u0005[הריהו]\u0006 \u0003שליח,\u0004 שכן טוען חבירו: \u0003להכי טרחי ואוקמיה\u0004 \u0005[משום כך טרחתי\u0006 המשלח \u0005והעמדתיו,\u0006 מיניתי אותו\u0005],\u0006 את השליח \u0003בעדים\u0004 — כדי \u0003דליקו ברשותיה\u0004 \u0005[שיעמוד\u0006 הדבר \u0005ברשותו]\u0006 שכשיימסר הכסף לידיו יהיה זה כאילו נמסר לידי. ואילו \u0003רבה אמר: לא הוי\u0004 \u0005[אינו]\u0006 \u0003שליח,\u0004 שכן \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 לזאת היתה כוונתו בכך שמינהו שליח בעדים, לומר לו לחבירו: \u0003איניש מהימנא\u0004 \u0005[אדם מהימן]\u0006 \u0003הוא, אי סמכת\u0004 \u0005[אם אתה סומך]\u0006 לשלוח בידו את החפץ או הכסף שבידך \u0003סמוך, אי בעית לשדוריה בידיה\u0004 \u0005[אם אתה רוצה לשלוח בידו]\u0006 — \u0003שדר בידיה\u0004 \u0005[שלח בידו].\u0006","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003השואל את הפרה, ושילחה\u0004 המשאיל לשואל \u0003ביד בנו\u0004 או \u0003ביד עבדו\u0004 או \u0003ביד שלוחו\u0004 של המשאיל, \u0003או ביד בנו ביד עבדו ביד שלוחו של שואל, ומתה\u0004 — \u0003פטור,\u0004 משום שלא הגיעה עדיין הבהמה לרשות שואל שיתחייב באונסיה.","ונברר: \u0003האי שלוחו היכי דמי\u0004 \u0005[שלוחו זה\u0006 של השואל \u0005כיצד הוא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא עשה\u0004 (מינה) אותו \u0003בעדים,\u0004 אם כן \u0003מנא ידעינן\u0004 \u0005[מנין אנו יודעים]\u0006 בכלל שהוא שלוחו? \u0003אלא\u0004 צריך אתה לומר ש\u0003עשה\u0004 אותו שליח \u0003בעדים, וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003פטור,\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לרב חסדא\u0004 שהוא סבור ששלוחו הוא!","ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב חסדא\u0004 להלן בהסבר משנה אחרת, שמדובר שם \u0003בשכירו ולקיטו,\u0004 כלומר, באדם שהוא שכיר אצלו או שנמצא אצלו ומלקט אצלו תבואה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יאמר רב חסדא שמדובר \u0003בשכירו ולקיטו\u0004 ויודעים הכל שהוא שלוחו, אפילו לא עשאו שליח בעדים.","ומביאים ראיה נוספת, \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו: \u0003לא יתן\u0004 הגזלן את הגזילה \u0003לא לבנו ולא לשלוחו\u0004 של הנגזל. ונברר: \u0003האי שלוחו היכי דמי\u0004 \u0005[שלוחו זה\u0006 ששנינו \u0005כיצד הוא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא עשאו בעדים, מנא ידעינן\u0004 \u0005[מנין אנו יודעים]\u0006 בכלל שהוא שלוחו? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן ש\u0003עשאו בעדים?\u0004 ומכאן שאין הוא נחשב כשליחו ממש וקשה לרב חסדא. \u0003תרגמא\u0004 \u0005[תרגם,\u0006 הסביר\u0005]\u0006 את זאת \u0003רב חסדא:\u0004 כאן מדובר \u0003בשכירו ולקיטו\u0004 ולא בשליח שמונה בעדים.","ומקשים: \u0003אבל שליח שעשאו בעדים, מאי\u0004 \u0005[מה]\u0006 יהא הדין? — \u0003הכי נמי דהוי\u0004 \u0005[כך גם כן שהריהו\u0006 נחשב\u0005]\u0006 \u0003שליח?\u0004 אם כן \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה,\u0006 ב\u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003אבל נותן הוא לשליח בית דין, לפלוג וליתני בדידיה\u0004 \u0005[שיחלק וישנה בה\u0006 בהלכה זו \u0005עצמה]\u0006 ש\u0003שליח שעשאו בעדים הכי נמי דהוי\u0004 \u0005[כך\u0006 הוא \u0005גם כן שהריהו]\u0006 נחשב \u0003שליח!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003לא פסיקא ליה\u0004 \u0005[פסוק\u0006 חתוך \u0005לו\u0006 הדבר\u0005]\u0006 כדי שיוכל לומר אותו בצורה כוללת כזו, כי \u0003שליח בית דין\u0004 שנאמרה בו הלכה זו, \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003עשאו נגזל ולא שנא\u0004 \u0005[שונה]\u0006 אם \u0003עשאו גזלן\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003שליח\u0004 ולכן \u0003פסיקא ליה\u0004 \u0005[פסוק,\u0006 חתוך \u0005אצלו\u0006 הדבר\u0005]\u0006 ויכול להשתמש בלשון כזו. ואילו \u0003שליח שעשאו בעדים,\u0004 שיש לגביו אופנים שונים, \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003עשאו נגזל הוא דהוי\u0004 \u0005[שנעשה]\u0006 \u0003שליח,\u0004 אבל אם \u0003עשאו גזלן לא הוי\u0004 \u0005[אינו]\u0006 \u0003שליח\u0004 — \u0003לא פסיקא ליה\u0004 \u0005[אינו פסוק,\u0006 חתוך \u0005אצלו\u0006 הדבר\u0005].\u0006","ומעירים: \u0003ולאפוקי מהאי תנא\u0004 \u0005[ו\u0006פירוש זה בדברי המשנה יש בו כדי \u0005להוציא מדברי תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון בן אלעזר אומר: שליח בית דין שעשאו נגזל ולא עשאו גזלן, או עשאו גזלן ושלח הלה\u0004 (הנגזל) שליח \u0003ונטל את שלו מידו\u0004 — \u0003פטור.\u0004 אבל שליח בית דין שעשאו גזלן ולא הגיע החפץ לנגזל — חייב. ובהמשך למחלוקת רב חסדא ורבה, אמוראי בבל, מביאים מה שאמרו על כך חכמי ארץ ישראל.","\u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 \u0003שליח שעשאו בעדים הוי\u0004 \u0005[הריהו]\u0006 \u0003שליח\u0004 לכל דבר, \u0003ואם תאמר: משנתנו\u0004 ממנה דייקנו שלא יתן לשליחו!","הכוונה היא \u0003בממציא לו שליח,\u0004 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הנגזל לאדם: \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי זוזי גבי פלניא\u0004 \u0005[מעות אצל פלוני]\u0006 שהוא חייב לי \u0003ולא קא משדר להו\u0004 \u0005[ואינו שולח אותם\u0006 לי\u0005],\u0006 \u0003איתחזי ליה\u0004 \u0005[הראה לו],\u0006 כלומר, המצא עצמך לפניו, \u0003דלמא איניש\u0004 \u0005[שמא אדם]\u0006 \u0003הוא\u0004 ש\u0003לא משכח לשדורי ליה\u0004 \u0005[מצא לשלוח אותו].\u0006","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003כ\u0004דברי \u0003רב חסדא\u0004 שמדובר \u0003בשכירו ולקיטו\u0004 ולא בשליח ממש. אבל אם עשאו הנגזל שליח בעדים — רשאי הגזלן לתיתו בידו ונפטר מאחריותו.","\u0003אמר רב יהודה אמר שמואל:\u0004"],["\u0003אין משלחין מעות\u0004 לבעליהן \u0003בדיוקני\u0004 (צורה), כלומר, על סמך סימן שמסר הבעלים לשליח להוכיח למחזיק במעות שאכן שלחו לקבל את המעות. \u0003ואפילו עדים חתומים עליה\u0004 לאשר שזה הוא סימנו. \u0003ור' יוחנן אמר: אם עדים חתומים עליה\u0004 — \u0003משלחין.\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ל\u0004פי דעת \u0003שמואל מאי תקנתא\u0004 \u0005[מה התקנה],\u0006 כיצד יכול אדם לגבות כספים מחבירו בלא שיצטרך לבוא בעצמו? — \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה],\u0006 ש\u0003ר' אבא הוי מסיק זוזי\u0004 \u0005[היה נושה כספים]\u0006 \u0003ברב יוסף בר חמא,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא \u0003לרב ספרא: בהדי דאתית אייתינהו ניהלי\u0004 \u0005[כאשר אתה בא\u0006 לשם, למקומו של רב יוסף בר חמא, \u0005הבא אותם לי].\u0006 \u0003כי אזל להתם\u0004 \u0005[כאשר הלך לשם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של רב יוסף בר חמא לרב ספרא: \u0003מי\u0004 \u0005[האם]\u0006 \u0003כתב לך\u0004 ר' אבא \u0003\"התקבלתי\",\u0004 כתב המאשר שכאשר יקבל רב ספרא את הכסף לידו הרי זה כאילו הוא עצמו קיבל את המעות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא\u0004 כתב לי. אמר לו: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003זיל ברישא\u0004 \u0005[לך בתחילה]\u0006 \u0003ויכתוב לך \"התקבלתי\",\u0004 כדי שנדע שבנתינה זו פטור אבי מן התשלום ורק אחרי כן ישלם לך אבי את חובו.","\u0003לסוף\u0004 (אחר כך) \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אי כתב לך נמי\u0004 \u0005[גם אילו היה כותב לך]\u0006 \u0003\"התקבלתי\" לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא, דלמא אדאתית\u0004 \u0005[שמא עד שאתה בא]\u0006 בדרכך חזרה אלינו \u0003שכיב\u0004 \u0005[ימות]\u0006 \u0003ר' אבא, ונפלו זוזי קמי יתמי\u0004 \u0005[ויפלו המעות לפני היתומים],\u0006 \u0003ו\"התקבלתי\"\u0004 של \u0003ר' אבא לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא,\u0004 שהרי בזמן שתקבל את הכסף עבורו הכסף אינו שלו אלא של היתומים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואלא מאי תקנתא\u0004 \u0005[מהי התקנה]?\u0006 אמר לו: \u0003זיל נקנינהו\u0004 \u0005[לך,\u0006 ו\u0005יקנה אותם]\u0006 ר' אבא \u0003לך\u0004 את הכספים \u0003אגב ארעא\u0004 \u0005[הקרקע],\u0006 שיהיו כספים אלה כמתנה לך, \u0003ותא את\u0004 \u0005[ובוא אתה]\u0006 ו\u0003כתוב לן\u0004 \u0005[לנו]\u0006 בשמך \u0003\"התקבלתי\u0004 את המעות\u0003\".\u0004","ומעירים: ועצה זו היא \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 שאירע בדור מאוחר יותר, ש\u0003רב פפא הוה מסיק תריסר אלפי זוזי\u0004 \u0005[היה נושה שנים עשר אלף זוז]\u0006 באיש שהיה גר ב\u0003בי חוזאי, אקנינהו ניהליה\u0004 \u0005[הקנה אותם\u0006 רב פפא \u0005לו]\u0006 \u0003לרב שמואל בר אבא,\u0004 שהלך לשם, \u0003אגב אסיפא דביתיה\u0004 \u0005[מפתן ביתו].\u0006 ומסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 רב שמואל בר אבא עם הכסף, \u0003נפק לאפיה\u0004 \u0005[יצא\u0006 רב פפא \u0005ל\u0006הקביל \u0005פניו]\u0006 \u0003עד\u0004 למקום \u0003תואך\u0004 מרוב שמחה שהכסף אכן הגיע לידו.","שנינו במשנה: \u0003נתן לו את הקרן\u0004 ולא נתן לו את החומש, אינו צריך לילך אחריו. מכאן מדייקים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 שחיוב \u0003חומש ממונא\u0004 \u0005[ממון]\u0006 \u0003הוא,\u0004 ודינו כשאר חוב של ממון, \u0003ו\u0004לכן \u0003אם מיית\u0004 \u0005[מת]\u0006 הגזלן — \u0003משלמי ליה\u0004 \u0005[משלמים לו\u0006 לנגזל\u0005]\u0006 ה\u0003יורשין.\u0004","\u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 בהמשך המשנה: \u0003נתן את הקרן ונשבע\u0004 לשקר \u0003על החומש\u0004 — \u0003הרי\u0004 זה \u0003מוסיף חומש על חומש, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חומשא ממונא\u0004 \u0005[החומש ממון]\u0006 \u0003הוא\u0004 כשאר חוב ממונות.","\u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הגוזל את חבירו, ונשבע לו\u0004 לשקר על כך, \u0003ומת\u0004 — \u0003יורשין\u0004 של הגזלן \u0003משלמים קרן וחומש\u0004 לנגזל, \u0003ו\u0004אולם \u0003פטורין מן האשם,\u0004 שהרי לא הם חטאו ואינם יכולים להביא קרבן. ומכל מקום חומש עליהם לשלם, ואם כן דין ממון יש לו.","ויש לשאול: \u0003ו\u0004כי \u0003יורשין בני\u0004 חובת \u0003שלומי חומשא דאבוהון הוו\u0004 \u0005[תשלום חומש של אביהם הם],\u0006 \u0003אלמא חומש ממונא\u0004 \u0005[מכאן\u0006 ש\u0005החומש ממון]\u0006 \u0003הוא ובעי שלומי\u0004 \u0005[וצריכים לשלם]\u0006 ה\u0003יורשין,\u0004 מכל אלה רואים אנו שחומש הוא ממון. \u0003ורמינהו\u0004 \u0005[ומשליכים\u0006 מראים סתירה על כך\u0005]\u0006 ממדרש הלכה בתורת כהנים, שבתחילה נאמר בו שאין אדם צריך להוסיף חומש אלא על גזל שלו, ולא של אביו. וממשיך, \u0003עדיין אני אומר: אימתי אינו משלם חומש על גזל אביו\u0004 — \u0003בזמן שלא נשבע לא הוא ולא אביו\u0004 שממון הנגזל אינו בידיו, אבל אם נשבע","\u0003הוא ולא אביו,\u0004 או \u0003אביו ולא הוא,\u0004 או \u0003הוא ואביו מנין\u0004 שגם כן דינו של הבן שפטור מן החומש? \u0003תלמוד לומר:\u0004 \u0003\"\u0004והשיב את הגזילה \u0003אשר גזל\u0004 או את העושק \u0003אשר עשק\"\u0004 (ויקרא ה, כג), \u0003והוא\u0004 הבן \u0003לא גזל ולא עשק.\u0004 ואם כן הבן לעולם פטור מן החומש ואין החומש כשאר חיוב ממון שחייב בו הבן!","\u0003אמר רב נחמן, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן שהודה\u0004 האב לאחר שנשבע, ונתחייב בתשלום קרן וחומש, \u0003כאן שלא הודה.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא הודה\u0004 האב, \u0003קרן נמי\u0004 \u0005[גם כן]\u0006 \u0003לא משלם\u0004 הבן! \u0003וכי תימא הכי נמי\u0004 \u0005[וכי תאמר כך גם כן]\u0006 ש\u0003לא משלם\u0004 גם קרן וזו כוונת מדרש ההלכה שבתורת כהנים, \u0003והא מדקא מהדר אחומש, למימרא\u0004 \u0005[והרי מתוך, שמחזר\u0006 לפרט מתי פטור מתשלום \u0005על החומש\u0006, הרי זה בא \u0005לומר]\u0006 ש\u0003קרן משלם\u0004 בכל מקרה!","\u0003ועוד תניא\u0004 \u0005[שנויה\u0006 בהמשך אותה ברייתא\u0005],\u0006 \u0003ועדיין אני אומר: אימתי הוא משלם קרן על גזל\u0004 שגזל \u0003אביו\u0004 — \u0003בזמן שנשבע הוא ואביו.\u0004 ואולם אם נשבע \u0003אביו ולא הוא, הוא ולא אביו, לא הוא ולא אביו מנין\u0004 שהוא משלם את הקרן? — \u0003תלמוד לומר: \"גזילה ועושק אבידה ופקדון יש תלמוד\".\u0004","ומסופר: \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב הונא וקאמר להא שמעתא\u0004 \u0005[ואמר את השמועה הזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בריה\u0004 \u0005[בנו]\u0006 של רב הונא: \u0003\"יש תלמוד\" קאמר מר\u0004 \u0005[אמר אדוני],\u0006 \u0003או \"ישתלמו\" קאמר מר\u0004 \u0005[אמר אדוני]?\u0006 שלא שמע היטב את הדברים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"יש תלמוד\" קאמינא\u0004 \u0005[אומר אני],\u0006 \u0003ומריבויא דקראי אמרי\u0004 \u0005[ומריבוי הכתובים אני אומר\u0006 זאת\u0005],\u0006 ואם כן מברייתא זו עולה בבירור כי הבן חייב לשלם קרן בכל מקרה!","\u0003אלא מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לא הודה\"\u0004 בברייתא שחייבה בקרן ופטרה את הבן מחומש? — \u0003לא הודה אביו, והודה בנו\u0004 לאחר שנשבע שהגזילה אכן בידו.","ושואלים: \u0003ונחייב\u0004 \u0005[ושיתחייב]\u0006 \u0003בנו חומש\u0004 על ה\u0003שבועה דידיה\u0004 \u0005[שלו]\u0006 שנשבע בשקר! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: מדובר שם \u0003בשאין\u0004 ה\u0003גזילה קיימת.\u0004 ואף שהיתה זו שבועת שקר, אינה שבועה של כפירת ממון שחייבים לשלם חומש. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003ב\u0004אופן \u0003שאין גזילה קיימת, אפילו קרן נמי\u0004 \u0005[גם כן]\u0006 \u0003לא משלם,\u0004 שאין הבנים חייבים לשלם מה שגזל אביהם ואינו קיים עוד! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003אחריות\u0004 נכסים על כך, כלומר, שהוריש לבניו קרקעות, וקרקעות הם אחריות וערבות לפרעון כל חובותיו, ובמקרה כזה חייבים בניו להשיב את הקרן מן הנכסים שירשו.","ושואלים: \u0003וכי איכא \u0004\u0005[וכאשר יש]\u0006 \u0003אחריות נכסים מאי הוי\u0004 \u0005[מה יהיה,\u0006 מה בכך\u0005]?\u0006 הרי בסופו של דבר גזילה זו \u0003מלוה על פה היא,\u0004 שהרי אין שטר התחייבות של הגזלן, \u0003ומלוה על פה אינו גובה לא מן היורשין ולא מן הלקוחות!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה:"],["מדובר \u0003בשעמד\u0004 האב ונתחייב \u0003בדין\u0004 לפני מותו, והרי זה באותה שעה כמלווה בשטר, שגובים מנכסי היתומים. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בשעמד בדין, אפילו חומש נמי\u0004 \u0005[גם כן]\u0006 \u0003משלם,\u0004 שהרי נעשה זה חוב גמור, ונשבע עליו הבן, והודה! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: לפי שאין משלמין חומש על כפירת שעבוד קרקעות,\u0004 וכיון שמדובר כאן בקרקע — לא נשבעים בכלל על הקרקע, וכפירה בענין זה אינה מחייבת את החומש.","\u0003רבא אמר: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — שהיתה פה הגזילה קיימת באופן מסויים, ו\u0003כגון שהיתה דיסקייא\u0004 (התיק) \u0003של אביו\u0004 שהיו בו כספיו, ובכלל זה כסף הגזילה \u0003מופקדת ביד אחרים, קרן משלם דהא איתיה\u0004 \u0005[שהרי\u0006 הדבר הנגזל \u0005ישנו],\u0006 ואולם \u0003חומש לא משלם,\u0004 משום \u0003דכי אישתבע בקושטא אישתבע\u0004 \u0005[שכאשר נשבע,\u0006 שאין בידו, \u0005באמת נשבע],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003לא הוה ידע\u0004 \u0005[היה יודע]\u0006 שהגזילה נמצאת ברשות אביו.","שנינו במשנה שאם החזיר הגזלן את הקרן ואת החומש \u0003חוץ מפחות שוה פרוטה בקרן\u0004 שוב אינו צריך ללכת אחר הנגזל. \u0003אמר רב פפא: לא שנו אלא שאין גזילה\u0004 עצמה \u0003קיימת, אבל\u0004 אם ה\u0003גזילה קיימת\u0004 — \u0003צריך לילך אחריו\u0004 בכל מקרה ולהשיב לו אותה, ומדוע? — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תייקר\u0004 (תתייקר, יעלה מחירה) ותהא שוב שווה פרוטה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 לשון אחרת, \u0003אמר רב פפא: לא שנא\u0004 \u0005[שונה]\u0006 באופן שה\u0003גזילה קיימת, ולא שנא\u0004 \u0005[שונה]\u0006 באופן \u0003שאין\u0004 ה\u0003גזילה קיימת\u0004 — אם אין הגזילה שבידו שווה פרוטה \u0003אינו צריך לילך אחריו,\u0004 ואילו \u0003ל\u0004חשש \u0003שמא תייקר לא חיישינן\u0004 \u0005[חוששים אנו],\u0006 אלא הכל לפי המצב כמו שהוא כעת.","\u0003אמר רבא: גזל שלש אגודות\u0004 (צרורות) של ירק למשל, שהיו שוות כולן בשעת הגזילה \u0003שלש פרוטות, והוזלו\u0004 האגודות הללו \u0003ועמדו על שתים\u0004 (שתי פרוטות), \u0003אם החזיר לו שתים\u0004 מן האגודות — \u0003חייב להחזיר לו\u0004 גם את האגודה ה\u0003אחרת,\u0004 אף על פי שאגודה זו אינה שווה כעת פרוטה. \u0003ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה התנא שלנו\u0006 במשנה שבפרקנו\u0005]:\u0006 \u0003גזל חמץ ועבר עליו הפסח\u0004 — \u0003אומר לו\u0004 הגזלן לבעל החמץ \u0003\"הרי שלך לפניך\".\u0004","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא \u0003דאיתיה בעיניה\u0004 \u0005[ש\u0006החמץ \u0005ישנו בעינו]\u0006 ויכול הגזלן לומר לבעל החמץ \"הרי שלך לפניך\", \u0003הא ליתיה בעיניה\u0004 \u0005[הרי\u0006 אם \u0005אינו בעינו\u0006 כעת\u0005],\u0006 \u0003אף על גב דהשתא לאו ממונא\u0004 \u0005[אף על פי שעתה\u0006 החמץ הזה \u0005אינו\u0006 שווה \u0005ממון]\u0006 שהרי נאסר בהנאה, \u0003כיון דמעיקרא ממונא\u0004 \u0005[שמתחילה ממון]\u0006 \u0003הוא\u0004 — \u0003בעי שלומי\u0004 \u0005[צריך לשלם],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003אף על גב דהשתא\u0004 \u0005[אף על פי שעתה]\u0006 האגודה השלישית \u0003לא שוה פרוטה,\u0004 \u0003כיון דמעיקרא הוי\u0004 \u0005[שבתחילה היתה]\u0006 \u0003שוה פרוטה\u0004 — \u0003בעי שלומי\u0004 \u0005[צריך לשלם].\u0006","אולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 בהמשך לכך: אם \u0003גזל שתי אגודות ב\u0004שווי \u0003פרוטה\u0004 יחד, \u0003והחזיר לו אחת מהן, מהו\u0004 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003השתא ליכא\u0004 \u0005[עתה אין\u0006 כבר\u0005]\u0006 \u0003גזילה,\u0004 שהרי מה שנשאר בידו הוא בודאי פחות משוה פרוטה ופטור הוא מהשבה. \u0003או דלמא הא\u0004 \u0005[שמא הרי]\u0006 \u0003לא הדר\u0004 \u0005[החזיר]\u0006 את כל ה\u0003גזילה דהואי גביה\u0004 \u0005[שהיתה אצלו]?\u0006","\u0003הדר פשטה\u0004 \u0005[חזר\u0006 רבא עצמו ו\u0005פתר אותה\u0006 את שאלתו\u0005]:\u0006 \u0003גזילה אין כאן,\u0004 שהרי אין פה שוה פרוטה, אבל \u0003השבה אין כאן.\u0004 ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003גזילה אין כאן\u0004 בידו, אם כך \u0003השבה\u0004 שהשיב מקודם \u0003יש כאן!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דברי רבא: \u0003אף על פי שגזילה אין כאן,\u0004 מכל מקום \u0003מצות השבה אין כאן,\u0004 שהרי לא החזיר את כל מה שגזל.","\u0003ו\u0004מביאים ענין דומה ש\u0003אמר רבא, הרי אמרו\u0004 הלכה במשנה: \u0003נזיר שגילח\u0004 את ראשו כדין \u0003ו\u0004אולם \u0003שייר שתי שערות\u0004 — \u0003לא עשה ולא כלום,\u0004 כאילו לא גילח. על כך \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם \u0003גילח\u0004 שערה \u0003אחת\u0004 מאותן שתים \u0003ונשרה אחת, מהו?\u0004 האם יצא ידי גילוח? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא\u0004 בתמיהה: וכי שאלה של \u0003נזיר שגילח\u0004 שערותיו \u0003אחת אחת קא מבעיא ליה\u0004 \u0005[נשאלה לו]\u0006 \u0003לרבא?\u0004 שהרי במקרה שלפנינו את השערה מהשתיים שנשארו הוא גילח כדין, והרי רשאי נזיר לגלח אפילו שערה שערה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן מסויים ו\u0003כגון שנשר אחת מהן\u0004 תחילה \u0003וגילח אחת\u0004 הנשארת בלבד, וכך שאל רבא: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003השתא מיהת הא ליכא\u0004 \u0005[עכשיו על כל פנים הרי אין פה]\u0006 \u0003שיעור\u0004 שמעכב את מצות הגילוח, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003הא לאו\u0004 \u0005[זה לא]\u0006 \u0003גילוח הוא,\u0004 \u0003דמעיקרא הא\u0004 \u0005[שמתחילה הרי]\u0006 \u0003שייר שתי שערות\u0004 ויש עליו חובת גילוח, \u0003והשתא כי גילח\u0004 \u0005[ועכשיו כאשר\u0006 הוא \u0005מגלח]\u0006 \u0003לא הוי\u0004 \u0005[היו]\u0006 \u0003שתי שערות,\u0004 ואין כאן שם גילוח?","ואף שאלה זו \u0003הדר פשטה\u0004 \u0005[חזר\u0006 ו\u0005תירץ אותה]\u0006 רבא עצמו ובאותה צורת לשון: \u0003שער אין כאן, גילוח אין כאן.\u0004 ואף כאן תוהים באותו אופן: \u0003אי\u0004 \u0005[אם]\u0006 \u0003שער אין כאן, גילוח יש כאן!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דברי רבא: \u0003אף על פי ששער\u0004 שתי שערות שמעכבות \u0003אין כאן,\u0004 מכל מקום \u0003מצות גילוח אין כאן\u0004 שלא קיים את המצוה.","\u0003ו\u0004מביאים שאלה דומה: \u0003אמר רבא, הרי אמרו\u0004 הלכה במשנה: \u0003חבית שניקבה\u0004 שמכיון שיש בה חור, אינה מהווה יותר חציצה בפני הטומאה מלטמא מה שבתוך החבית, \u0003ו\u0004אולם \u0003סתמוה שמרים\u0004 שהיו בה — \u0003הצילוה,\u0004 והיא נחשבת כסתומה. על כך \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: אגף חציה,\u0004 כלומר, סגר את חצי הנקב \u0003מהו\u0004 הדין? וצדדי השאלה: האם נאמר שעכשיו אין כאן שיעור נקב והרי החבית כסתומה, או שנשארת בגדר נקובה למרות הסתימה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי: לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משנתנו היא זו?\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 באותה משנה\u0005]:\u0006 \u0003חבית שניקבה וסתמוה שמרים\u0004 — \u0003הצילוה\u0004 מלהיטמא, אם \u0003פקקה בזמורה\u0004 (ענף) — אינה נחשבת כסתומה \u0003עד שימרח\u0004 טיט סביב הזמורה, כדי לסתום יפה את הנקב. \u0003היו בה שתים\u0004 (שתי זמורות) לסתום — אינה נחשבת כסתומה \u0003עד שימרח מן הצדדים\u0004 מצידי הזמורות \u0003ובין זמורה לחבירתה.\u0004","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא במקרה ש\u0003מרח, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא מרח\u0004 — \u0003לא,\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 צריך למרוח? \u0003ותיהוי כי\u0004 \u0005[ותהא\u0006 זו \u0005כמו]\u0006 \u0003אגף חציה,\u0004 שהרי מכל מקום סתם חלק מן הנקב, ומכאן פתרון לשאלת רבא שאין זו סתימה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית ההוכחה: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם אי\u0004 \u0005[שם אם]\u0006 \u0003לא מרח\u0004 את שתי הזמורות משני צידיהן הרי \u0003לא קאי\u0004 \u0005[אין\u0006 הסתימה \u0005עומדת\u0006 כלל\u0005]\u0006 והרי זה כאילו לא נסתמה כלל, אבל \u0003אגף חציה\u0004 — \u0003במידי דקאי קאי\u0004 \u0005[בדבר ש\u0006הוא \u0005עומד עומד].\u0006 ושאלה זו נשארה ללא פתרון.","\u0003ו\u0004מביאים עוד ענין ש\u0003אמר רבא, הרי אמרו\u0004 הלכה במשנה: אם \u0003גזל חמץ ועבר עליו הפסח\u0004 — מחזיר לו את החמץ שנגזל כמו שהוא ו\u0003אומר לו \"הרי שלך לפניך\".\u0004 ובהמשך לכך \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004"],["אם לאחר שכבר נאסר החמץ \u0003נשבע עליו\u0004 בשקר שלא גזלו, \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דאי מיגנב בעי שלומי ליה\u0004 \u0005[שאם ייגנב ממנו\u0006 החמץ הזה עצמו \u0005צריך לשלם לו],\u0006 שהרי אינו יכול לומר לו \"הרי שלך לפניך\" אלא כשהחמץ נמצא בעינו, ואם אינו קיים — משלם כשעת הגזילה כל מחירו, אם כן נמצא ש\u0003ממונא קא כפר ליה\u0004 \u0005[ממון הוא\u0006 ש\u0005כופר לו]\u0006 וחייב עליו חומש ואשם. \u0003או דלמא השתא מיהת הא מנח\u0004 \u0005[שמא עכשיו\u0006 בשעת השבועה \u0005הרי מונח\u0006 הוא\u0005]\u0006 \u0003ועפרא בעלמא\u0004 \u0005[ועפר בלבד]\u0006 \u0003הוא, ו\u0004נמצא ש\u0003לא כפר ליה ממונא\u0004 \u0005[לו ממון]?\u0006","ומעירים: \u0003מילתא דאיבעיא ליה\u0004 \u0005[דבר שהיה מסופק לו]\u0006 \u0003לרבא, פשיטא ליה\u0004 \u0005[\u0006היה \u0005פשוט לו]\u0006 \u0003לרבה.\u0004 ש\u0003אמר רבה:\u0004 אם טוען לחבירו: \u0003\"שורי גנבת\", והוא,\u0004 הנטען, \u0003אומר: \"לא גנבתי\",\u0004 ושואל אותו בעל השור:","\u0003\"\u0004אם כן \u0003מה טיבו\u0004 (עניינו) \u0003אצלך\"?\u0004 כלומר, מהו עושה אצלך? ואמר לו: \u0003\"שומר חנם אני עליו\"\u0004 ונשבע על כך ואחר כך הודה ששיקר — \u0003חייב,\u0004 ומדוע? שאף שמודה שהשור שייך לחבירו, כיון שאומר שהוא שומר חינם \u0003הרי\u0004 בכך \u0003פטר עצמו מגניבה ואבידה,\u0004 ולכן אם ייגנב השור מרשותו לא יצטרך לשלם, שהרי הוא שומר חינם בלבד, ונמצא שהוא בכל זאת מרוויח ממון בטענת השקר שלו, שהרי בתור גזלן היה חייב אף במקרה שאירע אונס לשור.","וכיוצא בזה אם אמר לו: \u0003\"שומר שכר אני עליו\"\u0004 — עדיין \u0003חייב\u0004 משום שבועת שקר, מדוע? \u0003שהרי\u0004 בטענתו זו \u0003פטר עצמו משבורה ומתה,\u0004 כלומר, אם תמות הבהמה באונס, שכן שומר שכר פטור באונסים.","ואפילו אם אמר: \u0003\"שואל אני עליו\"\u0004 ושואל חייב באונסים — \u0003חייב\u0004 על שבועתו, \u0003שהרי פטר עצמו\u0004 בטענתו זו אם הבהמה \u0003מתה מחמת מלאכה.\u0004","\u0003אלמא\u0004 \u0005[מכאן יוצא]\u0006 כי \u0003אף על גב דהא קאים\u0004 \u0005[אף על פי ש\u0006עכשיו \u0005הוא קיים\u0006 בעינו\u0005],\u0006 ולא הרויח הטוען כלום בטענתו, מכל מקום \u0003כיון דאי מיגניב ממונא קא כפר\u0004 \u0005[שאם ייגנב\u0006 ממנו נמצא ש\u0005ממון הוא כופר]\u0006 במה שהוא טוען שהוא שומר חינם, \u0003השתא נמי ממונא קא כפר\u0004 \u0005[עכשיו גם כן\u0006 נחשב כאילו \u0005ממון הוא כופר].\u0006 ואם כן \u0003הכא\u0004 \u0005[כאן]\u0006 בבעייתו של רבא בגזילת חמץ ושבועה לאחר שעבר עליו הפסח, \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר: \u0003אף על גב דעפרא בעלמא\u0004 \u0005[אף על פי ש\u0006עכשיו \u0005עפר בלבד]\u0006 \u0003הוא\u0004 מצד הדין, מכל מקום \u0003כיון דאי מיגניב בעי שלומי ליה ממונא מעליא\u0004 \u0005[שאם ייגנב צריך לשלם לו ממון מעולה],\u0006 \u0003השתא נמי ממונא קא כפר ליה\u0004 \u0005[עכשיו גם כן ממון הוא כופר לו].\u0006","אומרים: \u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רבא וקאמר להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו]\u0006 של רבה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב עמרם לרבא\u0004 ממה ששנינו בברייתא לענין אשם גזילות, מה שנאמר בתורה \u0003\"וכחש בה\"\u0004 (ויקרא ה, כב) הרי זה בא למעט — \u0003פרט למודה בעיקר\u0004 טענת הבעלים,","\u0003כיצד?\u0004 — אמר לו: \u0003\"שורי גנבת\", והוא,\u0004 הנטען, \u0003אומר: \"לא גנבתי\".\u0004","אומר לו: \u0003\"מה טיבו אצלך\"?\u0004 אומר לו הנטען: \u0003\"אתה מכרתו לי\",\u0004 או \u0003\"אתה נתתו לי במתנה\",\u0004 או \u0003\"אביך מכרו לי\",\u0004 או \u0003\"אביך נתנו לי במתנה\",\u0004 או \"השור הזה \u0003אחר פרתי רץ\u0004 והגיע לכאן\", או \u0003\"מאליו בא אצלי\",\u0004 או \u0003\"תועה בדרך מצאתיו\",\u0004 או \u0003\"שומר חנם אני עליו\",\u0004 או \u0003\"שומר שכר אני עליו\",\u0004 או \u0003\"שואל אני עליו\", ונשבע\u0004 על כך, \u0003ו\u0004אחר כך \u0003הודה\u0004 שהיתה זו שבועת שקר שגזלו, \u0003יכול יהא חייב\u0004 חומש ואשם? — \u0003תלמוד לומר: \"וכחש בה\"\u0004 — \u0003פרט למודה בעיקר.\u0004 כי במקרה זה הרי מודה בעיקר הטענה שהשור אינו שלו, והפרטים שנשבע עליהם לשקר אינם עיקר. והרי רבה אמר שהטוען \"שומר אני עליו\" חייב משום שבועת שקר חומש ואשם, למרות שהודה שהחפץ של חבירו הוא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב עמרם: \u0003תדורא\u0004 \u0005[שוטה]!\u0006 \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 שאינו חייב בטענת שומר — הרי זה במקרה \u0003דקאמר ליה\u0004 \u0005[שאומר לו]:\u0006 אכן שורך הוא זה ו\u0003הילך\u0004 (והא לך), הריני מחזיר אותו לך ונמצא שאינו עשוי להרוויח דבר בטענתו, \u0003כי קאמינא\u0004 \u0005[כאשר אני אומר]\u0006 — הרי זה באופן \u0003דקיימא\u0004 \u0005[\u0006שהשור \u0005עומד]\u0006 \u0003באגם,\u0004 כלומר במקום אחר. שאינו אומר לו קח אותו מיד, ובינתיים אינו נותן לו דבר, ורק טוען טענה. ובמקרה זה, שאם לא היה טוען שקר, עשוי היה להתחייב לו ממון — נחשב הדבר ככפירת ממון, וחייב על כך חומש ואשם.","על פירוש זה של הברייתא מקשים: אחת הטענות שטוען הנתבע היא: \u0003\"אתה מכרתו לי\", מאי\u0004 \u0005[מה]\u0006 \u0003מודה בעיקר איכא\u0004 \u0005[יש כאן]\u0006 בטענה זו? הרי בכך אינו מודה כלל ואדרבא הוא טוען שהשור שלו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא במקרה \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 אמנם אתה מכרתו לי אבל \u0003לא נתתי לך\u0004 עדיין \u0003דמי\u0004 \u0005[כסף]\u0006 עבורו, ולכן \u0003שקיל תורך וזיל\u0004 \u0005[קח\u0006 את \u0005שורך ולך].\u0006","ועוד שואלים: אם אומר לו \u0003\"אתה נתתו לי\u0004 במתנה \u0003\",\u0004 או \u0003\"אביך נתנו לי\u0004 במתנה \u0003\",\u0004 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מודה בעיקר איכא\u0004 \u0005[יש פה]?\u0006 הרי הוא טוען שהשור שלו! ומשיבים: \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הנטען: קיבלתי אותו במתנה \u0003על מנת דעבידנא\u0004 \u0005[שאעשה]\u0006 \u0003לך נייח דנפשא\u0004 \u0005[נחת רוח],\u0006 \u0003ולא עבדי\u0004 \u0005[עשיתי]\u0006 \u0003לך,\u0004 וכיון שלא מלאתי את התנאי — \u0003שקיל תורך וזיל\u0004 \u0005[קח\u0006 את \u0005שורך ולך].\u0006","ועוד שואלים: אם אמר לו: \u0003\"תועה בדרך מצאתיו\",\u0004 מה טענה היא זו? \u0003לימא\u0004 \u0005[יאמר]\u0006 לו הבעלים: \u0003איבעי לך לאהדוריה\u0004 \u0005[צריך היית להחזיר אותו לי]\u0006 \u0003לי!\u0004 \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל, באומר: שבועה, אבידה מצאתי, ולא הייתי יודע שהיא שלך שאחזירנה לך,\u0004 ומשום כך לא החזרתי.","ובענין זה של מי שנשבע ואינו כופר בממון ממש, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר בן עזאי: שלש שבועות הן\u0004 בשבועת העדות, שמשביע עד שיודע שאבידתו בידי אדם אחר, והלה כופר ואחר כך מודה: הודה ש\u0003הכיר בה\u0004 באבידה שהיא של בעליה, \u0003ולא במוצאה,\u0004 שאינו יודע ביד מי היתה, או הודה שהכיר \u0003במוצאה\u0004 שראה פלוני מוצא מציאה \u0003ולא בה,\u0004 או שלא הכיר \u0003לא בה ולא במוצאה.\u0004","ותוהים: אם לא הכיר \u0003לא בה ולא במוצאה?\u0004 אם כן \u0003קושטא אשתבע\u0004 \u0005[\u0006שבועת \u0005אמת\u0006 הוא \u0005נשבע],\u0006 שהרי באמת אינו יודע דבר ואינו מכיר לא למי האבידה ולא את מוצאה! ומתקנים, \u0003אימא\u0004 \u0005[אמור]:\u0006 הכיר \u0003בה ובמוצאה.\u0004","ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה,\u0006 נאמר דבר זה\u0005]?\u0006 \u0003רב אמי אמר\u0004 בשם \u0003ר' חנינא:\u0004 הכוונה היא \u0003לפטור,\u0004 לומר שהעד פטור משבועת העדות. \u0003ושמואל אמר:\u0004 בכולם הוא \u0003לחיוב.\u0004","ומעירים: \u0003ו\u0004הם חולקים \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 \u0003דהני תנאי\u0004 \u0005[של התנאים הללו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המשביע עד אחד\u0004 שבועת העדות, שיעיד עדות שראה או שידע שחבירו חייב לו ממון, והעד נשבע שאינו יודע לו עדות, ואחר כך הודה שכן יודע — \u0003פטור\u0004 העד מקרבן שבועה, \u0003ור' אלעזר בר' שמעון מחייב.\u0004","ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון, \u0005הם חלוקים]?\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר בר' שמעון, \u0005סבור]:\u0006 \u0003דבר הגורם ל\u0004חיוב \u0003ממון כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 וכיון שעד אחד יכול לגרום שהנתבע יודה וישלם הרי זה כעדות ממש. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 סתם ברייתא, \u0005סבור]:\u0006 \u0003לאו\u0004 \u0005[אינו]\u0006 \u0003כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שכיון שעדותו של עד אחד אינה מחייבת ממון כשלעצמה — אין זה נחשב כדבר של ממון.","\u0003אמר רב ששת: הכופר בפקדון\u0004 שטוען שאינו בידיו, ובאו עדים והעידו ששיקר והפקדון אצלו — \u0003נעשה עליו גזלן\u0004 משעה שכפר, \u0003וחייב\u0004 בתשלומים אף \u0003באונסין\u0004 שיארעו לפקדון, ולא רק בדברים שאירעו כתוצאה מפשיעה, כשומר חינם. \u0003ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה התנא שלנו]:\u0006 \u0003\"וכחש בה\"\u0004 (ויקרא ה, כב) — \u0003למדנו\u0004 מכאן \u0003עונש\u0004 למי שמכחש. \u0003אזהרה\u0004 ציווי ואיסור התורה שלא לעשות כן, \u0003מנין?\u0004 — \u0003תלמוד לומר: \"\u0004ו\u0003לא תכחשו\"\u0004 (שם יט, יא). \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה בדברי הברייתא \u0003לעונש ממון\u0004 שחייב אף באונסים משום ששיקר?","ודוחים: \u0003לא,\u0004 הכוונה היא \u0003לעונש שבועה,\u0004 כלומר, לחיוב חומש ואשם שחל על מי שנשבע לשקר. ומקשים: \u0003הא מדקתני סיפא ואישתבע\u0004 \u0005[הרי מ\u0006מה \u0005ששנה\u0006 ב\u0005סוף\u0006 אותה ברייתא \u0005שנשבע],\u0006 \u0003מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבתחילת\u0006 הברייתא\u0005]\u0006 מדובר באופן ש\u0003לא אישתבע\u0004 \u0005[נשבע\u0006\u0005]\u0006 ואין מדובר כאן אלא על הכחשה בלבד! \u0003דקתני סיפא\u0004 \u0005[שהוא שונה\u0006 ב\u0005סוף]:\u0006 \u0003\"ונשבע על שקר\"\u0004 (שם ה, כב) — \u0003למדנו עונש\u0004 חומש ואשם על שבועת שקר בפקדון, \u0003אזהרה מנין?\u0004 — \u0003תלמוד לומר: \"\u0004ו\u0003לא תשקרו\"\u0004 (שם יט, יא). \u0003ומדסיפא,\u0004 \u0005[ומ\u0006כיון \u0005שבסוף]\u0006 מדובר באופן \u0003דאישתבע\u0004 \u0005[שנשבע]\u0006 מכאן שב\u0003רישא\u0004 \u0005[\u0006ב\u0005תחילה]\u0006 מדובר באופן ש\u0003לא אישתבע\u0004 \u0005[נשבע]!\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003אידי ואידי דאישתבע\u0004 \u0005[זה וזה\u0006 מדובר \u0005שנשבע],\u0006 אלא \u0003כאן שהודה\u0004 בדבר בעצמו לאחר שנשבע, \u0003כאן שבאו עדים\u0004 והכחישוהו. אם \u0003אתו\u0004 \u0005[באו]\u0006 \u0003עדים\u0004 והעידו כנגדו — רק \u0003חייב באונסין\u0004 כדין גזלן, שהחפץ נהיה כשלו לענין זה. אם \u0003אודויי אודי\u0004 \u0005[הודה\u0006 בדבר\u0005]\u0006 — \u0003חייב\u0004 גם \u0003בקרן וחומש ואשם.\u0004","על דברי רב ששת שהכופר בפקדון נחשב גזלן מזמן שכפר, אף בלא שבועה, \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רמי בר חמא:\u0004 במשנה במסכת שבועות מנויים מקרים בהם (שלא כרגיל) התובע הוא הנשבע על דבריו, ונוטל מה שתבע, \u0003ו\u0004בין אלה מונים \u0003שכנגדו חשוד על השבועה,\u0004 כלומר, כאשר בעל הדין שכנגדו שצריך היה להישבע ולהפטר מן התביעה, חשוד על שבועת שקר. ומבארת המשנה \u0003כיצד\u0004 נחשב חשוד על השבועה? — \u0003אחד\u0004 שנשבע בשקר \u0003שבועת העדות, ואחד שבועת הפקדון, ואפילו שבועת שוא\u0004 (שאינה של ממון).","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי רב ששת, לא היה צריך למנות את שבועת הפקדון, שהרי לדעת רב ששת, הלא כבר \u0003ב\u0004זמן ה\u0003כפירה\u0004 בפיקדון \u0003הוא דאיפסיל ליה\u0004 \u0005[\u0006\u0005ש\u0006\u0005נפסל לו]\u0006 כגזלן, והוא פסול לשבועה משום כך!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 שמתחייב רק לאחר שבועת שקר, \u0005במה אנו עוסקים]?\u0006 \u0003דקאי\u0004 \u0005[ש\u0006הבהמה \u0005עומדת]\u0006 עכשיו \u0003באגם,\u0004 \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003כפירה הוא\u0004 נחשב, ואין הכופר נפסל כגזלן בשבילה, משום שאפשר \u0003דסבר\u0004 \u0005[ש\u0006הוא, הגזלן, \u0005חושב]\u0006 בליבו: \u0003אשתמיטנא ליה אדאזילנא ומייתינא ליה\u0004 \u0005[אשתמט ממנו\u0006 ואומר שלא קיבלתי פיקדון \u0005עד שאלך ואביא לו אותה],\u0006 ובמקרה כזה רק כאשר נשבע לשקר שלא קיבל פיקדון הוא נפסל משעת השבועה. ורב ששת, המחשיבו כגזלן משעת כפירה, עוסק במקרה בו העידו עדים שבזמן שכפר בו היה החפץ ברשותו.","\u0003תדע\u0004 שכן הוא, שכל המשתמט שכוונתו אחר כך להחזיר אינו נחשב כגזלן — ש\u0003אמר רב אידי בר אבין: הכופר במלוה,\u0004 שאומר שלא לווה ובאו עדים והעידו שלווה — \u0003כשר לעדות,\u0004"],["ואילו הכופר \u0003בפקדון\u0004 — \u0003פסול לעדות,\u0004 שאם ברור שהפקדון בידו והוא כופר בו — אין כאן מקום לטענות השתמטות, אלא ודאי הוא משקר.","ועוד מקשים על שיטת רב ששת: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אילפא: שבועה קונה,\u0004 ומשמע שמשעה שנשבע לשקר נחשב הדבר כשלו, להתחייב בו באונסים, ונדייק: \u0003שבועה היא דקניא\u0004 \u0005[שקונה],\u0006 \u0003אבל כפירה\u0004 בלבד \u0003לא קניא\u0004 \u0005[קונה]!\u0006 ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003דקיימא\u0004 \u0005[שעומדת]\u0006 הפרה \u0003באגם,\u0004 שכל עוד לא נשבע אנו מניחים שאין כוונתו אלא להשתמט, אבל אם היתה בביתו — קנה מזמן הכפירה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שבועה קונה\"\u0004 שאמר אילפא? — \u0003כ\u0004דברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא אמר רב,\u0004 התובע את חבירו: \u0003\"מנה\u0004 (מטבע של מאה דינר) יש \u0003לי בידך\", והלה אומר: \"אין לך בידי\", ונשבע\u0004 על טענתו, \u0003ואחר כך באו עדים\u0004 והעידו ששיקר בשבועתו — \u0003פטור\u0004 מלשלם, \u0003שנאמר:\u0004 \u0003\"\u0004שבועת ה' תהיה בין שניהם אם לא שלח ידו במלאכת רעהו \u0003ולקח בעליו ולא ישלם\"\u0004 (שמות כב, י), לומר: \u0003כיון שקבלו הבעלים שבועה, שוב אין משלם ממון\u0004 והשבועה מקנה את החפץ לנתבע.","כיון שהוזכרה הלכה זו באים עתה לדון בה \u0003גופא\u0004 \u0005[עצמה].\u0006 \u0003אמר רב הונא אמר רב,\u0004 טענו: \u0003\"מנה לי בידך\", והלה,\u0004 הנתבע, \u0003אומר: \"אין לך בידי כלום\", ונשבע\u0004 על טענתו \u0003ובאו עדים\u0004 והעידו ששיקר בשבועתו — \u0003פטור, שנאמר: \"ולקח בעליו ולא ישלם\", כיון שקבלו בעלים שבועה, שוב אין משלמין ממון.\u0004","\u0003אמר רבא: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003רב\u0004 דווקא בכופר \u0003במלוה,\u0004 ש\u0003להוצאה ניתנה,\u0004 שאין הכסף עוד בנמצא, ופטרו הכתוב מלשלם ממון אם נשבע עליו, \u0003אבל פקדון\u0004 — \u0003ברשותיה דמריה קאי\u0004 \u0005[ברשות בעליו\u0006 הוא \u0005עומד]\u0006 ואין בו חובת תשלום שיש לפוטרו ממנה, אלא השבתו כפי שהוא. והוסיף רבא בלשון שבועה: \u0003והאלהים!\u0004 \u0003אמר רב\u0004 את דבריו אלו \u0003אפילו בפקדון,\u0004 שאם נשבע עליו פטור מלהשיבו, \u0003דכי כתיב קרא\u0004 \u0005[שכאשר נאמר פסוק\u0006 זה\u0005]\u0006 \"ולקח בעליו ולא ישלם\" \u0003בפקדון כתיב\u0004 \u0005[נאמר].\u0006","ומסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב נחמן וקאמר להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו]\u0006 שאמר רב הונא בשם רב. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אחא בר מניומי לרב נחמן\u0004 ממה ששנינו במשנה, אמר לחבירו: \u0003\"היכן פקדוני\"? אמר לו: \"אבד\",\u0004 אמר לו המפקיד: \u0003\"משביעך אני\", ואמר\u0004 הלה: \u0003\"אמן\", והעדים מעידים אותו,\u0004 את הנתבע, \u0003שאכלו,\u0004 כלומר, שהשתמש בו עד שכלה — \u0003משלם את הקרן,\u0004 ואם \u0003הודה מעצמו\u0004 שנשבע לשקר — \u0003משלם קרן וחומש ואשם!\u0004 משמע שאף אחרי שנשבע — משלם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון\u0004 ש\u0003נשבע חוץ לבית דין,\u0004 שאין שבועה זו נחשבת כדי לפטור אותו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור\u0006 את מה ששנינו \u0005בסוף\u0006 המשנה\u0005],\u0006 אמר לחבירו: \u0003\"היכן פקדוני\"? אמר לו: \"נגנב\",\u0004 אמר לו: \u0003\"משביעך אני\", ואמר: \"אמן\", והעדים מעידים אותו ש\u0004הוא עצמו \u0003גנבו\u0004 — \u0003משלם תשלומי כפל.\u0004 אם \u0003הודה מעצמו\u0004 — \u0003משלם קרן וחומש ואשם. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שמדובר כאן בשבועה \u0003חוץ לבית דין, מי איכא\u0004 \u0005[האם יש]\u0006 חובת \u0003כפל\u0004 על שבועה כגון זו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003יכילנא לשנויי\u0004 \u0005[הייתי יכול לתרץ]\u0006 \u0003לך\u0004 כי \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילת\u0006 המשנה\u0005]\u0006 מדובר שנשבע \u0003חוץ לבית דין, וסיפא\u0004 \u0005[וסופה]\u0006 מדובר שנשבע \u0003בבית דין. מיהו שינויא דחיקא\u0004 \u0005[אולם תירוץ דחוק]\u0006 \u0003לא משנינן\u0004 \u0005[אתרץ]\u0006 \u0003לך.\u0004 אלא כך צריך להסביר: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר שנשבע \u0003בבית דין, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה];\u0006 \u0003כאן בקפץ,\u0004 כלומר, שקפץ ונשבע מעצמו, כשתבעו לכך בעל דינו, שלא חייבוהו הדיינים עדיין להישבע, ואין זו שבועה גמורה, ו\u0003כאן בשלא קפץ.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא לרב נחמן: מכדי\u0004 \u0005[הרי]\u0006 שיטתו של \u0003רב לא סבירא\u0004 \u0005[מסתברת\u0006 נראית\u0005]\u0006 \u0003לך, משכוני נפשך\u0004 \u0005[למשכן את עצמך]\u0006 לדחוק ולפרש דברים לשיטתו של \u0003רב למה לך?\u0004 יכולת לומר שבאמת קושיה היא עליו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 לא אמרתי זאת לעצם ההלכה אלא \u0003לפרושה\u0004 \u0005[לפרש]\u0006 את דברי \u0003רב,\u0004 ש\u0003רב הכי\u0004 \u0005[כך]\u0006 הוא \u0003מתרץ לה למתניתין\u0004 \u0005[את משנתנו].\u0006","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב קרא קאמר\u0004 \u0005[כתוב\u0006 הוא \u0005אומר]\u0006 ולכאורה לשון הכתוב מסייעת לו! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003קרא\u0004 \u0005[הכתוב]\u0006 לא לענין זה נאמר, אלא \u0003ל\u0004למד ענין אחר: ש\u0003כל הנשבעין שבתורה נשבעין ולא משלמין הוא דאתא\u0004 \u0005[שבא].\u0006 ללמדנו שכל שבועה שבתורה היא כדי לפטור את הנשבע מתביעה, ולא כדי לקבל דבר מאחרים. וכך מדייקים מפסוק זה: \u0003\"ולקח בעליו ולא ישלם\"\u0004 — \u0003מי שעליו לשלם הוא נשבע.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא\u0004 על שיטת רב ממקור אחר, ששנינו במשנה: \u0003השביע עליו,\u0004 כלומר, תבע את פקדונו והזקיקו להישבע שאין הוא בידו \u0003חמשה פעמים, בין\u0004 שנשבע \u0003בפני בית דין ובין\u0004 שנשבע \u0003שלא בפני בית דין, וכפר עליו,\u0004 שנשבע בכל פעם שהחפץ אינו בידו — \u0003חייב על כל אחת ואחת\u0004 מן השבועות שהשביעהו חומש ואשם משום שבועת הפקדון, \u0003ואמר ר' שמעון: מה טעם?\u0004 — \u0003הואיל ויכול לחזור ולהודות\u0004 לאחר כל שבועה, ואז יחול עליו חיוב תשלום, ונמצא שבשבועה הבאה הוא כופר בחובה זו. ולענייננו למדים מכאן שאם מודה לאחר שבועה — חייב בתשלום, שלא כשיטת רב!","\u0003והכא\u0004 \u0005[וכאן]\u0006 בפירוש משנה זו לתרץ שמדובר ב\u0003קפץ\u0004 מעצמו ונשבע \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר],\u0006 שהרי \u0003\"השביע עליו\" קתני\u0004 \u0005[שנה],\u0006 ולתרץ שמדובר שנשבע \u0003חוץ לבית דין\u0004 גם כן \u0003לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר],\u0006 שהרי \u0003\"בפני בית דין\" קתני\u0004 \u0005[שנה]!\u0006","ומוסיפים: \u0003הוא,\u0004 רב המנונא, \u0003מותיב לה\u0004 \u0005[הקשה אותה],\u0006 את הקושיה הזו, \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[תירץ אותה]\u0006 ש\u0003לצדדין קתני\u0004 \u0005[שנה]\u0006 בברייתא. כלומר, משנה זו אינה שנויה כהמשך אחד אלא במקרים שונים היא עוסקת. מה ששנה \u0003השביע עליו\u0004 — \u0003חוץ לבית דין\u0004 נאמר, \u0003ו\u0004מה שנאמר \u0003ב\u0004פני \u0003בית דין\u0004 מדובר במקרה ש\u0003קפץ\u0004 הנתבע ונשבע מעצמו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על שיטת רב, ממה ששנינו במקום אחר: \u0003בעל הבית שטען טענת גנב בפקדון,\u0004 שנגנב ממנו פקדון שהופקד בידו, \u0003ונשבע\u0004 על טענתו \u0003ו\u0004לאחר מכן \u0003הודה\u0004 ששיקר, \u0003ו\u0004גם \u0003באו עדים\u0004 להעיד כנגדו, \u0003אם עד שלא באו עדים הודה\u0004 — \u0003משלם קרן וחומש ואשם, ואם משבאו עדים הודה\u0004 — \u0003משלם תשלומי כפל\u0004 (ובתוך זה נכלל החומש) \u0003ואשם.\u0004 הרי שגם מי שנשבע משלם.","\u0003והכא\u0004 \u0005[וכאן]\u0006 לתרץ שמדובר \u0003חוץ לבית דין ו\u0004כיוצא בזה \u0003קפץ\u0004 — \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר],\u0006 שהרי \u0003כפל קתני\u0004 \u0005[שנה]\u0006 בברייתא, ותשלום כפל אין משלם אלא כשנשבע על פי המשביע אותו, ובבית דין!","\u0003אלא אמר רבא: כל\u0004 מקום שנשבע לשקר ו\u0003הודה, לא שנא\u0004 \u0005[שונה]\u0006 ש\u0003טוען טענת אבד,\u0004 כלומר, שהחפץ אבד ממנו, \u0003ולא שנא\u0004 \u0005[שונה]\u0006 \u0003טוען טענת גנב,\u0004 שהחפץ נגנב ממנו, בזה \u0003לא אמר רב\u0004 שנפטר מתשלום, \u0003דהא כתיב\u0004 \u0005[שהרי נאמר]\u0006 \u0003\"והתודה\"\u0004 (במדבר ה, ז) שנאמר שם \"והתוודו את חטאתם אשר עשו והשיב את אשמו בראשו וחמישתו יוסף עליו ונתן לאשר אשם לו\", לומר שכל המודה בשבועת הפקדון \u0003דבעי שלומי\u0004 \u0005[שצריך לשלם]\u0006 \u0003קרן וחומש.\u0004","וכן אם \u0003טוען טענת גנב ובאו עדים\u0004 והוכיחו שהוא עצמו גנב, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמר רב, דהא כתיב\u0004 \u0005[שהרי נאמר]\u0006 במפורש בתורה \u0003תשלומי כפל,\u0004 שמשלם הטוען טענת גנב, שגזירת הכתוב היא שכיון שטען טענה זו והוכחש — משלם כפל. \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 רב את דבריו, היה זה רק \u0003כגון שטוען טענת אבד, ונשבע ולא הודה ובאו עדים.\u0004","מסופר: \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב גמדא ואמרה לשמעתא\u0004 \u0005[את השמועה,\u0006 ההלכה הזו\u0005]\u0006 של רבא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אשי אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה\u0004 אם \u0003רב המנונא\u0004 שהיה \u0003תלמידיה\u0004 \u0005[תלמידו]\u0006 של \u0003רב\u0004 עצמו, \u0003וידע דאמר\u0004 \u0005[ויודע שאומר]\u0006 \u0003רב\u0004 שהנשבע פטור גם במקרה ש\u0003הודה, וקמותיב\u0004 \u0005[והוא מקשה]\u0006 עליו ממשנה ממנה מוכח שחייב במקרה ש\u0003הודה, ואת אמרת\u0004 \u0005[ואתה אומר]:\u0006 במקרה ש\u0003הודה לא אמר רב\u0004 שפטור?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא סבא לרב אשי: רב המנונא\u0004 לא הקשה על רב בנוגע למקרה שהודה, אלא על מקרה שבאו עדים לאחר שנשבע, ו\u0003הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו]:\u0006"],["\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שגם אם \u0003נשבע, כי אתו\u0004 \u0005[כאשר באים]\u0006 \u0003עדים מיחייב\u0004 \u0005[הריהו מתחייב]\u0006 לשלם — \u0003אמטו להכי מחייבינן ליה\u0004 \u0005[משום כך מחייבים אנו אותו]\u0006 גם \u0003קרבן\u0004 על ה\u0003שבועה בתרייתא\u0004 \u0005[האחרונה],\u0006 \u0003הואיל ויכול\u0004 עדיין \u0003לחזור ולהודות,\u0004 ומה שחזר ונשבע הריהו כפירה על דבר שיש בו חיוב ממון.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 \u0003כי אתו\u0004 \u0005[כאשר באים]\u0006 \u0003עדים פטור, מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003אילו אתי סהדי ומסהדי ביה\u0004 \u0005[יבואו עדים ויעידו בו]\u0006 יהיה \u0003פטור, ואנן ניקו ניחייביה\u0004 \u0005[ואנו נעמוד\u0006 ו\u0005נחייב אותו]\u0006 \u0003קרבן\u0004 על ה\u0003שבועה\u0004 רק מהטעם ש\u0003הואיל ויכול לחזור ולהודות?\u0004 הרי \u0003השתא מיהת\u0004 \u0005[עכשיו על כל פנים]\u0006 \u0003לא אודי\u0004 \u0005[הודה],\u0006 ולא נתחייב בממון, ולכן אף שבועות נוספות שנשבע לא היתה בהן כפירת ממון כלל! ונמצא שאין לסתור את הסברו של רבא לדברי רב, מקושייתו של רב המנונא.","ועוד בענין זה של טוען טענת גנב בפקדון \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב בפקדון\u0004 והתברר שלא היה הדבר אמת אלא הוא עצמו גנבו — \u0003משלם תשלומי כפל,\u0004 ואם \u0003טבח ומכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה.\u0004","והוא מוכיח את דבריו מתוך ההשוואה הבאה: \u0003הואיל וגנב\u0004 עצמו \u0003משלם תשלומי כפל, וטוען טענת גנב\u0004 בפקדון אף הוא \u0003משלם תשלומי כפל,\u0004 כמבואר לעיל (בבא קמא סג,ב), אם כן דין טוען טענת גנב בפקדון כדין גנב ולכן גם יש להסיק מכאן: \u0003מה גנב שהוא משלם\u0004 תשלומי \u0003כפל,\u0004 אם \u0003טבח ומכר משלם תשלומי ארבעה וחמשה\u0004 — \u0003אף טוען טענת גנב בפקדון, כ\u0004שם \u0003שהוא משלם תשלומי כפל,\u0004 כך אם \u0003טבח ומכר משלם תשלומי ארבעה וחמשה.\u0004","ומקשים על השוואה זו: \u0003מה לגנב\u0004 שיש בו חומרה מיוחדת — \u0003שכן משלם תשלומי כפל שלא בשבועה, תאמר בטוען טענת גנב\u0004 — \u0003שאין משלם תשלומי כפל אלא בשבועה,\u0004 לאחר שנשבע על טענתו זו ונמצא ששיקר, ואין ללמוד מכאן לחיובו של טוען טענת גנב בתשלומי ארבעה וחמישה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003היקישא\u0004 \u0005[היקש]\u0006 \u0003היא\u0004 שמקיש הכתוב טוען טענת גנב לגנב, \u0003ואין משיבין\u0004 (מקשים) \u0003על היקישא\u0004 \u0005[ההיקש]\u0006 שאינו מבוסס אלא על סמיכות הכתובים.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שאכן קיים היקש כזה, כתוב \u0003חד\u0004 \u0005[אחד]\u0006 מדבר \u0003בגנב, ו\u0004כתוב \u0003חד\u0004 \u0005[אחד]\u0006 מדבר \u0003בטוען טענת גנב,\u0004 ולפי זה \u0003שפיר\u0004 \u0005[יפה],\u0006 שיש היקש המשווה ביניהם. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"אם ימצא הגנב\"\u0004 (שמות כב, ו) \u0003ו\u0004גם הכתוב \u0003\"אם לא ימצא\"\u0004 (שם ז), \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 מדברים \u0003בטוען טענת גנב, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: הוא לומד מריבוי הלשון \u0003\"גנב\" \"הגנב\",\u0004 כלומר, מתוספת הה\"א, שתשלומי ארבעה וחמישה האמורים בגנב הם גם בטוען טענת גנב.","לאחר שהביא את דבריו \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן\u0004 על שיטתו ממה ששנינו, אמר לחבירו: \u0003\"היכן שורי\"?\u0004 אמר לו הנתבע: \u0003\"נגנב\",\u0004 אמר לו: \u0003\"משביעך אני\", ואמר\u0004 הנתבע: \u0003\"אמן\", והעדים מעידים אותו שאכלו\u0004 את השור — \u0003משלם תשלומי כפל. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003אי אפשר ל\u0004אכול אפילו \u0003כזית בשר\u0004 מן השור \u0003בלא שחיטה,\u0004 שהרי נאמר שאכלו, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003משלם תשלומי כפל.\u0004 ונדייק מכאן: \u0003תשלומי כפל\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואילו \u0003תשלומי ארבעה וחמשה\u0004 — \u0003לא!\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שאכלו נבילה,\u0004 וזה אינו נחשב ל\"טבח\" שהתורה מחייבת עליו תשלומי ארבעה וחמישה.","ושואלים: \u0003ולישני ליה\u0004 \u0005[ושיתרץ לו]\u0006 ר' יוחנן לר' חייא בר אבא שמדובר \u0003כגון שאכלו טריפה\u0004 וכדעת ר' שמעון, הסבור ששחיטה שאינה ראויה לאכילה (כגון הטריפה) אינה נחשבת שחיטה לחייבו ארבעה וחמישה משום \"וטבחו\"! ומשיבים: ר' יוחנן סבור \u0003כ\u0004שיטת \u0003ר' מאיר, דאמר\u0004 \u0005[שאומר]:\u0006 \u0003שחיטה שאינה ראויה\u0004 אף על פי שאינה שחיטה כדין \u0003שמה שחיטה.\u0004","ושואלים עוד: \u0003ולישני ליה\u0004 \u0005[ושיתרץ לו]\u0006 שמדובר כאן \u0003בבן פקועה,\u0004 ולד חי שהוציאוהו מרחם אימו לאחר שנשחטה, שאפשר לאכול אותו בהיתר בלי לשחוט אותו, ואין חייבים על אכילתו ארבעה וחמישה! ומשיבים: ר' יוחנן סבור \u0003כ\u0004שטת \u0003ר' מאיר דאמר\u0004 \u0005[שאומר]:\u0006 \u0003בן פקועה טעון\u0004 (חייב) \u0003שחיטה\u0004 להתירו באכילה.","ושואלים עוד: \u0003ולישני ליה\u0004 \u0005[ושיתרץ לו]\u0006 שמדובר כאן \u0003כגון שעמד\u0004 הטוען טענת גנב \u0003בדין, ואמרו לו\u0004 הדיינים בפסק \u0003\"צא תן לו\". דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רבא:\u0004 אם עמד הגנב בדין ואמרו לו בבית דין: \u0003\"צא תן לו\"\u0004 את הגניבה, ולא עשה כן ואחר כך \u0003טבח ומכר\u0004 — \u0003פטור\u0004 מתשלומי ארבעה וחמישה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003כיון דפסקיה למילתיה\u0004 \u0005[שפסק\u0006 בית הדין \u0005את הדבר]\u0006 בכך שאמר לו \"צא תן לו\", וכבר יצא מכלל דין הגניבה, והוא לא שם לבו כלל להוראת בית דין \u0003וטבח ומכר הוי\u0004 \u0005[הריהו]\u0006 \u0003גזלן, וגזלן לא משלם תשלומי ארבעה וחמשה.\u0004","אבל אם רק נאמר לו בבית הדין: \u0003\"חייב אתה ליתן לו\", וטבח ומכר\u0004 — \u0003חייב\u0004 בתשלומי ארבעה וחמישה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003כל כמה\u0004 ש\u0003לא פסיקא ליה מילתא, אכתי\u0004 \u0005[נפסק לו,\u0006 נחתך \u0005לו הדבר, עדיין]\u0006 \u0003גנב הוא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003לישני ליה\u0004 \u0005[שיתרץ לו]\u0006 באופן אחר: שמדובר כאן \u0003בשותף שטבח שלא מדעת חבירו,\u0004 שלמדנו שגזירת הכתוב היא שאינו משלם ארבעה וחמישה! \u0003אלא חדא מתרי ותלתא נקט\u0004 \u0005[אחד\u0006 התירוצים \u0005מתוך שנים ושלושה\u0006 תירוצים \u0005תפס]\u0006 ואין הכוונה לומר שזהו התירוץ היחיד, ובאמת אפשר לתרץ את שאלת ר' חייא בר אבא גם בדרכים אחרות.","\u0003ו\u0004עוד \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב באבידה,\u0004 שמצא אבידה ונתבע להשיבה לבעליה וטען שנגנבה ממנו, והתברר ששיקר והוא עצמו לקח אותה — \u0003משלם תשלומי כפל. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 בכתובים המדברים על תשלומי כפל גם \u0003\"על כל אבדה אשר יאמר\"\u0004 (שמות כב, ח), משמע שאף על טענת גנב באבידה משלם כפל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא בר ממל לר' חייא בר אבא\u0004 ממה ששנינו בברייתא, נאמר: \u0003\"כי יתן איש\u0004 אל רעהו כסף או כלים לשמור\u0003\"\u0004 (שם ו), ומן הביטוי \"איש\" שמובנו גדול למדנו כי \u0003אין נתינת קטן\u0004 נחשבת \u0003כלום\u0004 (משהו) לענין זה, שאין הפרשה עוסקת בקטן שהפקיד אצל חבירו. \u0003ואין לי אלא שנתנו כשהוא קטן ותבעו כשהוא קטן\u0004 שפטור הנתבע, ואולם אם \u0003נתנו\u0004 לו \u0003כשהוא קטן ותבעו\u0004 אחר כך \u0003כשהוא גדול, מנין\u0004 שגם זו אינה תביעה? — \u0003תלמוד לומר: \"עד האלהים יבא דבר שניהם\"\u0004 (שם ח), לומר: \u0003עד שתהא נתינה ותביעה שוין כאחד,\u0004 שבשתיהן צריך הנותן להיות גדול. עד כאן לשון הברייתא.","\u0003ואם איתא\u0004 \u0005[שכן הוא]\u0006 כדברי ר' יוחנן, שאף המוצא אבידה משלם תשלומי כפל על טענת גניבה, הרי שאין צורך בנתינה של בעלים כדי לחייבו, \u0003תיהוי נמי\u0004 \u0005[תהא גם כן]\u0006 תביעת קטן \u0003כאבידה,\u0004 שהרי אף באבידה לא ניתן הדבר מיד הבעלים למוצא, ובכל זאת חייב על כך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בענין הקטן, \u0005במה אנו עוסקים]\u0006 — \u0003כגון שאכלו\u0004 המוצא את האבידה \u0003כשהוא\u0004 הבעלים היה עדיין \u0003קטן,\u0004 ונמצא שכשתובעו כשהוא גדול — אינו תובעו דבר של ממש.","ושואלים, נדייק מתשובה זו: \u0003אבל\u0004 אם אכלו \u0003כשהוא גדול, מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יהיה ש\u0003משלם? אי הכי, אדתנא\u0004 \u0005[אם כך, עד ש\u0006הוא \u0005שונה]\u0006 בהמשך הברייתא את הכלל: \u0003עד שתהא נתינה ותביעה שוין כאחד, ליתני\u0004 \u0005[שישנה]\u0006 בצורה יותר מדוייקת ובחלוקה יותר דקה: \u0003עד שתהא אכילה ותביעה שוין כאחד! אמר ליה\u0004 \u0005[לו],\u0006 תקן ו\u0003תני\u0004 \u0005[שנה]:\u0006 \u0003עד שתהא אכילה ותביעה שוין כאחד.\u0004","\u0003רב אשי אמר\u0004 תירוץ אחר לשאלת ר' אבא בר ממל: \u0003לא דמי\u0004 \u0005[אין\u0006 הדברים \u0005דומים]\u0006 ואין להקשות מהברייתא העוסקת בנתינת קטן על דברי ר' חייא בר אבא שעניינם באבידה, שכן \u0003אבידה\u0004 בכל אופן \u0003קא אתיא\u0004 \u0005[באה]\u0006 \u0003מכח בן־דעת,\u0004 שהמאבד היה ברדעת, אף על פי שהוא עצמו לא נתנה \u0003והא\u0004 \u0005[וזו]\u0006 של הקטן \u0003לא אתיא\u0004 \u0005[באה]\u0006 לידו \u0003מכח בן דעת,\u0004 וכיון שאינו בן דעת אין זה נחשב לעילה של תביעה.","\u0003ו\u0004עוד \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב בפקדון\u0004 שהופקד אצלו, \u0003אינו חייב\u0004 שבועה, ולא תשלומי כפל \u0003עד שיכפור במקצת ויודה במקצת. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין זה: \"אשר יאמר \u0003כי הוא זה\u0004 עד האלהים יבוא דבר שניהם, אשר ירשיעון אלהים ישלם שנים לרעהו\" (שם ח), שפירשו אותו שהכוונה היא שמודה במקצת וכופר במקצת. ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 הלכה זו על הלכה זו של \u0003ר' חייא בר יוסף,\u0004 ש\u0003אמר ר' חייא בר יוסף:\u0004"],["\u0003עירוב פרשיות כתוב כאן,\u0004 כלומר, פרשה זו אינה עוסקת רק בנושא אחד אלא יש בה גם ענין הנוגע לפרשה אחרת. \u0003וכי כתיב\u0004 \u0005[וכאשר נאמר]:\u0006 \u0003\"כי הוא זה\"\u0004 שעניינו שמודה במקצת הטענה — על \u0003מלוה הוא דכתיב\u0004 \u0005[שנאמר]\u0006 ולא לגבי פקדון. ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה השוני]\u0006 בין \u0003מלוה\u0004 ופקדון?","ומשיבים: \u0003כ\u0004פי שאמר \u0003רבה,\u0004 ש\u0003אמר רבה: מפני מה אמרה תורה מודה במקצת\u0004 (בחלק) \u0003הטענה ישבע?\u0004 — לההסבר לכך הוא זה: \u0003חזקה\u0004 היא ש\u0003אין אדם מעיז פניו בפני בעל חובו,\u0004 לכפור בטובה שעשה לו. \u0003והאי בכולי בעי דנכפריה\u0004 \u0005[וזה,\u0006 הנתבע שכופר במקצת הטענה, באמת \u0005בכל רוצה לכפור],\u0006 \u0003והאי דלא כפריה\u0004 \u0005[וזה שאינו כופר]\u0006 בכל ואינו מכחיש ואומר שלא היו דברים מעולם — \u0003משום\u0004 חזקה זו ש\u0003אין אדם מעיז פניו\u0004 בפני בעל חובו.","\u0003ו\u0004משום כך באמת \u0003בכולי בעי דלודי ליה\u0004 \u0005[בכל רוצה להודות לו],\u0006 \u0003והאי דכפר ליה\u0004 \u0005[וזה ש\u0006הוא \u0005כופר לו]\u0006 \u0003במקצת\u0004 — \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005],\u0006 כך הוא אומר לעצמו: \u0003אי מודינא ליה בכוליה\u0004 \u0005[אם אודה לו על הכל]\u0006 \u0003תבע לי בכוליה\u0004 \u0005[יתבע אותי על הכל]\u0006 ואין לי עתה לשלם, \u0003אישתמיט\u0004 \u0005[אשתמט]\u0006 \u0003לי מיהא השתא אדהוו\u0004 \u0005[בכך אופן עכשיו עד שיהיה]\u0006 \u0003לי זוזי ופרענא\u0004 \u0005[כסף ואפרע\u0006 לו\u0005]\u0006 את הכל, \u0003הלכך רמא רחמנא\u0004 \u0005[משום כך הטילה התורה]\u0006 \u0003שבועה עילויה\u0004 \u0005[עליו]\u0006 \u0003כי היכי דלודי ליה בכוליה\u0004 \u0005[כדי שיודה לו בכל].\u0006","\u0003וגבי\u0004 \u0005[ואצל]\u0006 \u0003מלוה הוא דאיכא למימר הכי\u0004 \u0005[שיש לומר כך]\u0006 שאין אדם מעיז פניו, משום שהמלוה עושה טובה ללווה, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003פקדון\u0004 שאין עושה לו טובה בזה שהפקיד בידו — \u0003מעיז ומעיז,\u0004 ועשוי לכפור הכל. ומשום כך יש סברה לומר כי המודה במקצת הטענה בפקדון אינו נאמן פחות או יותר מזה שכפר בכל, ובכל מקרה חייב.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר חמא\u0004 ברייתא זו: \u0003ארבעה שומרין\u0004"],["כדי שיתחייבו בשבועה על תביעת תשלומים שהם נתבעים, \u0003צריכין\u0004 שיטענו טענה שיש בה \u0003כפירה במקצת והודאה במקצת, ואלו הן\u0004 ארבעת השומרים: \u0003שומר חנם והשואל, נושא שכר והשוכר.\u0004","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רמי בר חמא? שומר חנם, בהדיא כתיב ביה\u0004 \u0005[בפירוש נאמר בו]\u0006 \u0003\"\u0004אשר יאמר \u0003כי הוא זה\"\u0004 (שמות כב, ח), משמע שהוא מודה במקצת הטענה. \u0003שומר שכר, יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה \u0003\"נתינה\" \"נתינה\" משומר חנם,\u0004 שבשתי הפרשיות נאמר \"כי יתן איש אל רעהו\" (שם פסוקים ו, ט).","\u0003שואל,\u0004 לומד ממה שנאמר בו: \u0003\"וכי ישאל\u0004 איש מעם רעהו\u0003\"\u0004 (שם פסוק יג). \u0003וי\"ו\u0004 של \"וכי\" \u0003מוסיף על ענין ראשון,\u0004 לומר שהדינים האמורים קודם בשומר חינם ושומר שכר שייכים גם בשואל, אלא שיש בו גם דינים מיוחדים לו. \u0003שוכר, אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 ששוכר דינו \u0003כשומר שכר\u0004 — \u0003היינו\u0004 \u0005[הריהו]\u0006 \u0003שומר שכר, אי למאן דאמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שאומר]\u0006 שדינו \u0003כשומר חנם\u0004 — \u0003היינו\u0004 \u0005[הריהו]\u0006 כ\u0003שומר חנם.\u0004","\u0003ו\u0004עוד באותו ענין \u0003אמר ר' חייא בר יוסף:\u0004 שומר חינם \u0003הטוען טענת גנב בפקדון,\u0004 שטוען שנגנב ממנו, והתברר ששיקר — \u0003אינו חייב\u0004 לשלם כפל \u0003עד שישלח בו יד,\u0004 שהעידו עדים שעשה בפקדון מלאכה, או נטל חלק ממנו קודם שנשבע. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — שנאמר בפרשה זו של טוען טענת גנב: \u0003\"ונקרב בעל הבית אל האלהים\u0004 (בשבועה) \u0003אם לא שלח ידו במלאכת רעהו\"\u0004 (שם ז), ובהמשך נאמר: \"אשר ירשיעון אלהים ישלם שנים לרעהו\", \u0003מכלל\u0004 הדברים אתה לומד: \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003שלח בה יד\u0004 — \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 בכפל, \u0003למימרא\u0004 \u0005[לומר\u0006 מכאן\u0005],\u0006 ש\u0003בשלח בה יד עסקינן\u0004 \u0005[אנו עוסקים]\u0006 לחייבו ולא במקרה אחר.","\u0003אמר להו\u0004 \u0005[להם,\u0006 ללומדי בית המדרש\u0005]\u0006 \u0003ר' חייא בר אבא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן:\u0004 הלכה זו שחייב תשלומי כפל בטוען טענת גנב בפקדון \u0003ב\u0004מקרה ש\u0003עומדת\u0004 בהמת הפקדון \u0003על אבוסה שנו.\u0004 שלא שלח בה יד אלא הניחה כמות שהיא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' חייא בר אבא:\u0004 מהם בדיוק דברי ר' יוחנן, האם \u0003דוקא בעומדת על אבוסה קאמר\u0004 \u0005[אמר]\u0006 שחייב, \u0003אבל\u0004 אם \u0003שלח בה יד\u0004 — \u0003קנה\u0004 אותה לעצמו, על ידי שליחות היד, שנעשה כגזלן עליה, \u0003ושבועה לא מהניא ביה\u0004 \u0005[מועילה בו]\u0006 \u0003כלום,\u0004 ואינו מתחייב כפל בגללה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו עומדת על אבוסה קאמר\u0004 \u0005[אמר]\u0006 שחייב כפל אם נשבע, וכל שכן אם שלח בה יד?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זו\u0004 עצמה \u0003לא שמעתי,\u0004 ואיני יכול לענות לך בשם ר' יוחנן מה דעתו, אבל \u0003כיוצא בה שמעתי,\u0004 ש\u0003אמר ר' אסי אמר ר' יוחנן:\u0004 שומר חינם \u0003הטוען טענת אבד ונשבע\u0004 שאבד, \u0003וחזר וטען טענת גנב ונשבע\u0004 שנגנב, ו\u0003באו עדים\u0004 והעידו ששיקר — \u0003פטור\u0004 מלשלם כפל על טענת הגניבה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003קנה\u0004 כבר את החפץ לעצמו \u0003בשבועה ראשונה,\u0004 ולכן אין מחשיבים את שבועתו השניה, וממילא אינו מתחייב כפל כטוען טענת גנב? והוא הדין במקרה ששלח בה יד, שקנאה בכך, ושוב אין שבועה מחייבת אותו.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 מכאן אין הוכחה, שכן אפשר לומר שטעם הדבר הוא לא משום שקנה את החפץ בשבועה הראשונה, אלא \u0003הואיל ויצא ידי בעלים בשבועה ראשונה,\u0004 פטור מלהישבע שוב על אותה תביעה.","ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 שכך היא דעת ר' יוחנן ש\u0003אמר ר' אבין אמר ר' אילעא אמר ר' יוחנן: הטוען טענת אבידה בפקדון ונשבע\u0004 על טענתו זו, \u0003וחזר וטען טענת גניבה\u0004 על פקדון זה \u0003ונשבע\u0004 על כך, \u0003ובאו עדים\u0004 והעידו ששיקר — \u0003פטור, הואיל ויצא ידי בעלים בשבועה ראשונה.\u0004 משמע שזהו הטעם לדבר.","ובענין זה \u0003אמר רב ששת\u0004 להיפך מדברי ר' חייא בר יוסף: \u0003הטוען טענת גנב בפקדון, כיון ששלח בו יד\u0004 — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003הכי קאמר רחמנא\u0004 \u0005[כך אמרה התורה]:\u0006 \u0003\"ונקרב בעל הבית אל האלהים אם לא שלח ידו...\u0004 אשר ירשיעון אלהים ישלם שנים לרעהו \u0003\",\u0004 לומר כי דין זה הוא דווקא במקרה שלא שלח יד בפקדון, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003שלח ידו\u0004 קודם לכן — \u0003פטור\u0004 מכפל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן\u0004 לרב ששת בשאלה: \u0003והלא\u0004 כל שומר חינם שטוען שנגנב ממנו החפץ \u0003שלש שבועות משביעין אותו\u0004 בית הדין: \u0003\"שבועה שלא פשעתי\u0004 (התרשלתי) \u0003בה\"\u0004 בשמירתה, ומתוך כך נגנבה, \u0003\"שבועה שלא שלחתי בה יד\",\u0004 ו\u0003\"שבועה שאינה ברשותי\". מאי לאו\u0004 \u0005[האם אין]\u0006 דין \u0003\"שבועה שלא שלחתי בה יד\" דומיא\u0004 \u0005[דומה]\u0006 ל\u0003\"שבועה שאינה ברשותי\", מה\u0004 בענין \u0003\"שבועה שאינה ברשותי\", כי מיגליא מילתא דאיתיה ברשותיה\u0004 \u0005[כאשר מתגלה הדבר ש\u0006הפקדון \u0005ישנו ברשותו]\u0006 — \u0003חייב, אף \"שבועה שלא שלחתי בה יד\", כי מיגליא מילתא\u0004 \u0005[כאשר מתגלה הדבר]\u0006 ש\u0003שלח בה יד\u0004 — \u0003חייב?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 אין להוכיח מכאן, שכן אפשר לומר שדין \u0003\"שבועה שלא שלחתי בה יד\" דומיא\u0004 \u0005[דומה]\u0006 לדין של \u0003\"שלא פשעתי בה\", מה \"שבועה שלא פשעתי בה\", כי מיגליא מילתא\u0004 \u0005[כאשר מתגלה הדבר]\u0006 ש\u0003פשע בה\u0004 ומשום כך נגנבה — \u0003פטור מכפל, אף \"שבועה שלא שלחתי בה יד\", כי מיגליא מילתא\u0004 \u0005[כאשר מתגלה הדבר]\u0006 ש\u0003שלח בה יד\u0004 — \u0003פטור מכפל\u0004 ואין מכאן ראיה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 שנינו בברייתא לעיל (בבא קמא סה,ב) שכאשר חייב השומר הטוען טענת גנב כפל, כאשר עדים מעידים שהחפץ בידו, אינו משלם חומש על שבועת השקר שנשבע. ויש לברר את סיבת הפטור מהחומש: האם \u0003ממון המחייבו כפל\u0004 הוא ה\u0003פוטרו מן החומש,\u0004 שמשום חיוב הממון בכפל הוא פטור מלשלם חומש, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שבועה המחייבתו כפל\u0004 היא זו ש\u0003פוטרתו מן החומש?\u0004","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 שבו אתה מוצא שיהיה הבדל מעשי בין שני ההסברים? — \u0003כגון שטען טענת גנב ונשבע\u0004 על כך, \u0003וחזר וטען\u0004 על אותו חפץ \u0003טענת אבד\u0004 שאותו חפץ לא נגנב באותה שעה אלא אבד \u0003ונשבע\u0004 על כך,"],["\u0003ובאו עדים אקמייתא\u0004 \u0005[על\u0006 טענתו \u0005הראשונה]\u0006 והעידו שבזמן שנשבע על טענתו שנגנב היה הפקדון אצלו, \u0003ו\u0004הוא עצמו \u0003הודה אבתרייתא\u0004 \u0005[על\u0006 טענתו \u0005האחרונה]\u0006 שלא אבד, ואז עולה השאלה \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 לענין לחייבו בחומש.","וצדדי השאלה: האם \u0003ממון המחייבתו כפל פוטרו מן החומש, ו\u0004במקרה זה \u0003הא איחייב ליה עילויה כפילא\u0004 \u0005[והרי\u0006 כבר \u0005התחייב לו עליו,\u0006 על ממון זה \u0005כפל]\u0006 וייפטר איפוא מחומש, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שבועה המחייבתו כפל\u0004 היא ה\u0003פוטרתו מן החומש, והא\u0004 \u0005[וזו]\u0006 ה\u0003שבועה בתרייתא\u0004 \u0005[האחרונה]\u0006 שהחפץ אבד \u0003הואיל\u0004 ש\u0003לא קא מחייבא ליה כפילא\u0004 \u0005[מחייבת אותו כפל],\u0006 שהרי לא טען טענת גנב — \u0003תחייביה חומשא\u0004 \u0005[תחייב אותו חומש]?\u0006","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנה: \u0003אמר לאחד מן השוק\u0004 שלא היה שומר פקדונו: \u0003\"היכן שורי שגנבת\"? והוא,\u0004 הנטען, \u0003אומר: \"לא גנבתי\",\u0004 אמר לו הטוען: \u0003\"משביעך אני\", ואמר\u0004 הנתבע: \u0003\"אמן\", והעדים מעידים אותו שגנבו\u0004 — \u0003משלם תשלומי כפל, ואם הודה מעצמו\u0004 שגנבו — \u0003משלם קרן וחומש ואשם.\u0004","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003עדים הוא דמחייבי ליה כפילא\u0004 \u0005[הם שמחייבים אותו כפל],\u0006 שאינו מתחייב כלל על ידי השבועה (שהרי אינו שומר הטוען טענת גנב) אלא על פי העדים כגנב, ובמקרה זה אם \u0003הודה מעצמו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 צריך לשלם חומש, \u0003אבל\u0004 אם \u0003הודה אחר\u0004 שהעידו עליו \u0003עדים\u0004 — \u0003לא\u0004 צריך לשלם חומש,","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003שבועה המחייבתו כפל\u0004 היא זו ש\u0003פוטרתו מן החומש, אמאי\u0004 \u0005[מדוע]\u0006 אם \u0003הודה אחר עדים לא\u0004 ישלם חומש? \u0003מכדי הא\u0004 \u0005[זו]\u0006 ה\u0003שבועה לא קא מיחייבא ליה כפילא\u0004 \u0005[אינה מחייבת אותו\u0006 לשלם \u0005כפל],\u0006 שרק שומר הטוען שנגנב ממנו משלם כפל, ואם כן \u0003תחייביה חומשא\u0004 \u0005[תחייב אותו\u0006 השבועה \u0005חומש]!\u0006","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003ממון המחייבו כפל\u0004 הוא זה ש\u0003פוטרתו מן החומש,\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהדבר תלוי בממון ולא בשבועה, ותיפטר בעייתו של רמי בר חמא לפוטרו מחומש.","ועוד בענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבינא: חומש וכפילא בתרי גברי\u0004 \u0005[חומש וכפל בשני אנשים],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הדין לענין חיוב חומש? ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 שבו שאל רבינא את שאלתו? — \u0003כגון שמסר שורו\u0004 לשמירה \u0003לשני בני אדם וטענו בו טענת גנב\u0004 שנגנב השור מידם, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003נשבע\u0004 שנגנב \u0003ו\u0004אחר כך \u0003הודה\u0004 מעצמו ששיקר, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003נשבע ו\u0004אחר כך \u0003באו עדים\u0004 והעידו בו ששיקר. ועתה נברר: \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003בחד גברא קפיד רחמנא\u0004 \u0005[באדם אחד מקפידה התורה]\u0006 ש\u0003לא משלם חומשא וכפילא\u0004 \u0005[\u0006גם \u0005חומש ו\u0006גם \u0005כפל],\u0006 ואולם במקרה הזה \u0003האי נשלם כפילא והאי נשלם חומשא\u0004 \u0005[זה ישלם כפל וזה ישלם חומש],\u0006 \u0003או דלמא עלויה חד ממונא קפיד רחמנא\u0004 \u0005[שמא על ממון אחד הקפידה התורה]\u0006 ש\u0003לא נשלם עלה חומשא וכפילא\u0004 \u0005[ישלם עליו חומש וכפל],\u0006 \u0003והכא נמי חד ממונא\u0004 \u0005[וכאן גם כן ממון אחד]\u0006 \u0003הוא?\u0004 שאלה זו לא נמצאה לה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא\u0004 שאלה מצד אחר: \u0003תרי חומשי\u0004 \u0005[שני חומשים]\u0006 \u0003או תרי כפילי בחד גברא\u0004 \u0005[שני כפלים באדם אחד],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם ישלם פעמיים על אותו ממון? ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 — \u0003שטען טענת אבד ונשבע ו\u0004אחר כך \u0003הודה\u0004 שלא אבד, \u0003וחזר וטען טענת אבד\u0004 על אותו חפץ \u0003ונשבע\u0004 שוב על טענתו זו \u0003והודה\u0004 שוב שלא אבד. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 במקרה \u0003כגון שטען טענת גנב ונשבע ובאו עדים\u0004 והעידו שהוא לקחו, \u0003וחזר וטען\u0004 שוב \u0003טענת גנב ונשבע ובאו עדים\u0004 והכחישוהו, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003תרי גווני ממונא קאמר רחמנא\u0004 \u0005[שני סוגי ממון,\u0006 תשלום, כפל וחומש, \u0005אמרה התורה]\u0006 ש\u0003לא נשתלמו עילוי חד ממונא\u0004 \u0005[ישלמו על ממון אחד],\u0006 \u0003והכא חד גוונא\u0004 \u0005[וכאן סוג אחד]\u0006 \u0003הוא,\u0004 שצריך לשלם פעמיים חומש או פעמיים כפל. \u0003או דלמא תרי ממונא אמר רחמנא\u0004 \u0005[שמא שתי\u0006 פעמים \u0005ממון,\u0006 תשלום, \u0005אמרה התורה]\u0006 ש\u0003לא לשתלמו עילוי חד ממונא\u0004 \u0005[ישלמו על ממון אחד],\u0006 \u0003והכא נמי תרי ממונא נינהו\u0004 \u0005[וכאן גם כן שתי\u0006 פעמים \u0005ממון הם]?\u0006","ומציעים פתרון לדבר: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר רבא:\u0004 אמר הכתוב: \u0003\"וחמשתיו יסף עליו\"\u0004 (ויקרא ה כד) בלשון רבים — \u0003התורה ריבתה חמישיות הרבה לקרן אחת, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שיכול לשלם כמה חומשים אפילו על קרן אחת.","ועוד דנים בנושא דומה: אם \u0003תבעוהו בעלים לשומר\u0004 חינם שיחזיר להם פקדונם וטען שנגנב ממנו \u0003ונשבע\u0004 שלא גנבו, \u0003ו\u0004אף שנפטר בכך \u0003שילם\u0004 מרצונו, \u0003ו\u0004אחר כך \u0003הוכר הגנב, כפל למי\u0004 שייך? \u0003אביי אמר: לבעל הפקדון\u0004 (הבעלים), \u0003רבא אמר: למי שהפקדון אצלו\u0004 (לשומר).","ומסבירים את השיטות: \u0003אביי אמר\u0004 שהוא שייך \u0003לבעל הפקדון, כיון דאטרחיה\u0004 \u0005[שהטריח אותו]\u0006 השומר \u0003בשבועה\u0004 ולא שילם לו מיד \u0003לא מקני ליה כפילא\u0004 \u0005[אינו מקנה לו את\u0006 זכות \u0005הכפל],\u0006 וזכות הכפל נשארת בידי הבעלים. \u0003רבא אמר למי שהפקדון אצלו, כיון\u0004 ש\u0003שילם\u0004 לבעלים \u0003מקני ליה כפילא\u0004 \u0005[מקנה לו\u0006 הבעלים את \u0005הכפל].\u0006","ומסבירים: \u0003וקא מיפלגי בדיוקא דמתניתין\u0004 \u0005[ו\u0006הם \u0005חלוקים בדיוק של\u0006 לשון \u0005משנתנו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המפקיד אצל חבירו בהמה או כלים ונגנבו או שאבדו,\u0004 ומשרצו להשביע את השומר על כך, אף שטענתו אמת \u0003שילם ולא רצה לישבע, שהרי אמרו שומר חנם נשבע ויוצא\u0004 (פטור), אם אחר כך \u0003נמצא הגנב\u0004 — \u0003משלם תשלומי כפל,\u0004 אם \u0003טבח\u0004 הגנב או \u0003מכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה,\u0004 ו\u0003למי הוא משלם?\u0004 — \u0003למי שהפקדון אצלו\u0004 (לשומר).","אם \u0003נשבע\u0004 השומר \u0003ולא רצה לשלם, ונמצא הגנב\u0004 אחר כך — \u0003משלם תשלומי כפל,\u0004 אם \u0003טבח\u0004 הגנב \u0003ומכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה, למי הוא משלם?\u0004 — \u0003לבעל הפקדון.\u0004","\u0003אביי דייק\u0004 את ההלכה \u0003מרישא\u0004 \u0005[מתחילת\u0006 המשנה\u0005],\u0006 ו\u0003רבא דייק מסיפא\u0004 \u0005[מסופה].\u0006 ומפרטים: \u0003אביי דייק מרישא\u0004 \u0005[מתחילתה],\u0006 \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003שילם\u0004 השומר \u0003ולא רצה לישבע\u0004 — משלם הגנב לשומר את הכפל וארבעה וחמישה. ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003לא רצה לישבע,\u0004"],["\u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נשבע\u0004 — \u0003אף על פי ששילם\u0004 לאחר מכן, \u0003למי משלם\u0004 הגנב? — \u0003לבעל הפקדון.\u0004","ואילו \u0003רבא דייק מסיפא\u0004 \u0005[מסופה]\u0006 של המשנה באופן זה: \u0003נשבע\u0004 השומר \u0003ולא רצה לשלם\u0004 — משלם (הגנב) לבעלים, \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003לא רצה לשלם, הא\u0004 \u0005[הרי]\u0006 אם \u0003שילם\u0004 — \u0003אף על פי שנשבע\u0004 קודם לכן, \u0003למי משלם\u0004 הגנב? — \u0003למי שהפקדון אצלו,\u0004 כלומר, לשומר.","ומעירים: \u0003לאביי קשיא סיפא\u0004 \u0005[קשה\u0006 הדיוק מן \u0005הסוף]!\u0006 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך אביי, הכי קתני\u0004 \u0005[כך שנה],\u0006 כך צריכים להבין את סוף המשנה: \u0003נשבע, ולא רצה לשלם קודם השבועה אלא\u0004 רק \u0003לאחר השבועה,\u0004 כלומר, ואכן כך עשה ששילם לאחר שנשבע, במקרה זה \u0003למי משלם?\u0004 — \u0003לבעל הפקדון\u0004 ולא לשומר. מצד שני \u0003לרבא קשיא רישא\u0004 \u0005[קשה\u0006 הדיוק של \u0005ההתחלה]!\u0006 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא, הכי קתני\u0004 \u0005[כך שנה],\u0006 כך צריך להבין את תחילת המשנה: \u0003שילם, ולא רצה לעמוד בשבועתו אלא שילם,\u0004 כלומר, שילם לאחר שנשבע, \u0003למי משלם\u0004 הגנב? — \u0003למי שהפקדון אצלו.\u0004","ועוד בעיה הקשורה למעמדו של השומר ביחס לדבר שנגנב ממנו: אם \u0003תבעוהו בעלים לשומר, ונשבע\u0004 השומר שלא היה אשם בחסרון החפץ אלא נגנב ממנו, \u0003והוכר\u0004 אחר כך \u0003הגנב,\u0004 ואז \u0003תבעו\u0004 ה\u0003שומר\u0004 לגנב \u0003והודה\u0004 לו שאכן גנב, אחר כך \u0003תבעוהו בעלים\u0004 את הגנב \u0003וכפר, והביאו עדים\u0004 שאכן גנב, \u0003מי\u0004 \u0005[האם]\u0006 \u0003נפטר הגנב\u0004 מן הכפל \u0003בהודאת שומר\u0004 (בהודאה שהודה לשומר), כדין כל מודה בקנס? האם אומרים אנו שעדיין השומר נחשב כבעל דברים של הגנב (למרות שנשבע לבעלים ונפטר בכך) והגנב שנשבע לו נחשב ככל מודה בקנס, ונפטר מן הקנס, \u0003או לא נפטר הגנב בהודאת שומר?\u0004","\u0003אמר רבא: אם באמת נשבע,\u0004 כלומר, אם מתברר עתה בעדות העדים על הגנב כי השומר נשבע באמת, ואדם נאמן הוא שכדבריו כך היה — יש להניח כי נוח לבעלים שישתדל לדאוג למענם בגניבה זו, ולכן \u0003נפטר הגנב בהודאת שומר,\u0004 \u0003אם בשקר נשבע,\u0004 וכגון שלא נשבע שנגנב, אלא שמתה מאליה, ומתברר כי שיקר בשבועתו — \u0003לא נפטר הגנב בהודאת שומר.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 באותו ענין: אם \u0003עמד\u0004 השומר \u0003לישבע בשקר ולא הניחוהו\u0004 ולבסוף לא נשבע, \u0003מהו\u0004 הדין, האם נחשב הוא כאילו כבר נשבע בפועל (שהרי לכך התכוון) והודאת הגנב לא נחשבת כהודאה, או כיון שלא נשבע בפועל הריהו נשאר בעמדתו והודאת הגנב נחשבת הודאה? שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה. ומעירים: \u0003רב כהנא מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את בעייתו של רבא, בלשון שאמרנו. ואילו \u0003רב טביומי מתני\u0004 \u0005[היה שונה]\u0006 אותה בלשון אחרת, וכך לדבריו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם באמת נשבע נפטר הגנב בהודאתו לשומר, אך אם \u0003נשבע לשקר, מהו\u0004 האם על ידי כך נפטר משמירתו, או שמא עדיין הוא נחשב כשומר? אף לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","ועוד בעיה מקבילה: \u0003תבעוהו בעלים לשומר ושילם, ו\u0004אחר כך \u0003הוכר הגנב,\u0004 ואז \u0003תבעוהו בעלים\u0004 לגנב \u0003והודה\u0004 להם שגנב, ואחר כך \u0003תבעו שומר וכפר\u0004 לו, \u0003והביא\u0004 השומר \u0003עדים\u0004 שאותו אדם באמת גנב, האם \u0003נפטר\u0004 ה\u0003גנב\u0004 מתשלום הכפל לשומר \u0003בהודאת בעלים\u0004 (בהודאה שהודה לבעלים), \u0003או לא?\u0004","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים],\u0006 כי \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 ה\u0003שומר לבעלים: אתון\u0004 \u0005[אתם]\u0006 \u0003כיון דשקליתו לכו דמי אסתליקתו לכו מהכא\u0004 \u0005[שלקחתם לכם\u0006 את \u0005הכסף\u0006 שלכם ממני בכך \u0005הסתלקתם לכם מכאן]\u0006 ואין לכם מעתה שום קשר לפקדון ועכשיו אני נחשב כבעליו של הדבר הגנוב, והכפל שלי הוא, ולכן אין ההודאה של הגנב לכם נחשבת. \u0003או דלמא מצי אמרי ליה\u0004 \u0005[שמא יכולים\u0006 הבעלים \u0005לומר לו]:\u0006 \u0003כי היכי דאת עבדת לן מילתא\u0004 \u0005[כמו שאתה עשית בשבילנו דבר]\u0006 של טובה, ושילמת לנו, \u0003אנן נמי עבדינן\u0004 \u0005[גם אנו עשינו]\u0006 \u0003לך\u0004 טובה, \u0003טרחינן בתר גנבא\u0004 \u0005[וטרחנו\u0006 לחפש \u0005אחר גנב],\u0006 ולכן לא הסתלקנו מן הפקדון, \u0003שקלנא אנן דידן\u0004 \u0005[אנו ניקח את שלנו]\u0006 את הפקדון מיד הגנב, \u0003ושקול את דידך\u0004 \u0005[ותיקח אתה את שלך],\u0006 את מה ששילמת לנו, ונמצא הגנב נפטר מן הכפל בהודאה לבעלים? שאלה זו לא נמצאה לה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 נחלקו אמוראים בבעיה הבאה: אם \u0003נגנבה\u0004 בהמה של פקדון \u0003באונס, והוכר הגנב\u0004 ובמקרה זה השומר פטור מתשלום, בין אם הוא שומר חינם ובין אם הוא שומר שכר, מה הדין? \u0003אמר אביי: אם שומר חנם הוא\u0004 — הרי אם \u0003רצה\u0004 השומר \u0003עושה עמו,\u0004 עם הגנב, \u0003דין,\u0004 שמשלם לבעלים, וחוזר ותובע מן הגנב. ואם \u0003רצה נשבע\u0004 השומר לבעלים שלא היה חייב בדבר, שהרי נגנבה ממנו הבהמה, והבעלים יתבעו מן הגנב. \u0003ואם שומר שכר הוא\u0004 — \u0003עושה עמו,\u0004 עם הגנב, \u0003דין,\u0004 \u0003ואינו נשבע\u0004 ונפטר בכך, שאף זה בכלל מה שמוטל עליו כשומר שכר. \u0003רבא אמר: אחד זה ואחד זה,\u0004 בין שומר חינם ובין שומר שכר — \u0003עושה עמו דין ואינו נשבע.\u0004","ושואלים: \u0003לימא, פליגא\u0004 \u0005[האם לומר\u0006 ש\u0005חולקת]\u0006 הלכה זו שאמר רבא על זו של \u0003רב הונא בר אבין?\u0004 ש\u0003שלח רב הונא בר אבין\u0004 הלכה זו: \u0003נגנבה באונס והוכר הגנב, אם שומר חנם הוא\u0004 — \u0003רצה עושה עמו דין, רצה נשבע, ואם שומר שכר הוא\u0004 — \u0003עושה עמו דין ואינו נשבע?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא: הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בדברי רב הונא בר אבין, \u0005במה אנו עוסקים]\u0006 — \u0003כגון שקדם\u0004 השומר \u0003ונשבע.\u0004 ושואלים: כיצד אפשר לפרש כן? \u0003והא רצה עושה עמו דין, רצה נשבע קאמר\u0004 \u0005[הוא אומר],\u0006 ומשמע שעדיין לא נשבע השומר! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 קדם השומר ונשבע, אם \u0003רצה שומר חנם עומד בשבועתו\u0004 ואינו משלם לבעלים, והם יתבעו את הגנב, \u0003רצה עושה עמו דין.\u0004","\u0003רבה זוטי\u0004 \u0005[הקטן]\u0006 \u0003בעי לה הכי\u0004 \u0005[שאל אותה כך]:\u0006 אם \u0003נגנבה באונס, והחזיר גנב\u0004 את האבידה והניחה \u0003בבית\u0004 ה\u0003שומר, ומתה\u0004 אחר כך \u0003בפשיעה, מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון\u0004 ש\u0003נגנבה\u0004 מבית הגנב \u0003באונס\u0004 — \u0003כליא ליה\u0004 \u0005[כלתה לו\u0006 כבר\u0005]\u0006 \u0003שמירתו\u0004 ושוב אין לו אחריות על הבהמה ואינו חייב גם על פשיעה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דהדרה\u0004 \u0005[שהחזיר אותה]\u0006 הגנב — \u0003הדרה\u0004 \u0005[חזרה]\u0006 \u0003לשמירתו,\u0004 ושומר חינם חייב במקרה של פשיעה? גם לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","הפקיד אדם חפץ ביד חבירו ואחר כך בא אליו ושאל: \u0003\"היכן פקדוני\"?\u0004 ו\u0003אמר לו\u0004 השומר: \u0003\"אבד\",\u0004 אמר לו המפקיד: \u0003\"משביעך אני\u0004 על כך שכדבריך היה הדבר \u0003\",\u0004 \u0003ואמר\u0004 השומר: \u0003\"אמן\",\u0004 ויש בזה איפוא שבועה, \u0003והעדים מעידים אותו\u0004 את השומר \u0003שאכלו,\u0004 שהשתמש בו הוא עד שכלה ולא שאבד ממנו — \u0003משלם קרן,\u0004 כלומר, משלם את דמי הפקדון. אם \u0003הודה מעצמו\u0004 בלי עדים שהוא גנבו ונשבע לשקר — \u0003משלם קרן וחומש ו\u0004מביא קרבן \u0003אשם.\u0004","ומקרה מקביל: הפקיד אצל חבירו ושאל אותו: \u0003\"היכן פקדוני\"? אמר לו\u0004 השומר: \u0003\"נגנב\",\u0004 אמר לו המפקיד: \u0003\"משביעך אני\", ואמר\u0004 השומר: \u0003\"אמן\", והעדים מעידים אותו,\u0004 את השומר, \u0003שגנבו\u0004 — \u0003משלם תשלומי כפל,\u0004 כדין הטוען טענת גנב ונמצא שהוא גנבו. אם \u0003הודה מעצמו\u0004 שהוא גנבו ונשבע לשקר — \u0003משלם קרן חומש ואשם.\u0004","ומכאן לדינים אחרים: \u0003הגוזל את אביו\u0004 ותבעו אביו על כך \u0003ונשבע לו\u0004 שלא גזלו, \u0003ומת\u0004 האב, והבן עושה תשובה ומודה שגזל ושנשבע לשקר, אבל בפועל הריהו יורש (לבדו או עם אחיו) את נכסי אביו, ובכלל זה גם הגזילה שצריך להשיב, וכיצד יעשה? — \u0003הרי זה משלם קרן וחומש ואשם לבניו או לאחיו\u0004 של האב שהם יורשיו, \u0003ואם אינו רוצה\u0004 לשלם, \u0003או שאין לו\u0004 — \u0003לוה\u0004 על חשבון גזילה זו \u0003ובעלי חוב באין ונפרעים\u0004 מדמי הגזילה.","\u0003האומר לבנו\u0004 בנדר: \u0003\"קונם\u0004 ש\u0003אי\u0004 (אין) \u0003אתה נהנה משלי\", אם מת\u0004 האב — \u0003ירשנו\u0004 בנו, שאחרי מותו שוב אין זה שלו."],["אבל אם אסר את נכסיו על בנו במפורש \u0003בחייו ובמותו,\u0004 הרי אף \u0003אם מת\u0004 — \u0003לא יירשנו,\u0004 שאינו רשאי ליהנות מן הנכסים, \u0003ויחזיר,\u0004 כלומר, יתן את חלקו בירושה \u0003לבניו או לאחיו, ואם אין לו\u0004 מה לאכול כאשר הוא מחזיר — \u0003לוה\u0004 מאחרים ויתפרנס מכסף זה \u0003ובעלי חוב באים ונפרעים\u0004 את חובם מחלקו בירושה, שהרי עליהם לא נאסר.","על האמור במשנה שהגוזל את אביו משלם קרן וחומש ליורשי אביו \u0003אמר רב יוסף: אפילו לארנקי\u0004 (ארנק, קופה) \u0003של צדקה\u0004 יתן את הסכום אם לא מצא יורש לאביו או שאינו רוצה לתת לו. \u0003אמר רב פפא: וצריך שיאמר\u0004 כאשר הוא נותן לצדקה, או למטרה אחרת: \u0003\"זה גזל אבי\"\u0004 ואותו הוא מחזיר.","ושואלים לגופה של המשנה: \u0003אמאי\u0004 \u0005[מדוע]\u0006 צריך לעשות כן ולהוציא מידיו את הגזילה? \u0003נמחליה לנפשיה\u0004 \u0005[שימחול אותו,\u0006 את הגזל, \u0005לעצמו],\u0006 שכיון שהוא עצמו היורש, יכול הוא למחול אותו! \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו]\u0006 במשנה לעיל (בבא קמא קג,א) בענין גזלן שנשבע ולאחר מכן הודה: \u0003מחל לו על הקרן ולא מחל לו על החומש? אלמא\u0004 \u0005[מכאן]\u0006 שהחפץ הגזול \u0003בר\u0004 \u0005[בן]\u0006 \u0003מחילה הוא\u0004 ומדוע לא ימחל לעצמו!","\u0003אמר ר' יוחנן, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זאת\u0006 המשנה שלמעלה\u0005]\u0006 היא שיטת \u0003ר' יוסי הגלילי\u0004 שיכול למחול, \u0003הא\u0004 \u0005[זאת\u0006 משנתנו\u0005]\u0006 היא שיטת \u0003ר' עקיבא\u0004 שאינו יכול למחול; ומה עניינה של מחלוקתם?","— \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"ואם אין לאיש גאל להשיב האשם\u0004 אליו האשם המושב לה' לכהן\u0003\"\u0004 (במדבר ה, ח) — \u0003וכי יש אדם בישראל שאין לו גואלים,\u0004 קרובים היורשים אותו? הרי כל אדם מישראל הוא מצאצאי יעקב אבינו, וממילא בהכרח יש לו קרוב מבית אביו שיירש אותו! \u0003אלא בגזל הגר הכתוב מדבר,\u0004 שכיון שאינו מתייחס עוד למשפחתו הקודמת, ומצד אחר אינו בן של ישראל, ייתכן שלא יהיו לו יורשים כלל ועל כך אמרה התורה שישיב את הגזילה של הגר שמת לכהנים.","\u0003הרי שגזל הגר ונשבע לו\u0004 שלא גזלו, \u0003ושמע שמת הגר, והיה מעלה כספו\u0004 של תשלום הקרן והחומש לשלמם לכהנים \u0003ו\u0004כן את קרבן \u0003אשמו לירושלים\u0004 על מנת להשיב לכהן את הכסף ולהקריב קרבן, \u0003ופגע\u0004 (פגש) \u0003באותו הגר,\u0004 שהתברר שלא מת, \u0003וזקפו עליו במלוה,\u0004 כלומר, לא שילם לו מיד אלא שהגר השאיר בידו את הגזילה כמילווה, \u0003ו\u0004אחר כך \u0003מת\u0004 הגר והרי כל נכסיו הינם הפקר — \u0003זכה הלה\u0004 (הגזלן) \u0003במה שבידו,\u0004 שהרי שוב אין תובעים לממון זה, שכבר אינו נחשב גזילה להשיבה לכהן. אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר: אין לו\u0004 לגזלן \u0003תקנה עד שיוציא גזילו מתחת ידו.\u0004","ור' יוחנן מפרש ש\u0003ל\u0004שיטת \u0003ר' יוסי הגלילי, לא שנא לנפשיה\u0004 \u0005[אינו שונה\u0006 המוחל \u0005לעצמו],\u0006 כגון גזל אביו או גזל הגר, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 המוחל \u0003לאחרים\u0004, כלומר, סתם נגזל למי שגזל ממנו — \u0003מצי מחיל\u0004 \u0005[יכול למחול]\u0006 על הגזילה, \u0003ול\u0004שיטת \u0003ר' עקיבא, לא שנא\u0004 \u0005[שונה]\u0006 \u0003לאחרים ולא שנא לנפשיה\u0004 \u0005[שונה לעצמו]\u0006 — \u0003לא מצי מחיל\u0004 \u0005[אינו יכול למחול].\u0006","\u0003ו\u0004צריכים לומר לדרך זו ש\u0003ל\u0004דעת \u0003ר' יוסי, הוא הדין\u0004 ש\u0003אפילו לא זקפו\u0004 הנגזל את הגזל \u0003במלוה\u0004 הדין כן, שאם רק במקרה שזקפו — הרי אין זה משום מחילה. \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 בברייתא \u0003זקפו עליו במלוה\u0004 — הרי זה בא \u0003להודיעך כחו\u0004 של \u0003ר' עקיבא,\u0004 ש\u0003אפילו זקפן עליו\u0004 הנגזל \u0003במלוה,\u0004 ולכאורה הרי זה נחשב כאילו החזיר לו, ומעתה הוא רק חייב לו חוב כספי בלבד, מכל מקום \u0003אין לו תקנה עד שיוציא\u0004 את ה\u0003גזילה מתחת ידו.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש את המחלוקת, \u0003ל\u0004שיטת \u0003ר' יוסי הגלילי\u0004 שהוא השונה במשנה לעיל \"מחל לו על הקרן\" — \u0003לשמעינן\u0004 \u0005[שישמיע לנו]\u0006 באותה משנה שיכול למחול \u0003לנפשיה\u0004 \u0005[לעצמו]\u0006 \u0003ו\u0004מכאן היינו למדים ש\u0003כל שכן\u0004 שהוא מוחל \u0003לאחרים,\u0004 ו\u0003ל\u0004שיטת \u0003ר' עקיבא\u0004 שאתה סבור שהוא התנא של משנתנו — \u0003לשמעינן\u0004 \u0005[שישמיע לנו]\u0006 \u0003לאחרים דלא מצי מחיל\u0004 \u0005[שאינו יכול למחול],\u0006 \u0003ו\u0004היינו למדים ש\u0003כל שכן לנפשיה דלא מצי מחיל\u0004 \u0005[לעצמו שאינו יכול למחול]!\u0006","\u0003אלא אמר רב ששת: הא והא\u0004 \u0005[זו וזו]\u0006 גם משנתנו וגם המשנה האמורה לעיל כדברי \u0003ר' יוסי הגלילי,\u0004 ומה ששאלנו על האמור במשנתנו מדוע אינו יכול למחול לעצמו, ההסבר לכך הוא ש\u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוסי הגלילי דמצי מחיל\u0004 \u0005[שיכול למחול]\u0006 על הגזל — הרי זה דווקא \u0003לאחרים\u0004 וכדברי אותה משנה, \u0003אבל לנפשיה\u0004 \u0005[לעצמו]\u0006 \u0003לא מצי מחיל\u0004 \u0005[יכול למחול],\u0006 וכדברי משנתנו. \u0003אלא אמאי\u0004 \u0005[מדוע]\u0006 \u0003זכה הלה\u0004 שגזל את הגר \u0003במה שבידו?\u0004 — \u0003משום\u0004 ש\u0003זקפן עליו במלוה\u0004 ושוב אין זה נחשב כגזילה אלא כסתם חוב שחייב לגר.","\u0003רבא אמר: הא והא\u0004 \u0005[זו וזו],\u0006 כלומר, גם משנתנו וגם המשנה האמורה לעיל כדעת \u0003ר' עקיבא,\u0004 ומה ששנינו במשנה לעיל שיכול למחול הוא משום ש\u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' עקיבא\u0004 ש\u0003לא מצי מחיל\u0004 \u0005[יכול למחול]\u0006 — הרי זה דווקא \u0003לנפשיה\u0004 \u0005[לעצמו],\u0006 כפי שאמר בגזל הגר, \u0003אבל לאחרים מצי מחיל\u0004 \u0005[יכול למחול].\u0006"],["על הסבר זה של רבא תמהים: \u0003מכלל\u0004 הדברים אתה למד כי \u0003ר' יוסי הגלילי סבר\u0004 \u0005[סובר]\u0006 ש\u0003אפילו לנפשיה נמי מצי מחיל\u0004 \u0005[לעצמו גם כן יכול למחול]?\u0006 \u0003אלא\u0004 אם כן \u0003גזל הגר דקאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 שדינו \u0003נתינה לכהנים היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 שהרי בכל מקרה שבו מת הגר יכול הגזלן למחול לעצמו!","\u0003אמר רבא\u0004 בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשגזל את הגר ונשבע לו\u0004 שלא גזלו, \u0003ומת הגר, והודה לאחר מיתה\u0004 שאכן גזלו, \u0003דבעידנא דאודי\u0004 \u0005[שבזמן שהודה\u0006 על כך\u0005]\u0006 \u0003קנאו השם\u0004 את תשלום הקרן והחומש \u0003ונתנו לכהנים,\u0004 ואז זוכים בו הכהנים ואינו יכול למחול. אבל אם הודה לפני מיתת הגר, הרי הגזלן מוחל לעצמו לאחר שזכה בדבר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבינא: גזל הגיורת, מהו\u0004 דינו לענין נתינה לכהנים את תשלום גזילתה? וצדדי השאלה: האם \u0003\"איש\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 כנאמר \"ואם אין לאיש גואל\" (במדבר ה, ח), וללמדנו: איש דווקא \u0003ולא אשה,\u0004 ואם מתה אין הכהנים זוכים בו, \u0003או דלמא אורחיה דקרא\u0004 \u0005[שמא דרכו של הכתוב]\u0006 \u0003הוא\u0004 לומר בלשון זכר ואינו דווקא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אהרן לרבינא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעייתך, ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 בענין זה: \u0003\"איש\"\u0004 שנאמר בכתוב — \u0003אין לי\u0004 מלשון זה \u0003אלא איש, אשה מנין\u0004 שדינה שווה לענין זה? \u0003כשהוא אומר: \"המושב\"\u0004 (במדבר ה, ח) — \u0003הרי כאן שנים,\u0004 בין איש בין אישה,","\u0003אם כן מה תלמוד לומר \"איש\"?\u0004 לומר כך: \u0003איש\u0004 — \u0003אתה צריך לחזור אחריו אם יש לו גואלים\u0004 (שהרי יתכן שהוליד בנים היורשים אותו) \u0003אם לאו\u0004 \u0005[לא],\u0006 אבל אם היה גר \u0003קטן\u0004 — \u0003אי\u0004 (אין) \u0003אתה צריך לחזור אחריו,\u0004 שהרי \u0003בידוע שאין לו גואלין,\u0004 שכן ככל גר אין לו קרובים מצד הוריו, ובודאי אין לו בנים שהרי קטן הוא.","ובענין זה של גזל הגר הניתן לכהנים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"\u0004האשם המושב \u0003לה' לכהן\"\u0004 (במדבר ה, ח) בא לומר: \u0003קנאו השם, ונתנו לכהן שבאותו משמר\u0004 של כהנים שהיה משרת באותה שעה. ויש לברר: \u0003אתה אומר\u0004 שנותנו \u0003לכהן שבאותו משמר, או אינו אלא\u0004 שנותנו \u0003לכל כהן שירצה?\u0004 — \u0003כשהוא אומר \"מלבד איל הכפרים אשר יכפר בו עליו\"\u0004 (במדבר ה, ח), \u0003הרי לכהן שבאותו משמר הכתוב מדבר,\u0004 כי שכשם שאיל האשם שמביא הגזלן ניתן לכהן המשרת במשמר זה ולא לכל כהן, שהרי הוא המקריב אותו, אף הגזילה עצמה כן דינה.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרי שהיה\u0004 זה שהיה \u0003גוזל\u0004 את הגר שמת, \u0003כהן, מנין שלא יאמר: הואיל ו\u0004גזל הגר \u0003יוצא לכהנים והרי הוא\u0004 עתה \u0003תחת ידי, יהא שלי? ו\u0004לכאורה \u0003דין\u0004 (קל וחומר) \u0003הוא\u0004 בדבריו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשל אחרים\u0004 שגזלו את הגר \u0003הוא זוכה, בשל עצמו,\u0004 בגזילת הגר שבידיו, \u0003לא כל שכן?!\u0004","\u0003ר' נתן אומר\u0004 קל וחומר זה \u0003בלשון אחר:\u0004 \u0003ומה דבר שאין לו\u0004 לכהן \u0003חלק בו עד שיכנס ברשותו\u0004 (כגון תרומה), \u0003כשיכנס לרשותו,\u0004 כהן אחר \u0003אינו יכול להוציאו מידו,\u0004 גזילת הגר שהיא \u0003דבר שיש לו\u0004 לכהן הגוזל \u0003חלק בו,\u0004 ככל אנשי משמרו, \u0003עד שלא יכנס ברשותו, משנכנס לרשותו,\u0004 כלומר, במקרה בו הגזילה כבר בידיו, \u0003אינו דין\u0004 ש\u0003אין אחר יכול להוציאו מידו?\u0004","ואת הקל וחומר הזה יש לדחות: \u0003לא, אם אמרת בדבר\u0004 כגון תרומות ומעשרות \u0003שאין לו חלק בו,\u0004 שאין יכולים להוציא מידו, משום \u0003שכשם שאין לו\u0004 לכהן זה \u0003חלק בו כך אין לאחרים חלק בו, תאמר בגזל\u0004 הגר שמת — \u0003שכשם שיש לו\u0004 לכהן הגוזל \u0003חלק בו\u0004 ככהן, \u0003כך יש ל\u0004כהנים \u0003אחרים חלק בו? אלא\u0004 הכהן הגוזל את הגר \u0003גזילו יוצא מתחת ידו ומתחלק לכל אחיו הכהנים.\u0004","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואיש את קדשיו לו יהיו\"\u0004 (שם י), משמע שכהן אינו צריך לתת לאחרים את קודשיו, שהוא עצמו מביא, ואם כן, כשם שהוא זוכה בבשר קרבן האשם שמביא על גזל הגר מדוע לא יזכה גם בגזל הגר עצמו? ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בכהן טמא\u0004 שאינו ראוי להקריב את קרבן איל האשם, ולכן אף אינו זוכה בבשרו לעצמו, וממילא גם לא בגזילה.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בכהן טמא\u0004 מדובר בברייתא זו, איך אפשר לומר על גזילת הגר שהיא \u0003דבר שיש לו חלק בו? מי אית ליה\u0004 \u0005[האם יש לו\u0006 חלק בו\u0005]?!\u0006 \u0003אלא\u0004 לא בכהן טמא מדובר בה, ומכל מקום אינו זוכה בגזילה משום טעם אחר, שכן \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"לכהן\" \"לכהן\" משדה אחוזה.\u0004 שהוא שדה אחוזה של אדם מישראל אשר הקדישו לה', ואם קנה (\"גאל\") אותו אדם אחר, הרי בשנת היובל אין השדה חוזר לבעלים הראשונים אלא ניתן לכהנים.","ובענין זה נאמרה הלכה ממנה למדנו לענייננו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \"והיה השדה בצאתו ביובל קודש לה', כשדה החרם לכהן תהיה אחוזתו\" (ויקרא כז, כא), \u0003\"אחזתו\" מה תלמוד לומר?\u0004 שדי היה לומר: \"כשדה החרם לכהן תהיה\"! בא הדבר ללמד: \u0003מנין לשדה היוצאה לכהנים ביובל וגאלה\u0004 (קנאה) \u0003אחד מן הכהנים\u0004 לפי היובל, \u0003מנין שלא יאמר\u0004 אותו כהן ביובל: \u0003הואיל ויוצאה\u0004 השדה \u0003לכהנים ביובל והרי היא\u0004 עתה \u0003תחת ידי\u0004 ברשותי שהרי הוא קנה את השדה \u0003תהא שלי? ו\u0004לכאורה","\u0003דין\u0004 (קל וחומר) \u0003הוא;\u0004 אם \u0003בשל אחרים אני זוכה, בשל עצמי לא כל שכן?!\u0004","— \u0003תלמוד לומר:\u0004 \u0003\"כשדה החרם לכהן תהיה אחזתו\"\u0004 (במדבר ה, ח), לומר \u0003אחוזה שלו,\u0004 של הכהן, שירש מאביו היא זו שתהיה לו, \u0003ואין זו\u0004 שקנה \u0003שלו, הא כיצד?\u0004 — \u0003יוצאה\u0004 (יוצאת) \u0003מתחת ידו ומתחלקת לכל אחיו הכהנים.\u0004","אגב הדברים הללו מביאים עוד בענין זכות הכהן בקרבנותיו: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין לכהן ש\u0004הוא \u0003בא ומקריב קרבנותיו\u0004 שלו \u0003בכל עת ובכל שעה שירצה,\u0004 ואינו צריך לחכות עד שיגיע משמרו? — \u0003תלמוד לומר: \"ובא בכל אות נפשו\u0004 אל המקום אשר יבחר ה', \u0003ושרת\"\u0004 וגו' (דברים יח, ו–ז),","\u0003ומניין שעבודתה,\u0004 כלומר, אכילת בשרה של אותה בהמה \u0003ועורה שלו\u0004 הם? — \u0003תלמוד לומר: \"ואיש את קדשיו לו יהיו\"\u0004 (במדבר ה, י), \u0003הא\u0004 \u0005[זה]\u0006 \u0003כיצד?\u0004 — \u0003אם היה\u0004 כהן זה \u0003בעל מום\u0004 — \u0003נותנה לכהן\u0004 אחר \u0003שבאותו משמר\u0004 להקריבה, \u0003ו\u0004אולם \u0003עבודתה ועורה שלו.\u0004"]]};
